INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993936896', 'Kit Tesoura BC701 E 2 Pinças Gold Sobrancelha Inox Mundial', 'Oii, é um prazer ter você aqui! Quer sobrancelhas perfeitas em poucos minutos, sem sair de casa? O Kit Tesoura BC701 E 2 Pinças Gold Sobrancelha Inox Mundial é o aliado ideal para quem busca praticidade e precisão no cuidado com o olhar. Com ele, você garante acabamento profissional com ferramentas fáceis de usar e super eficientes! O que é: - Kit Tesoura BC701 E 2 Pinças Gold Sobrancelha Inox. - Marca: Mundial. - Linha: Make Up e gold. - Uso seguro. O que tem: - Tesoura BC701. - Pinça 381P. - Pinça 380P. - Aço Inoxidável. - Afiação de fabrica. - Esterilização em Autoclave e Estufa O que faz: - Corte suave e eficiente, sem danificar os fios e proporcionando um acabamento profissional. - Design confortável permitindo que você tenha total controle na hora de aparar as sobrancelhas. - Modela, corta e remove pelos com facilidade, proporcionando sobrancelhas bem definidas e alinhadas. Indicado para: - Pessoas que buscam uma tesoura precisa e fácil de usar para aparar as sobrancelhas. - Profissionais de beleza. - Uso profissional ou pessoal. Modo de uso: - Use a tesoura para aparar os fios mais longos, respeitando o formato natural das sobrancelhas. - Utilize as pinças para remover os fios fora do contorno desejado. Precauções de uso: - Evite cortar muito perto da pele para não causar irritações. - Mantenha a tesoura limpa e seca após o uso para preservar as lâminas afiadas. - Não utilize em áreas inflamadas ou com feridas. Com acabamento preciso, fácil manuseio e a qualidade que só a Mundial oferece, esse kit é perfeito para deixar suas sobrancelhas sempre impecáveis. Garanta o seu agora e eleve sua rotina de cuidados com beleza e praticidade! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 99.98, 79.98, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhp-m97fjaix3auf30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F23993936896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44750276825', 'Pedal Royal Ciclo Free Sport Nylon Preto Rosca Grossa 9/16', 'O Pedal Free Sport da Royal Ciclo é uma excelente opção para ciclistas que buscam leveza, resistência e segurança em cada pedalada. Fabricado em nylon de alta durabilidade, conta com superfície texturizada e travas que garantem firmeza ao calçado, evitando escorregões durante o uso. O modelo possui refletor lateral integrado, oferecendo mais visibilidade e segurança em pedaladas noturnas, conforme normas internacionais. Seu eixo em aço é resistente e de fácil instalação, ideal para bicicletas aro 24”, 26” e 29”, tanto MTB quanto passeio. Especificações Técnicas: • Modelo: Free Sport • Marca: Royal Ciclo • Material base: Nylon (PP copolímero) • Eixo: Aço conformado • Medida do eixo: 9/16” • Cor: Preto • Medidas: 95mm (comprimento) x 101mm (largura) x 21mm (altura) • Peso aproximado: 290,66g o par • Indicação: Bicicletas aro 24”, 26” e 29” – MTB e passeio • Refletor de segurança integrado • Design moderno com travas antiderrapantes', 19.9, 16.87, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mgcog28d0umkd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F44750276825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
