INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198142899', 'Limpa Costado 5L Nautispecial', 'Limpa Costado 5L Nautispecial Tira o amarelado da fibra e gelcoat. - Desenvolvido exclusivamente para remoção de oxidação (amarelamento) do costado da lancha; - Remove toda a impregnação sem atacar a fibra e o gelcoat; - Para utilizar somente em casco de cor branca da linha d´água para baixo; - Tensoativos biodegradáveis. Limpa Costado foi desenvolvido exclusivamente para remoção de oxidação (amarelamento) do costado das embarcações da linha d´água para baixo, que navegam em rios, lagos, represa, águas barrentas e mares. NÃO USAR em vidros, policarbonato e acrílicos, pois causa manchas irreversíveis. Remove toda a impregnação sem atacar a fibra e o gelcoat. Para utilizar somente em casco de cor branca da linha d´água para baixo. Tensoativos biodegradáveis. Embalagem de 5 litros', 115.0, 115.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfhp-m9iy8otdyrkmc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1511959705%2F20198142899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598664246', 'Capa Case Capinha MagSafe Preta para iPhone 16E Gshield - Proteção com Conexão Magnética', 'A Capa MagSafe Preta para iPhone 16E, da Gshield, foi projetada para dar mais segurança ao seu smartphone! Com design fino, leve e confortável, a capa além de proteger o seu celular irá manter o brilho e estilo original do aparelho! Desenvolvida com a combinação de policarbonato transparente, ela se encaixa perfeitamente ao smartphone. A tecnologia MagSafe na capa forma um anel de ímãs na traseira do celular para se conectar por magnetismo aos carregadores sem fios. Antes existia o risco de o usuário posicionar o aparelho de forma errada na base carregadora; agora, o MagSafe garante que o aparelho será sempre atraído para o ponto certo. Não compatível com uso de suporte magnético / Utilizar a placa para suporte magnetico poderá impossibilitar o carregamento Wireless OBS: O smartphone quando superaquecido durante o uso e/ou carregamento, transmite um calor que provoca uma reação química do material da capa que pode ocasionar uma aparência amarelada na mesma. ESPECIFICAÇÕES Material: policarbonato de alta densidade Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos Cor: Preta COMPATIBILIDADE iPhone 16E ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 109.99, 109.99, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbcezginwp73a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23598664246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22295633095', 'Sinergy Spray Vitrificador de Pintura Aplicador Vonixx Pano Microfibra 40x40', 'KIT CONTÉM: SINERGY PAINT 500ML VONIXX PANO DE MICROFIBRA 40X40CM JS APLICADOR DE ESPUMA VONIXX ------------------------------------------------------------------------------------ SINERGY PAINT 500ML - COATING SPRAY PARA PINTURA DESCRIÇÃO: Sinergy é coating spray de fácil aplicação desenvolvido para pintura de automóveis e tem como função proteger a pintura por até 12 meses. O diferencial desse produto é a sua tecnologia exclusiva Vonixx, Carbosiloxy, onde o elemento químico carbono age em sinergia com o silício e com isso, forma um filme resistente e super hidrofóbico e tem um tempo de cura menor, em média 60 minutos. Além disso, esse produto reduz o atrito, minimizando riscos e promovendo um excelente brilho. DURABILIDADE: Até 12 meses TEMPO DE CURA: 1 hora RENDIMENTO MÉDIO: Até 15 aplicações MODO DE USO: 1. Certifique-se que a pintura esteja limpa e seca 2. Pulverize uma pequena quantidade do produto em uma toalha de microfibra limpa e seca 3. Espalhe em movimentos laterais em área não superior a 60 x 60 cm 4. Após 10 segundos faça acabamento com uma segunda toalha de microfibra limpa e seca 5. Continue o processo até concluir todo o veículo', 127.92, 127.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgi0ujt5sxz8ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F22295633095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698212545', 'Película Protetora Anti Luz Azul para iPhone 16e - AntiBlue - Gshield', 'Você está cansado de sofrer os efeitos nocivos da luz azul? Estresse, dores de cabeça, fadiga ocular e insônia são alguns dos problemas enfrentados pelo uso excessivo do celular. Se você procura uma solução para esses problemas, então a Película AntiBlue da Gshield, é exatamente o que você precisa! A AntiBlue da Gshield é fabricada com tecnologia espacial para bloquear 99% da luz UV azul prejudicial à saúde emitida pelo smartphone durante o uso, ela protege tanto seus olhos quanto sua pele; reduz significadamente os reflexos luminosos e também melhora drasticamente o sono noturno regulando melhor as ondas cerebrais com base na frequência da luz azul emitida pela tela do celular, proporcionando assim um bem-estar mental durante todo o dia! Não há nada melhor do que realizar dois investimentos em um só: cuidar da sua saúde e do seu bem material, por isso a película AntiBlue é perfeita para você! Protege o seu iPhone 16e e a sua saúde! Principais diferenças da AntiBlue: - Previne o ressecamento dos olhos - Previne o ressecamento da pele - Segura para uso contínuo - Tecnologia Anti-risco ESPECIFICAÇÕES - Marca: Gshield - Material: Hidro nano pet + TPU Soft Gel- (Gorila Shield) - Dimensão: Cobre as dimensões da tela, podendo existir leves recuos para melhor utilização com capas - Espessura: 0,19mm - Proteção: Contra pequenos impactos e riscos à tela - Grau de transparência: 99% High Definition - Certificações: US Military COMPATIBILIDADE - iPhone 16e ITENS INCLUSOS - 1x Película AntiBlue - 1x Kit de Instalação', 65.97, 65.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rcdd-m6fqf16u6cc205', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23698212545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697566925', 'Película para Motorola Moto Edge 50 Fusion 5G - Traseira de Fibra de Carbono Preta - Gshield', 'Proteja a traseira com a película para Motorola Moto Edge 50 Fusion 5G A Película Traseira de Fibra de Carbono Preta para Motorola Moto Edge 50 Fusion 5G, da Gshield, é projetada para proporcionar uma camada de proteção adicional, garantindo que seu aparelho fique livre de riscos e arranhões indesejados na parte de trás. Com seu acabamento em fibra de carbono preta, ela não apenas oferece segurança, mas também adiciona um toque estiloso ao seu smartphone.', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rd5b-lvadnz4fz88k21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23697566925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19626683963', 'Chupeta 100% Silicone Soft Calming 6m+ Neutra - Lillo', 'Chupeta 100% Silicone Soft Calming 6m+ Neutra – Lillo A Chupeta Soft Calming Lillo foi projetada em peça única, 100% Silicone macio e flexível, livre de Bisfenol-A, com bordas arredondadas, canais de ventilação e alça integrada que permite o uso de prendedores para evitar a perda. O formato do bico permite o uso da chupeta dos dois lados. Acompanha estojo esterilizável e reutilizável para higienização e transporte. “O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO”. Principais Características: - Tamanho do Bico: Nº2 (6m+) - Bico pode ser utilizado dos dois lados. - Silicone Macio e flexível - Bordas arredondadas - Livre de Bisfenol-A 0% - 100% Silicone - Alça para prendedores - Acompanha estojo esterilizável e reutilizável. Especificações Técnicas: - Conteúdo da Embalagem: 01 Chupeta e 01 estojo esterilizável. - Composição/Material: 100% Silicone - Garantia: 90 Dias (Contra Defeito de Fabricação) - Certificação: CE-PUR /IQB-000637 - Código do Fabricante: 629801 - EAN: 7896033204651 - Marca: Lillo * Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante*', 24.0, 24.0, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/580930c681ce430c9fbb01935e8ecc43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F19626683963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
