INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3744438048', '5 Mascaras Respiradora Pff2 Valvulada N95 Coronavirus', 'Imagem ilustrativa - Você poderá receber as máscaras das marcas Delta , Alians ou Camper enviaremos de acordo com a disponibilidade no ato da separaçåo dos pedidos. • Aplicação: - Além das aplicações citados no filtro classe PFF1, os filtros de classe PFF2 são eficientes na retenção de fumos metálicos como solda ou provenientes do processo de fusão de metal que contenham os metais: ferro, chumbo, cobre zinco, níquel, manganês, névoas aquosas de inorgânicos em baixa concentração: névoas de ácido sulfúrico e soda cáustica. Também são indicados os filtros P2 para proteção contra névoas de pesticidas com baixa pressão de vapor que não contenham vapores químicos associados • Respirador semifacial descartável dobrável • Classe PFF2 • Cor externa azul • Tamanho único • Equipada com válvula de exalação • Possui solda por ultrassom em todo seu perímetro • Confeccionado com filtro de manta sintética, para uso contra aerodispersoides (partículas) gerados mecanicamente. As partículas podem ser sólidas ou líquidas geradas de soluções ou suspensões aquosas • C.A.: 38.509 - Certificações: NBR 13698/2011 e as portarias do INMETRO 230/2009 06/2015.', 49.0, 49.0, NULL, 'Health > Medical Supplies > Medical Gloves & Masks', 'https://cf.shopee.com.br/file/5cd27e2d601550e0699361dedc5a118c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F3744438048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
