INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098689764', 'Kit Meu Feed com 4 itens 970891 Pimaco', 'O Kit Meu Feed da Pimaco foi desenvolvido para quem ama personalização, criatividade e estilo nas pequenas coisas do dia a dia. Composto por 4 itens coordenados, esse conjunto é ideal para decorar planners, cadernos, agendas, cartões, diários e muito mais, permitindo criar composições únicas e com a sua cara. Os itens foram pensados para refletir tendências visuais inspiradas nas redes sociais, com cores modernas e elementos gráficos divertidos. O kit oferece variedade e praticidade, reunindo diferentes tipos de adesivos e papéis criativos em um só pacote. Detalhes: - Ideal para: uso escolar, decoração de papelaria, scrapbooking e DIY - Cores e temas inspirados nas redes sociais - Fácil de aplicar e combinar - Contém 4 itens diversos no kit: 1 bloco adesivo Pima Note de 76x76mm 1 bloco adesivo Pima Note de 100x151mm 5 blocos marcadores de páginas Pima Note de 12x42mm 5 folhas de adesivos diversos', 38.82, 32.61, NULL, 'Stationery > Art Supplies > Color Pencils', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-mbnrkr6fxtdhb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23098689764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194572844', 'WHISKY WHITE HORSE 500 ML', 'É composto por mais de 35 maltes, uma das mais elevadas proporções de maltes nos scotch whiskies. Assim como Logan, também desenvolvido por Peter Mackie, seus principais maltes são Lagavulim, Glen Elgin e Craigellachie. White Horse foi um dos primeiros scoth a serem introduzidos no Brasil, e traz até hoje o mesmo sabor rico e único, e a mesma qualidade, aqui e no mundo inteiro. Características: Volume:500ml Tipo: Whisky Teor: 40% Marca: White Horse OBS: Produto proibido para menores de 18 Anos! Conteúdo Embalagem: 1x Gin Watermelon Garrafa De 900ml', 57.99, 57.99, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mg42yjmufzm006', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1605305232%2F22194572844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18961852688', 'Vela De Ignição Honda Titan 150 2004 A 2015 Ngk Cpr8ea9', 'Aplicação Aplicação HONDA CG 150 TITAN-ES 2004 até 2009 CG 150 TITAN-ES MIX 2009 até 2010 CG 150 TITAN-ESD MIX/FLEX 2009 até 2015 CG 150 TITAN-ESD/ TITAN SPECIAL EDITION 2004 até 2009 CG 150 TITAN-EX MIX/FLEX 2010 até 2015 CG 150 TITAN-KS MIX 2009 até 2011 CG 150 TITAN-KS/ TITAN-JOB 2004 até 2009 Conteúdo Da Embalagem 1 Vela de Ignição Tipo de Veículo para Motos Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. Além disso, a NGK é uma companhia certificada pela ISO/TS 16.949 e obedece as diversas regras de referências internacionais de qualidade. Os mais de 1300 funcionários da NGK do Brasil passam por um absoluto programa de treinamento e integração à filosofia de trabalho, no qual são estimulados a contribuir com propostas de melhoria contínua em benefício da organização e da sociedade. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 3 Meses. Valor unitário. Imagem meramente ilustrativa. Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. Código do Fabricante CPR8EA9', 26.78, 26.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7r98r-llu08fakcrbt70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18961852688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
