INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2972141037', 'Kit Mini Bands 4 intensidades e Faixas Elásticas Theraband para treino com elástico - Odin Fit', 'Kit Faixas Elásticas 3 Intensidades ODIN FIT permite o fortalecimento dos músculos, resistência e elasticidade. Indicada também para reabilitação muscular, fisioterapia e pós-cirúrgico. Prático para uso e transporte. Especificações: Comprimento: 120 cm; Largura: 15 cm; Possui 3 Intensidades: Fraca (Amarela) - 0,35mm – Resistência: 4,5 a 6,8kg; Média (Vermelha) - 0,45mm - Resistência: 6,8 a 11kg; Forte (Azul) - 0,55mm - Resistência: 11 a 16kg; Material: Elastômero Termoplástico (TPE) + Kit Mini Bands 4 Intensidades - Odin Fit O Kit Mini Bands Odin Fit, também conhecido como “Látex Loops” é ideal para o desenvolvimento de resistência, reabilitação e força muscular, sendo um ótimo equipamento para exercícios funcionais. Prático de usar, e de transportar para qualquer lugar. Especificações: Dimensões aproximadas: 30 x 5 cm. Possui 4 intensidades: 1 elástico (Mini band) amarelo - leve intensidade - Resistência: 2,3 a 4,5 kg; 1 elástico (Mini band) vermelho - Média intensidade - Resistência: 6,8 a 14 kg; 1 elástico (Mini band) azul - Forte intensidade - Resistência: 9 a 16 kg; 1 elástico (Mini band) preto - Extra-forte intensidade - Resistência: 14 a 20 kg; Contém: 1 (um) Kit com 4 Mini Bands – Odin Fit + 1 (um) kit de faixas elásticas com três intensidades. Garantia de 3 meses sobre defeitos de fabricação.', 119.9, 107.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Yoga & Pilates', 'https://cf.shopee.com.br/file/368eb582891b849ea0ae78857caa74e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F407831463%2F2972141037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202787607', 'Junta Cárter Motor TARANTO Belina Del Rey Escort Pampa Royale Verona Versailles Gol Golf Kombi Logus Parati Passat AP', 'CONFIRME O MODELO ANTES DE COMPRAR; REFERÊNCIA ORIGINAL: 056103609A; JUNTA DE CORTIÇA COM BORRACHA; Vedação eficaz; Alta resistência térmica; Bem-vindo à Cornélio Autopeças no Shopee! Somos referência em autopeças, oferecendo produtos de alta qualidade para manter seu veículo em perfeito funcionamento. 🔧 O que você encontra aqui? Peças das melhores marcas para diversas montadoras e modelos Acessórios automotivos com o melhor custo-benefício Frete rápido e seguro para todo o Brasil Atendimento especializado para tirar suas dúvidas 👉 Acesse já e garanta os melhores produtos para o seu carro! 🚗💨 ITENS INCLUSOS: 1 JUNTA CARTER CORTIÇA 220411 - 056103609A; DESCRIÇÃO: Proteja o motor do seu veículo com a Junta Cárter Motor TARANTO 220411. Essa peça essencial cria uma vedação confiável entre o cárter e o bloco do motor, evitando vazamentos de óleo e garantindo o bom funcionamento do sistema de lubrificação. Fabricada com materiais de alta qualidade, a Junta Cárter Motor TARANTO proporciona resistência a altas temperaturas e pressões, prolongando a vida útil do motor e evitando danos graves. Com a Junta Cárter Motor TARANTO, você terá a tranquilidade de rodar com seu veículo sem se preocupar com vazamentos prejudiciais. Mantenha a manutenção em dia e garanta o desempenho e a durabilidade do seu motor com essa junta de qualidade. VEÍCULOS COMPATÍVEIS: Ford: • Belina 1989 1.8 8V AP anotação: JUNTA DE CORTIÇA - 056103609A • Belina 1990 1.8 8V AP anotação: JUNTA DE CORTIÇA - 056103609A • Belina 1991 1.8 8V AP anotação: JUNTA DE CORTIÇA - 056103609A • Del Rey 1989 1.8 8V AP anotação: JUNTA DE CORTIÇA - 056103609A • Del Rey 1990 1.8 8V AP anotação: JUNTA D