INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698486276', 'Kit Coleção Sentimentos e Emoções + 4 Dedoches e Livros', 'O escritor James Missé lança um olhar diferenciado sobre o tema e nos desafia a trabalhar nossas emoções e sentimentos para que, assim, possamos ser mais felizes! Recomendado por psicólogos e especialistas. Além disso, vem com uma caixa super personalizada, todos os livros da coleção (medo, raiva, feliz e triste), e com os dedoches do nosso personagem Ednelson de todos os títulos (medo, raiva, feliz e triste). 22x22cm', 82.9, 82.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfgk-m9upnm8lhmz333', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22698486276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9925556895', 'Barnabé - O Pregador de Fé e Obras - Ciro Sanches', 'Neste livro, o pastor Ciro Sanches Zibordi traz à luz todo o protagonismo de Barnabé que é um dos personagens mais atraentes de todo o livro de Atos e que foi proeminente em seu tríplice ministério, similar ao de Paulo: pregador, apóstolo e mestre dos gentios. Características ISBN 978-85-263-1897-7 Altura 21 Largura 14 Número de páginas 160 Acabamento Brochura', 32.9, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/b77c77118d65c6ac2fd24539636a515f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F9925556895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19469529855', 'Como meus pais nutriram a minha fé | Elisabeth Elliot', 'COMO DEVE SER UM LAR CRISTÃO? Neste livro, Elisabeth Elliot reuniu memórias queridas e discernimentos valiosos obtidos de suas experiências ao crescer em um lar cristão. Por meio das histórias de seus avós, irmãos e pais, especialmente os escritos de sua mãe ao longo de 10 anos, Elisabeth mostra a importância da obediência, oração e perdão, entre outras lições que aprendeu quando criança. Sobre algumas, ela escreve: CONFIANÇA “O estabelecimento da confiança de um filho em Deus começa com a sua confiança na palavra de seus pais.” DISCIPLINA “É importante escolher o tempo certo, o lugar certo e o tom de voz certo quando a correção é necessária.” CORTESIA “A cortesia é simples e antiquada consideração. Faça por ele ou por ela o que você gostaria que lhe fizessem.” ENSINAR PELO EXEMPLO “O exemplo dos pais, para o bem ou para o mal, é uma influência muito mais profunda do que podemos medir.” 304 Páginas 16x23cm', 56.9, 56.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22120-fgfudhfyzelvf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19469529855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43602989298', 'Jogo de Cartas Baralho Batman 85 Anos Copag 34607 Criança Adulto Colecionável Poker Truco Tranca', 'Celebre os 85 anos do icônico herói da DC com o Baralho Batman 85 Anos, uma verdadeira obra-prima para colecionadores e fãs apaixonados! Cada carta foi cuidadosamente elaborada para trazer os personagens mais emblemáticos da franquia, capturando a essência única do universo do Batman. Uma homenagem à longa trajetória do Batman, repleta de emoção, aventura e legado. Adicione essa peça exclusiva à sua coleção e mergulhe no fascinante mundo do Cavaleiro das Trevas. Informações Técnicas: - Material: Plástico e Papel Recicláveis. - Contém: 55 Unidades de Cartas personalizadas no formato 63mm x 88mm - Tamanho da carta: Poker Size (63mm x 88mm) - Indicado para: Truco, Poker, Buraco, Cacheta, Paciência, BlackJack, Canastra, Buraco, Rummy, Bridge e muito mais! Características: - Marca:COPAG - Modelo:34607 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 55 Unidades de Cartas personalizadas no formato 63mm x 88mm', 57.07, 42.52, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rauk-maiitoqtr7cza6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F43602989298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
