INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697501693', 'Protetor Solar Nivea Sun Protect & Hidrata FPS50 125ml', 'Protetor Solar Nivea Sun Protect & Hidrata FPS50 é um filtro solar feito para proteger a sua pele enquanto a hidrata, para deixá-la ainda mais linda e bem cuidada. Sua fórmula contém Panthenol, um ativo que equilibra e hidrata de forma prolongada, deixando a sua pele macia e levemente perfumada.O protetor solar é livre de óleos (oil free), tem toque seco e é resistente à água, e pode ser aplicado no rosto e corpo. Use diariamente.', 58.79, 58.79, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd6b-lvc4bja3dqca23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23697501693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
