INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598277959', 'Blusa Feminina Viscotorcion Com Bolso Rovitex Laranja', 'A blusa feminina confeccionada em viscotorcion possui um bolso na altura do busto, é uma peça elegante e confortável, que combina estilo e praticidade. O tecido em viscotorcion é conhecido por sua durabilidade e caimento suave, garantindo conforto e mobilidade durante todo o dia. O bolso na altura do busto é um detalhe que traz um toque de charme e originalidade à peça, além de ser uma opção prática para quem precisa carregar pequenos objetos consigo.', 69.99, 69.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mr0jvtk80vlze9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F20598277959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
