INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598015921', 'Mesa Para Computador Escrivaninha Zetta 90cm Preto - Fit Mobel', 'Conheça a Mesa Para Computador Escrivaninha Zetta 120cm Preto da Fit Mobel, essa é a escolha correta para quem procura praticidade no Ambiente de Trabalho. A Mesa Para Computador vai valorizar a decoração do ambiente e trazer mais praticidade. Produzida em MDP de 15 mm com acabamento em BP que proporciona maior durabilidade e resistência ao produto. Além disso, a Mesa De Escritorio conta com design moderno e pés metálicos pretos com sapatas niveladoras. Este móvel pode ser usado tanto como mesa de estudos quanto escrivaninha para home office, sendo igualmente util nos seus afazeres diários. Confira e leve já! ESPECIFICAÇÕES Dimensões do Produto Largura: 90 cm. Altura: 75 cm. Profundidade: 60 cm. Peso: 11,30 Kg. Características do Produto Material da Estrutura: MDP BP 15 mm. Peso Suportado: 30 Kg. Acabamento: BP e Pintura Epóxi. Escala de Brilho: Fosco. Tipo de Pés: Pés metálicos. Possui Rodízios: Não. Diferenciais: - Design moderno. - Sapatas niveladoras. - Estrutura reforçada. Sistema de Montagem: Minifix / Cavilhas / Parafusos. Manual de Montagem: Sim. Complexidade da Montagem: Baixa. Volumes: 2 Volumes. Garantia do Fabricante: 90 dias contra defeito de fabricação. Montagem: Recomendamos que seja feita por um profissional. Recomendação de Limpeza: Utilize pano levemente úmido.', 468.61, 198.0, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-823qi-mojx0teltk3w40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F375188138%2F23598015921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
