INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398462772', 'Pincel Duo De Sombra Mari Maria MM 204', 'Descrição: Com o Pincel Duo De Sombra Mari Maria descubra a magia da maquiagem perfeita com o lançamento da nossa linha completa de pincéis! Experimente e otimize a aplicação da maquiagem garantindo acabamentos impecáveis. As nossas cerdas sintéticas, além de evitarem o desperdício de produto, são totalmente cruelty free, garantindo uma experiência segura e eficiente. Transforme sua rotina de beleza com as ferramentas certas para explorar todas as possibilidades de sua maquiagem! MODO DE USAR: O lado mais rígido aplica a cor, enquanto o lado mais macio, ou com cerdas maiores, ajuda a criar transições suaves e um esfumado impecável. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 1un. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 49.9, 29.99, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rffq-m9j1vg3xeuw7ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F23398462772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
