INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19878281283', 'Escapamento Pro Tork Powercore 3 Steel Technology Titan 150 Esd 2004/08', 'Uma nova versão do renomado escapamento Powercore 3, vem ai o modelo Steel Technology. Produzido em aço carbono, entrega excelentes níveis de potência para motocicletas street e off road, com a melhor relação custo/benefício do mercado. O projeto contempla tubos bem dimensionados, garantindo maior potência em baixas, médias e altas rotações, além de retomadas certas nas saídas de curvas. Acabamento de primeira qualidade, banhado no melhor cromo do mercado e soldas reforçadas. sem falar no design agressivo que confere um belo visual. Tudo testado em dinamômetro e também nas pistas. Especificações: - Powercore 3 modelo Steel Technology; - Material: Aço carbono; - Acabamento feito em Titanium; - Ronco esportivo; - Design agressivo; - Pronto para instalação; - Sistema de dobras Omniex que permite a vazão dos gases em alta velocidade; - Curva com Sistema Bomber; - Marca: Pro Tork. Aplicações: - Titan Esd 150 2004; - Titan Esd 150 2005; - Titan Esd 150 2006; - Titan Esd 150 2007; - Titan Esd 150 2008. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa -se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 399.89, 317.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfjqw9e66lyzec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F19878281283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
