INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15749199854', 'Livro - Amigos do espaço', 'O espaço é um lugar cheio de mistérios e repleto de amigos especiais: O Sol, a Lua, as estrelas, os planetas... Que tal conhecer um pouco mais sobre esses astros incríveis? _x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2021_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 18.00 x A 20.50 x E 1.00_x000D_ ISBN: 9786555008333', 19.9, 19.9, NULL, 'Books & Magazines > Others', 'https://cf.shopee.com.br/file/493216579d0dfec45ff254031fc8bd5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F15749199854', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42260812752', 'Livro The Phanton of the Opera W.Books', 'Mr Poligny is retiring as manager of the Paris Opera House. Before he leaves, he tells his replacements how to please the phantom who has haunted the opera house for years. Despite the mysterious death of a stagehand, the new managers insist the phantom is just a ghost story and the ballerinas are scared of nothing. Meanwhile, a singer is visited by the Angel of Music; a being who is neither angel nor ghost…_x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Gaston Leroux_x000D_ Idioma: Inglês_x000D_ Páginas: 120_x000D_ Dimensões: L 12.80 x A 19.80 x E 1.00_x000D_ ISBN: 9786552941923_x000D_ Coleção: The Creepy Classics_x000D_ Linha Editorial: W. Books - Clássicos_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Literatura estrangeira, Clássicos, Fantasia, Imaginação, Terror, Suspense_x000D_ BISAC: Ficção / Ficção / Clássicos_x000D_ Linha de Produto: W. Books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Não se aplica_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-mcs8bd4v3e502f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42260812752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399593586', 'Livro Literatura infantil Profissão do verbo amar', 'Ser protagonista da própria vida, mudar seu entorno e contribuir para a transformação do mundo. Esta é a história de uma pequena menina que aprendeu a ler o mundo conjugando os verbos amar, ler, transformar, protagonizar e esperançar. Escrito por Lúcia Serrano e ilustrado por Sami Ribeiro, este é um livro inspirador, que eleva a autoestima e faz um convite aos pequenos e aos grandes: Sempre acredite em você! _x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2024_x000D_ Autor: Lúcia Serrano_x000D_ Ilustrador: Sami Ribeiro_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.37_x000D_ ISBN: 9786553843721_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Professores, Amor, Leitura, Poesia, Escola, Estudar_x000D_ BISAC: Literatura Infantil / Escola & Educação_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 39.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rfgw-m3dib4i51v2b2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F18399593586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8669959252', 'Livro - Sítio do Picapau Amarelo - Cores do sítio - Ciranda Cultural', 'Lar de uma família para lá de especial, o Sítio do Picapau Amarelo promete grandes aventuras para Narizinho, Pedrinho e seus amigos. Com muito cuidado para a Cuca não os pegar, essa turminha não perde uma chance de se divertir! Embarque junto nessa aventura supercolorida, enquanto pinta os desenhos com a incrível aquarela. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Ieska Tubaldini Labão Idioma: Português Páginas: 16 Dimensões: L 21.00 x A 28.00 x E 0.20 ISBN: 9786555000146', 19.9, 19.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/4c5ed9644b2422b69e51c3bf13857a03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8669959252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594189141', 'Amend Cachos Hidratados - Ativador de Cachos 190ml', 'Amend Cachos Ativador de Cachos - Definição e Hidratação Sem Frizz Defina, hidrate e dê vida aos seus cachos com Amend Ativador de Cachos. Nutre profundamente, elimina o frizz e repõe a umidade capilar. Enriquecido com manteiga de karité, d-panthenol, biotina e vitamina E, protege os fios do calor e mantém a memória dos cachos com brilho, maciez e volume na medida certa. Conselho de Aplicação Aplique o produto no cabelo úmido e massageie bem as mechas. Modele os cachos com os dedos ou amasse os fios de baixo para cima e seque como de costume.', 49.96, 49.96, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra1w-mbiaxj58wtmd26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22594189141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493424533', 'Wella Professionals Color Touch 8/0 Louro Claro - Tonalizante 60g', 'Tonalizante em creme para todos os tipos de cabelo. Wella Professionals Color Touch colore os fios com tons intensos e brilhantes. Ideal para matização, neutralização e escurecimento, possui nuances variadas, como cinza, dourado, vermelho e marrom. Além disso, sua fórmula consegue cobrir até 50% do branco. O Tonalizante Color Touch, da Wella Professionals age de forma suave e semi-permanente, de forma evitar danos à fibra capilar. Assim, pode ser usado por fios sensibilizados, já que preserva a saúde do cabelo.', 44.21, 44.21, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-m17eujh41afe47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22493424533', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899760103', 'Kit Payot Vitamina C Hidratacao Facial (3 Produtos)', 'Kit Payot Vitamina C Hidratacao Facial (3 Produtos) Payot Vitamina C traz uma série de produtos de cuidado e tratamento à base dessa vitamina. O Complexo Vitamina C Payot, utiliza como ativo principal a melhor fração estável de Vitamina C do mundo, o VC-IP. Produzido no Japão, o VC-IP garante máxima absorção de Vitamina C na pele, o que o torna muito mais eficaz, por isso, demonstra resultados surpreendentes comprovados em 28 dias de uso. Escolher o Complexo de Vitamina C Payot significa: investimento no produto que garante maior absorção de Vitamina C e melhores resultados comprovados. Escolha o melhor! Este Kit Contém Payot Vitamina C - Sabonete Líquido 220ml: deixa o rosto com uma aparência saudável, combate os radicais livres e mantém a hidratação. Também protege, proporciona maciez e toque sedoso na pele. Ideal para higienizar e revitalizar. Payot Complexo Vitamina C - Sérum para Area dos Olhos 14ml: Confere firmeza, luminosidade e hidratação intensa. Payot Complexo Vitamina C - Sérum Anti-Idade 30ml: Confere firmeza, luminosidade e hidratação intensa. Como Usar Conselho de Aplicação Sabonete: Aplique o sabonete sobre a pele molhada com movimentos suaves até formar espuma. Em seguida, enxágue bem com água. Serum Anti Idade e Serum Para os Olhos: Aplique no rosto e espalhe com movimentos circulares. Pode ser usado pela manhã e à noite.', 529.68, 269.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7ras8-maecp8bfdrv55b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21899760103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497295538', 'Óleo Essencial de Eucalipto - Eucalyptus Oil 10ml', 'O Óleo de Eucalipto Possui Propriedades Purificantes e Refrescantes. Ele Ajuda a Eliminar Pensamentos Negativos e Equilibrar As Energias. Seu Aroma Mentolado Traz Uma Sensação de Liberdade Emocional. Ideal para Ser Usado com Os Difusores de Aroma Océane e Proporcionar Um Ambiente Perfumado e com Toque de Frescor.', 69.9, 59.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Essential Oils', 'https://cf.shopee.com.br/file/sg-11134201-8259v-mqhptrdhwd8i0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F20497295538', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293826097', 'Sombra Líquida Cobre - Liquid Eyeshadow Oasis 4you 2g', 'Gosta de Brilho No Olhar? Então Você Encontrou o Produto Certo! a Liquid Eyeshadow Permite Criações Cheias de Personalidade para Que Você Mostre Seu Lado Mais Radiante sem Medo. Se Deixe Levar Por Essa Sombra Líquida Incrível! A Cor Oasis É Um Cobre com Brilho Dourado e Furta-Cor Super Intenso Que Dura Por Bastante Tempo! Ele Arrasa No Visual Sempre, Seja Usado Sozinho ou Por Baixo de Uma Sombra, o Que Deixa a Cor Ainda Mais Fantástica. e Ainda Conta com Um Acabamento Cintilante Que Dá Aquele Glow Lindo para Suas Makes. E o Melhor de Tudo: É Super Fácil de Aplicar, Porque Tem Uma Textura Líquida Leve Que Esfuma Facilmente e Tem Uma Fixação Maravilhosa. Ah! e o Aplicador Também Ajuda Muito, Viu? Você Pode Tanto Usá-Lo para Passar Diretamente Nas Pálpebras ou Colocar No Dorso da Mão para Usar com Um Pincel. De Fórmula Vegana, a Liquid Eyeshadow É Aquele Produto Indispensável em Qualquer Coleção de Maquiagem. É Brilho para o Que Der e Vier! Em Quais Ocasiões Eu Posso Usar o Liquid Eyeshadow? Em Todas! com Essa Sombra Líquida, Você Pode Tanto Criar Um Olhar Super Colorido e Marcante, com Pequenos Pontos de Luz Que Dão Um Leve Toque Elegante à Produção. Você Pode Usá-La Tanto Na Maquiagem para Trabalho Quanto para Uma Festa. Sua Criatividade Não Tem Limites com Liquid Eyeshadow! Liquid Eyeshadow Sai Fácil da Pele? Usando Um Demaquilante da Océane, a Liquid Eyeshadow Sai com Muita Facilidade! Mas Durante o Dia, Não Se Preocupe, Pois a Sombra Vai Continuar Intacta, Já Que Sua Fórmula É de Longa Duração, com Alta Fixação.', 69.9, 59.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8259e-mr25c29bcwsid0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F23293826097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398026696', 'Placa Eletrônica de Geladeira Brastemp 326063223 - 110V', 'Placa Eletrônica de Geladeira Brastemp 326063223 - 110V A Placa Eletrônica de Geladeira Brastemp 326063223 - 110V é um componente essencial para garantir o funcionamento eficiente e seguro de refrigeradores. Esta placa eletrônica é projetada para atuar no controle das principais funções da geladeira, como o sistema de refrigeração e descongelamento automático, proporcionando uma gestão otimizada da temperatura interna. Com a substituição adequada, sua geladeira retoma o desempenho ideal, assegurando a conservação correta dos alimentos e prolongando a vida útil do eletrodoméstico. Compatível com modelos de geladeiras Brastemp, este componente se destaca pela eficiência e confiabilidade, auxiliando no controle dos ciclos de operação. Sua estrutura compacta e tecnologia avançada permitem um funcionamento silencioso e com baixo consumo de energia, o que contribui para maior economia e sustentabilidade no uso diário. Além disso, a instalação é simples, sendo uma excelente escolha para quem busca restaurar a funcionalidade de sua geladeira com uma peça de alta qualidade. Ideal para quem deseja manter seu refrigerador funcionando com o máximo desempenho, a Placa Eletrônica Brastemp 326063223 oferece uma solução confiável para problemas de controle e operação. Ao investir em peças de reposição como esta, o consumidor pode prolongar a vida útil do eletrodoméstico e evitar gastos com a compra de novos equipamentos.', 319.9, 319.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbnh-m5ymuzkpqdtg68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21398026696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198026705', 'Atuador LR Emicol Compatível Lavadora Electrolux - 110V', 'Atuador LR Emicol Compatível Lavadora Electrolux - 110V O Atuador LR Emicol Compatível para Lavadora Electrolux - 110V é uma peça fundamental para garantir o funcionamento ideal da sua lavadora. Desenvolvido com tecnologia avançada, este atuador é projetado para proporcionar maior eficiência e durabilidade, assegurando que suas roupas sejam lavadas com a eficácia que você espera. Sua instalação é simples e rápida, permitindo que você retome o uso da sua lavadora sem complicações. Com componentes de alta qualidade, ele oferece uma performance confiável, otimizando cada ciclo de lavagem. Ao escolher o Atuador LR Emicol, você investe em um produto que não só atende às especificações técnicas da Lavadora Electrolux, mas também contribui para o desempenho geral do aparelho. Este atuador é ideal para quem busca uma solução que alie custo-benefício a uma manutenção de alta performance. Com ele, você pode ter a tranquilidade de saber que sua lavadora está equipada com um componente que funciona em harmonia com seu sistema, garantindo resultados consistentes e satisfatórios em cada lavagem. Além de sua funcionalidade, o Atuador LR Emicol é uma excelente escolha para quem valoriza a praticidade. A peça é fabricada para garantir um encaixe perfeito e seguro, reduzindo o risco de falhas no funcionamento. Ao optar por esse atuador, você está assegurando um ciclo de lavagem eficiente, permitindo que você aproveite ao máximo a sua lavadora Electrolux. Com um produto de qualidade como este, suas roupas ficarão sempre limpas e frescas, enquanto você desfruta da conveniência e praticidade que uma lavadora de alta performance pode oferecer.', 114.9, 114.9, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbne-m5ymshnjd00ece', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21198026705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699249630', 'OBRAS COMPLETAS DE MARIA JUDITE DE CARVALHO', 'OBRAS COMPLETAS DE MARIA JUDITE DE CARVALHO A presente coleção reúne a obra completa de Maria Judite de Carvalho, considerada uma das escritoras mais marcantes da literatura portuguesa do século XX. Herdeira do existencialismo e do nouveau roman, a sua voz é intemporal, tratando com mestria e um sentido de humor único temas fundamentais, como a solidão da vida na cidade e a angústia e o desespero espelhados no seu quotidiano anónimo.Observadora exímia, as suas personagens convivem com o ritmo fervilhante de uma vida avassalada por multidões, permanecendo reclusas em si mesmas, separadas por um monólogo da alma infinito.O presente volume inclui as crónicas publicadas sob o pseudónimo de Emília Bravo.. Informações Adicionais Autor: DE, CARVALHO Data Publicação: 30/12/1899 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: OBRAS COMPLETAS DE MARIA JUDITE DE CARVALHO Idioma: INDEFINIDO Páginas: 332 Edição: 1 ISBN-13: 9789898866745 ISBN-10: 9898866748', 79.0, 79.0, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbmd-lp84a7qec3d498', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F20699249630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398793706', 'Capacitor 324-388 Eletrolítico Hulter - 110V', 'Capacitor 324-388 Eletrolítico Hulter - 110V O Capacitor 324-388 Eletrolítico Hulter - 110V é um componente essencial para garantir o desempenho e a eficiência de equipamentos elétricos que exigem alta performance. Com capacitância entre 324 e 388 microfarads e tensão de operação de 110V, ele é ideal para motores, compressores e sistemas de refrigeração que necessitam de maior torque de partida e estabilidade durante o funcionamento. Projetado com foco em durabilidade e segurança, o capacitor Hulter oferece excelente resistência a variações elétricas, contribuindo para o bom funcionamento dos aparelhos e reduzindo o risco de falhas. Sua estrutura compacta facilita a instalação e se adapta bem aos mais diversos modelos de equipamentos, tornando-o uma escolha confiável para manutenção ou substituição. Com alto padrão de qualidade, o capacitor eletrolítico da Hulter proporciona performance constante, mesmo em ambientes com exigência contínua de carga elétrica. É uma solução eficiente para quem busca estabilidade, proteção e melhor desempenho nos sistemas elétricos do dia a dia.', 22.9, 22.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rdw3-mbo71nmnccmt55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22398793706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
