INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298843713', 'Jogo Sapata Lona Freio Polo 2008 2009 2010 2011 2012 2013', 'Jogo de Sapata de Lona de Freio Traseiro Polo 2008 a 2013 Descrição do Produto Jogo de sapata de freio traseiro para Volkswagen Polo, modelos de 2008 a 2013. Produzido com material de alta durabilidade, garante eficiência, segurança e conforto na frenagem. Mantém o desempenho original do sistema de freio, reduzindo ruídos e vibrações e aumentando a confiança ao dirigir. Aplicação Veículo: Volkswagen Polo Motorização: 1.6 / 2.0 Anos: 2008, 2009, 2010, 2011, 2012, 2013 Posição: Traseira Benefícios Frenagem eficiente em diferentes condições Redução de ruídos e vibrações Maior durabilidade e resistência ao desgaste Preserva o tambor de freio Conforto e segurança ao dirigir Qualidades do Produto Alta resistência ao desgaste Compatibilidade com o sistema original Instalação fácil e precisa Excelente dissipação de calor Desempenho confiável e garantido Importância da Troca A substituição regular das sapatas de freio traseiras é essencial para manter a segurança e evitar desgaste excessivo do tambor. A troca no período correto assegura uma resposta de frenagem eficiente e aumenta a durabilidade do sistema de freio, oferecendo mais tranquilidade na condução.', 127.97, 106.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdxghm2bjxmrc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1464009232%2F23298843713', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
