INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3048401086', 'SAGA STARLING - STARLING', 'Mason Starling é campeã de esgrima, mas nunca teve de lutar por sua vida. Não até a noite em que uma violenta tempestade sobrenatural assola Manhattan, aprisionando Mason e seus colegas de equipe dentro da escola. Ela é atacada por criaturas horrendas, com forma vagamente humana, enquanto a tormenta traz para a vida dela um perigoso desconhecido: um jovem que não se recorda de nada além de seu nome – Fennrys, o Lobo. A chegada desse garoto misterioso faz em pedaços o mundo de Mason, ao mesmo tempo que uma atração inegável surge entre eles. Juntos, eles tentam desvendar os segredos da identidade de Fenn, enquanto forças estranhas e sobrenaturais se adensam à volta deles. Quando descobrem que a família de Mason, com sua obscura ligação com antigos deuses nórdicos, é a chave de todo o mistério, Fennrys e Mason subitamente se veem diante de um futuro catastrófico: o Ragnarök – ou o fim do mundo, como o conhecemos.', 29.6, 29.6, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-23030-f9ebp1ghapov57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F3048401086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
