INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41729481917', 'Lovito Meias de Algodão Bonitas 10 Pares Bordado de Laço Coreano Média Canela Respiráveis Feminino LNE141001', '✅DESTAQUES -❤️Pacote de 10 combinados -❤️Bordado -❤️Respirável -❤️Elástico em 4 direções -❤️Amigável à pele e confortável -❤️anual -❤️Lar ✅DESCRIÇÕES Estampa / Padrão:Plain Estilo:Cute Tamanho Plus:No Material:Poliéster Composição:100%Polyester Tipo de modelagem:Slim Fit Transparência:No Esticar: Feito na China ✅O PACOTE INCLUI 1XMeias ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 39.9, 27.9, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/sg-11134201-81zvv-mmtq44sbchs22a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F41729481917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
