INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297984720', 'Batedeira Planetária Artisan KitchenAid Stand Mixer com 03 Batedores Silver', 'Considerando um ícone de design, a batedeira Stand Mixer é a mais usada e adorada por chefs de cozinha no mundo todo. Possui o movimento planetário com 10 velocidades e é a única que atinge 67 pontos de contato da tigela. Inclui protetor de respingos e 3 batedores: gancho, pá plana e fouet. Além de exclusivos acessórios para moer, fatiar, triturar, fazer sorvetes , massas e sucos. Principais Características 10 Velocidades. Potência de 275W. Sistema de mistura com movimento planetário. Corpo total de metal. Outras Características Sistema de mistura com movimento planetário - Com um movimento planetário com 67 pontos de contato na lateral da tigela, prepara alimentos proporcionando uma mistura rápida e homogênea. Dez velocidades - Permitem ter maior precisão para obter misturas perfeitas. Corpo todo de metal - Maior robustez e durabilidade em um design exclusivo. Acessórios Inclusos - Protetor de respingo, três batedores (massa, pão, claras), tigela de aço inox. Tigela - Com capacidade de 4,83 litros, para fazer as maiores e mais complexas receitas. Comandos simples e intuitivos. Fácil limpeza. Corpo todo de metal - Maior robustez e durabilidade em um design exclusivo. Especificações Técnicas Cor: Contour Silver (Prata). Voltagem: 110V. Potência: 275W. Dimensões (LxAxP): 219x353x358mm. Peso: 9,34kg. Garantia de 1 ano. Acessórios Inclusos Manual de instruções. Protetor de respingo. Três batedores (gancho, pá plana e fouet). Tigela de Aço Inox (4,83 litros). Acessórios Opcionais (Não Inclusos) Acessórios exclusivos para moer (Moedor de Alimentos), fatiar (Set Gourmet), triturar (Set Gourmet), fazer sorvetes (Sorveteira), massas (Pasta Roller, Pasta Press e Varal de Massas) e sucos (Extrator de Suco).', 3378.7, 2619.78, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfh9-m35bkw4vi8b7a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F854082976%2F19297984720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
