INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8431434030', 'Quando a escuridão não Passa', 'Até mesmo o cristão mais fiel e dedicado pode passar por períodos de depressão e escuridão espiritual, momentos em que a alegria parece inalcançável. Isso pode acontecer por diversas razões: pecado, ataque satnico, circunstncias estressantes, doenças ou outras causas físicas. Em Quando a escuridão não passa, o objetivo de John Piper é trazer consolo e orientação para aqueles que estão enfrentando escuridão espiritual. Ao longo destas páginas, o leitor compreenderá o aspecto físico da depressão, o significado de “esperar no Senhor” em períodos de trevas, como os pecados não confessados podem obstruir nossa alegria e como ajudar aqueles dos quais a alegria parece distante. Com uma sensibilidade ímpar, Piper utiliza exemplos da vida real e constrói uma narrativa inteligente para mostrar por que temos muitas razões para ter esperança de que Deus nos tirará do poço do desespero e nos trará mais uma vez para sua luz. 80 páginas 21x14cm', 26.9, 22.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/d2586829d239c99729895bbb80c4c874', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F8431434030', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993599566', 'Vozes dos Mártires: A história da fé e sacrifício dos apóstolos e dos primeiros cristãos | Capa Dura', 'Vozes dos Mártires é uma antologia de três histórias em quadrinhos colorida e envolvente que abrange o período mais antigo da história da Igreja. Na primeira, AS TESTEMUNHAS, acompanhe a vida de pessoas que conheceram Cristo e também de cristãos da Igreja Primitiva que foram martirizados por seu testemunho. A segunda, O APÓSTOLO, narra a transformação milagrosa de Saul, o perseguidor, em Paulo, o apóstolo, desde sua conversão dramática até as épicas aventuras missionárias que se seguiram. Por fim, OS DOZE, conta sobre a vida e a morte dos 12 apóstolos de Jesus 490 Páginas 16x26cm', 119.9, 117.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfg3-m4f7ynsrmohv16', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23993599566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
