INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40651154703', 'Livro Mulheres Que Caminham Juntas', 'Livro Mulheres Que Caminham Juntas Ana Paula Araujo, Claudia Lotti, Laise Oliveira, Luciana Sborowsky, Naná Castillo, Nátalie Campos, Prirsca Mendonça e Renata Gandolfo "Mulheres que Caminham Juntas" é um livro sobre a jornada cristã vivida em comunidade. Reunindo mulheres que, apesar das dificuldades da vida, buscam edificar umas às outras com seus dons e talentos, o livro nos desafia a viver em comunhão, praticando amor sacrificial e compartilhando as lutas e alegrias. Escrito por Ana Paula Araujo, Claudia Lotti, Laise Oliveira, Luciana Sborowski, Naná Castilho, Nátalie Campos, Prisca Mendonça e Renata Gandolfo, a obra traz reflexões sobre serviço, discipulado, ensino, aconselhamento e o uso das tecnologias no contexto da igreja local. Um convite para caminhar juntas com Cristo, edificando o corpo de Cristo para a glória de Deus. Vamos juntas? Especificações do livro Mulheres Que Caminham Juntas: Título: Mulheres Que Caminham Juntas Autor(es): Ana Paula Araujo, Claudia Lotti, Laise Oliveira, Luciana Sborowsky, Naná Castillo, Nátalie Campos, Prirsca Mendonça e Renata Gandolfo Ano de Edição: 2025 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel Pólen Páginas: 186 Dimensões: 14 x 21 x 1,3 cm Peso: 0.212 ISBN: 9786557233894 Editora: Editora Fiel', 38.36, 38.36, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kr5dam9fzt4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F40651154703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
