INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699599320', 'Sabonete Líquido para Bebês Protex Baby Lavanda 1L Garrafa', '"Sabonete líquido para bebê com glicerina de origem natural e fragrância de Lavanda desenvolvida para o relaxamento Essa linha de sabonete líquido da cabeça aos pés de Protex Baby é hipoalergênico e tem glicerina de origem natural, que ajuda a hidratar a pele do seu(ua) pequeno(a) naturalmente. Tem mais: a glicerina também mantém a barreira protetora da pele dos bebês para que ela fique saudável e macia. E sua fórmula suave é sem álcool, sem corantes e sem parabenos. <3 São produtos criados especialmente para momentos inesquecíveis, como o banho em bebê recém-nascido. Benefícios: 🟢 Protex Baby é enriquecido com glicerina de origem natural 🟢 Tem a Fragrância Relaxante 🟢 Fórmula Hipoalergênica 🟢 Protex Baby é enriquecido com glicerina de origem natural 🟢 Livre de álcool, conservantes e parabenos 🟢 Sem lágrimas 🟢 Testada por pediatra e dermatologista"', 90.53, 90.53, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7ra3g-m537banksl5j74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F19699599320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45453917953', 'Kit 6 Cueca Boxer Reebok Microfibra Kit Cueca Box Poliamida Cueca Masculina Sem Costura Original', 'Kit 6 Cueca Boxer Classic Poliamida Reebok A cueca boxer masculina em poliamida da Reebok é a escolha ideal para quem busca conforto, respirabilidade e alta performance no dia a dia e nos treinos. Desenvolvida com modelagem anatômica sem costura, ajusta-se perfeitamente ao corpo, reduzindo atritos e proporcionando liberdade total de movimento ao longo do uso. O tecido leve e macio oferece excelente absorção do suor e secagem rápida, mantendo a sensação de frescor mesmo em longos períodos de uso. O cós elástico reforçado com logo Reebok garante ajuste firme e seguro, sem dobrar, apertar ou enrolar, unindo funcionalidade e estilo esportivo. Versátil e durável, essa cueca boxer é indicada tanto para atividades físicas quanto para a rotina diária, entregando conforto contínuo, suporte estável e acabamento premium. Vantagens do produto: - Tecnologia sem costura, que reduz atritos e aumenta o conforto - Modelagem anatômica que se ajusta perfeitamente ao corpo - Tecido leve, macio e resistente, com alta durabilidade - Cós confortável com logo Reebok, firme sem apertar - Excelente absorção do suor e secagem rápida - Ideal para treinos, trabalho e uso prolongado - Design moderno, discreto e acabamento de qualidade Conteúdo da embalagem: Você receberá: Kit com 6 Cuecas Boxer Reebok Classic em Poliamida Composição: 94,16% Poliamida | 5% Elastano | 0,84% Poliéster Descrição dos kits Kit sortido: 1 branca | 1 cinza | 2 marinho | 2 preto Kit monocromático: 6 unidades na cor preta (Envio conforme variação escolhida no anúncio) Tabela de medidas: P: Manequim 38?40 | Quadril 34?36 cm M: Manequim 42?44 | Quadril 36?38 cm G: Manequim 46?48 | Quadril 38?40 cm GG: Manequim 50?52 | Quadril 41?43 cm Dica: se estiver entre dois tamanhos, opte pelo maior para melhor conforto. Cuidados na lavagem: - Lavar à mão ou na máquina até 30°C - Não usar alvejante - Secar à sombra, em varal - Não passar a ferro - Não lavar a seco Seguindo essas orientações, você preserva o caimento, a elasticidade e a durabilidade do produto.', 129.99, 89.99, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-81zwi-miu3f7891hjb03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1559054473%2F45453917953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
