INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692970927', 'Coti Massa Tutti Frutti Parque dos Dinossauros - Cotiplás', 'Coti Massa Tutti Frutti Parque dos Dinossauros - CotiplásA Massa de Modelar Coti Tutti Frutti Parque dos Dinossauros da marca Cotiplas é um brinquedo educativo e criativo que estimula a imaginação e coordenação motora das crianças. Idade recomendada: A partir de 3 anos. Selo Inmetro: CE-BRI/IQB 0228 IQB-OCP 011. Diferenciais:Variedade de Cores: A massinha Tutti Frutti vem em cores vibrantes que despertam a criatividade dos pequenos. Estímulo à Criatividade: As crianças podem criar diferentes dinossauros usando os moldes e acessórios disponíveis no kit. Mais sobre o Produto:Cada pote de massa apresenta um molde de dinossauro, permitindo que os pequenos criem diversas formas e personagens pré-históricos. Além disso, o kit acompanha ferramentas que auxiliam no processo de modelagem, como a espátula e o rolinho. A Tesoura sem ponta garante a segurança das crianças durante a brincadeira. Dicas de Uso:Para aproveitar ao máximo o potencial criativo do produto, incentive as crianças a experimentarem combinações de cores e texturas, criando diferentes tipos de dinossauros. Organize sessões de brincadeira em grupo para estimular a interação e colaboração entre os pequenos. Ficha Técnica:Marca: Cotiplás; Nome do produto: Coti Massa Tutti Frutti Parque dos Dinossauros; Idade Recomendada: A partir de 3 anos; Selo Inmetro: CE-BRI/IQB 0228 IQB-OCP 011; Contém: 4 Moldes, 1 Rolinho, 1 Espátula, 1 Tesoura e 3 Potes de Massinha.', 23.99, 23.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-luf7e04o5efs99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22692970927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499629240', 'Espuma Assento Banco Gol Voyage Saveiro G5 G6 G7 G8 Original', 'ESPUMA DO ASSENTO ORIGINAL VW GOL G5 G6 G7 G8 SAVEIRO G5 G6 G7 G8 VOYAGE G5 G6 G7 COMPRAS EFETIVADAS ATÉ AS 10:00H, SERÃO ENVIADAS NO MESMO DIA! PARA AVERIGUAÇÃO DE COMPATIBILIDADE, É NECESSÁRIO A NUMERAÇÃO COMPLETA DO CHASSI. PRODUTO NOVO, ORIGINAL! SOMOS CONCESSIONÁRIA VOLKSWAGEN. TIRE TODAS AS DÚVIDAS PELO CAMPO DE PERGUNTAS ANTES DE EFETUAR A COMPRA. VERIFIQUE SEU ENDEREÇO DE ENTREGA. SERÁ COBRADO UM NOVO FRETE CASO O PRODUTO RETORNE. FIQUE ATENTO AS SUAS MENSAGENS. GARANTIA: PEÇAS ORIGINAIS COMPRADA NA REDE VW TEM GARANTIA NACIONAL, SENDO QUE, SE A PEÇA FOR INSTALADA EM UMA CONCESSIONÁRIA TERÁ GARANTIA DE 1 ANO, INSTALAÇÃO FEITA EM OUTRA OFICINA TERÁ GARANTIA DE APENAS 90 DIAS! “AS PEÇAS ORIGINAIS VOLKSWAGEN REPRESENTAM SEMPRE A MELHOR ESCOLHA. UMA LINHA COMPLETA DE PEÇAS PROJETADAS, TESTADAS E PRODUZIDAS COM ALTO RIGOR TECNOLÓGICO PARA PROPORCIONAR O MÁXIMO EM DESEMPENHO COM CONFIABILIDADE E A MESMA SEGURANÇA DAS PEÇAS UTILIZADAS EM UM VEÍCULO ZERO QUILOMETRO”. CORREAUTO VW VOCÊ MERECE UM ATENDIMENTO 5 ESTRELAS!', 259.9, 259.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134201-820mc-mqxbgjcu1sef95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1182059565%2F18499629240', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263286096', 'Barbie Cavalo Quebra-Nozes - Mattel', 'Cavalo Barbie O Quebra-Nozes - Mattel Descrição Detalhada do ProdutoO Cavalo Barbie O Quebra-Nozes da Mattel é o complemento ideal para as aventuras no reino mágico. Com um design encantador inspirado no tema, este brinquedo traz uma experiência sensorial única, contando com crina colorida implantada que estimula a imaginação. O conjunto acompanha acessórios temáticos permitindo que a criança estilize a crina do cavalo de diversas formas. Fabricado com materiais duráveis, este item é perfeito para criar cenários lúdicos e colecionáveis, garantindo horas de diversão criativa. Seu acabamento detalhado reflete a atenção da marca aos elementos visuais, tornando-o uma peça de destaque em qualquer coleção da linha Barbie. Diferenciais/Benefícios Crina e cauda implantadas que permitem pentear e criar diferentes estilos, estimulando a coordenação motora. Acompanha acessórios temáticos de doces, como presilhas e pente, para personalizar o visual do cavalo. Design inspirado no universo Barbie O Quebra-Nozes, ideal para expandir o cenário de brincadeiras. Dicas de Uso Para preservar a textura da crina implantada, utilize apenas o pente incluso e evite puxar os fios com força. Mantenha o brinquedo em local seco e arejado, longe de fontes de calor excessivo para conservar o aroma e o acabamento. Público RecomendadoEste produto é indicado para crianças a partir de 3 anos de idade. Por conter peças pequenas que podem ser engolidas, não é recomendado para menores de 3 anos. Especificações Marca Mattel Modelo JLW55 Tema Barbie O Quebra-Nozes Peso 0.349 kg Itens Inclusos 1 cavalo + acessórios Principais DúvidasO cavalo vem com a boneca Barbie inclusa? Não, este produto contém apenas o cavalo e os acessórios. A boneca Barbie é vendida separadamente. Qual é a idade recomendada para brincar com este cavalo? O brinquedo é indicado para crianças a partir de 3 anos, devido à presença de peças pequenas que podem oferecer risco de ingestão. As presilhas podem ser usadas no cabelo da criança? As presilhas foram projetadas especificamente para serem utilizadas na crina do cavalo, não sendo recomendadas para uso pessoal. Como devo limpar o brinquedo? Recomenda-se a limpeza apenas com um pano levemente umedecido, evitando imersão em água para não danificar a crina e os componentes.', 159.99, 159.99, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-824in-mpy1j54bdbswa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F58263286096', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
