INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9233826044', 'Módulo Taramps MD 8000 1 Canal 2 Ohms 8000W Rms Amplificador Automotivo MD8000', 'Descrição O amplificador MD 8000.1 2 OHMS é desenvolvido com a mais alta tecnologia e desempenho para sistemas de som automotivo. É mono, com potência máxima de 8000Watts RMS com impedância de 2 OHMS, e 1 canal de 8000W RMS. O MD 8000.1 é FULL RANGE tocando todas as frequências na medida certa para você. CLASSE DE OPERAÇÃO Classe D NÚMERO DE CANAIS 01 POTÊNCIA MÁXIMA @ 12,6 VDC - 2 OHMS: 8000W RMS @ 12,6 VDC - 4 OHMS: 5120W RMS SENSIBILIDADE DE ENTRADA 220mV RELAÇÃO DE SINAL/RUÍDO >90dB RESPOSTA DE FREQUÊNCIA 10Hz ~10KHz(-3dB) CROSSOVER HIGH PASS (HPF) 10Hz ~90Hz(-12dB/8ª) Variável CROSSOVER LOW PASS (LPF) 90Hz ~10KHz(-12dB/8ª) Variável BASS BOOST Freq.: 35Hz ~55Hz Boost: 0 ~10dB(50Hz) EFICIÊNCIA 87% IMPEDÂNCIA DE ENTRADA 22K OHMS IMPEDÂNCIA DE SAÍDA 2 OHMS SISTEMA DE PROTEÇÃO Curto na Saída, Curto na Saída em Relação ao GND, Proteção de baixa impedância, Proteção de tensão alta/baixa e proteção térmica TENSÃO DE ALIMENTAÇÃO MÍNIMA 9VDC TENSÃO DE ALIMENTAÇÃO MÁXIMA 16VDC CONSUMO EM REPOUSO 2.5A CONSUMO MÁXIMO MUSICAL 364.90A CONSUMO MÁXIMO EM SINAL SENOIDAL 729.80A DIMENSÕES (LXAXP) 228 x 70 x 419mm', 2109.0, 1364.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820mb-mn0hfrcegz5t88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F9233826044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
