INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897540232', 'Base de Cama Queen Basic', 'Descrição: O visual moderno 100% MDF da Base para Cama de Casal / Queen TW22, remete ao design das camas japonesas e leva aconchego para qualquer quarto. O produto conta com um design minimalista e é ideal para compor o seu quarto. Por ser um produto Dalla Costa, a TW22 combina perfeitamente com qualquer escolha de mobiliário da marca. Por ser um produto 100% MDF e com pintura de 6 camadas de proteção, essa base de cama apresenta alta qualidade de acabamento e alta durabilidade. Com cantos levemente arredondados, esse produto é milimetricamente pensado para fornecer o conforto necessário para sua circulação pelo dormitório. Este produto não acompanha cabeceira e colchão. Características: - Possui Portas?: Não - Pode Ser Montado Invertido?: Não - Possui Puxadores?: Não - Possui Prateleiras?: Não - Possui Espelho?: Não - Possui Rodízios ?: Não - Possui Pés?: Sim - Superfície Antideslizante: Não - Pés Removíveis: Não - Cantoneiras: Sim - Possui Gavetas?: Não - Necessita de Montagem: Sim - Garantia (dias): 180 - Sistema de Montagem: Parafusos e cavilhas - Grau de Dificuldade da Montagem: Médio - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Indicação de Uso: Quarto - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Recomendação de Manutenção: Para conservar a cor e os aspectos originais do produto, leve em consideração: Levantar a peça ao deslocá-la, o que ajuda a evitar danos à base e aos pés; Não utilizar água em abundância na peça, somente um pano levemente umedecido para a limpeza ou um espanador seco; Utilizar panos preferencialmente brancos, para evitar manchas e seque bem o móvel após a limpeza; Utilize somente água, nunca produtos químicos, abrasivos, solventes, ceras, sabonetes não neutros ou produtos de limpeza doméstica, visto que podem danificar o acabamento; Não coloque objetos quentes diretamente em cima do móvel para não causar bolhas, manchas ou outros danos, opte por utilizar um apoio; Se possível, não exponha sua peça diretamente ao sol, utilize cortinas ou persianas para bloquear os raios de luz, para que a pintura não desbote. Esses cuidados são muito simples e auxiliarão seu produto a permanecer em perfeito estado por muitos anos. - Revestimento /Acabamento: Pintura UV - Espessura da Estrutura: 6 mm, 15 mm, 44 mm - Altura dos Pés: 001 - Estrutura da Base: MDF - Material dos Pés/Rodízios: Plástico - Modelo: Queen Size - Tipo de Enchimento: Não possui - Linha: Basic - Material da Estrutura: MDF - Escala de brilho: Fosco e Brilho - Tipo: Lojista e E-commerce - Quantidade de Pés: 12 - Material dos Pés: Sapata Plástica', 997.49, 969.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-lvjdjcj93qxy66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226105437%2F23897540232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398925093', 'Par Cubo Roda Traseiro Fox Polo SpaceFox CrossFox 1.0 1.6 2.0 Original Cofap Com ABS 5 Furo 05 a 14', 'DESCRIÇÃO O CUBO DE RODA COFAP CRC01007 – TRASEIRO COM ROLAMENTO E ABS – FOI DESENVOLVIDO PARA OFERECER O MÁXIMO EM SEGURANÇA, DURABILIDADE E CONFIABILIDADE. PRODUTO ORIGINAL COFAP, GARANTINDO PERFEITA COMPATIBILIDADE COM SEU VEÍCULO VOLKSWAGEN. CUBO DE RODA – TRASEIRO CÓDIGO PRODUTO: CRC01007 – TRASEIRO COM ROLAMENTO E ABS MARCA: COFAP ITENS INCLUSOS: 02 (DOIS) CUBO DE RODA TRASEIRO COFAP CRC01007 – COM ROLAMENTO E ABS BENEFÍCIOS: MAIOR SEGURANÇA E ESTABILIDADE ALTA DURABILIDADE E RESISTÊNCIA AO DESGASTE PRODUTO 100% NOVO E ORIGINAL COFAP COMPATIBILIDADE TOTAL COM ESPECIFICAÇÕES ORIGINAIS (OEM) APLICAÇÃO: VOLKSWAGEN CROSSFOX ........... 2005 A 2014 – MOTOR 1.6 – 5 FUROS Ø 28MM VOLKSWAGEN FOX .................... 2003 A 2015 – MOTOR 1.0 / 1.6 – 5 FUROS Ø 28MM VOLKSWAGEN POLO .................. 2002 A 2014 – MOTOR 1.6 / 2.0 – 5 FUROS Ø 28MM VOLKSWAGEN SPACEFOX .......... 2007 A 2014 – MOTOR 1.6 – 5 FUROS Ø 28MM DÚVIDAS FREQUENTES: ESTE PRODUTO É NOVO? SIM, TRABALHAMOS SOMENTE COM PRODUTOS NOVOS. O PRODUTO É ORIGINAL? SIM, PRODUTO ORIGINAL COFAP. POSSUI GARANTIA? QUAL O PRAZO? SIM, GARANTIA MÍNIMA DE 90 DIAS CONTRA DEFEITOS DE FABRICAÇÃO OU CONFORME PRAZO DO FABRICANTE. O PRODUTO É IDÊNTICO À FOTO? SIM, TODAS AS FOTOS SÃO FIÉIS AO PRODUTO QUE VOCÊ IRÁ RECEBER. ESTE PRODUTO É COMPATÍVEL COM O MEU VEÍCULO? PARA CONFIRMAR, ENVIE A PLACA OU O CHASSI DO SEU VEÍCULO. EM QUANTO TEMPO RECEBO MINHA COMPRA? INSIRA SEU CEP NO CALCULADOR DE FRETE DO ANÚNCIO PARA SABER O PRAZO. POSSO RETIRAR? SIM, OPÇÃO DE RETIRADA DISPONÍVEL EM NOSSA LOJA FÍSICA NA PENHA, SÃO PAULO. PEDIMOS A GENTILEZA NÃO AVARIAR A EMBALAGEM ORIGINAL (NÃO PASSE FITA ADESIVA, COLE ETIQUETAS OU RASGUE A EMBALAGEM). ANTES DE EFETUAR DEVOLUÇÃO OU ABRIR RECLAMAÇÃO, ENTRE EM CONTATO CONOSCO PARA QUE POSSAMOS AJUDAR. ATENÇÃO A EMPRESA NÃO SE RESPONSABILIZA POR MAU USO OU INSTALAÇÃO INCORRETA. RECOMENDAMOS INSTALAÇÃO POR PROFISSIONAL ESPECIALIZADO. cubo de roda cofap crc01007 volkswagen fox crossfox polo spacefox traseiro com abs rolamento original cofap cubo durável resistente segurança estabilidade qualidade oem reposição automotiva', 529.99, 487.6, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-824hh-mezxyqxg3spb22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1456324506%2F23398925093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
