INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204085421', 'Kit Ultra Led Nano Fiat Fiorino 1990 A 2003 H4 30000lm', 'Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - 2 Super Led nano R8 - H4 - Alto e Baixo - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Aplicação: Fiat Fiorino 1990 Aplicação: Fiat Fiorino 1991 Aplicação: Fiat Fiorino 1992 Aplicação: Fiat Fiorino 1993 Aplicação: Fiat Fiorino 1994 Aplicação: Fiat Fiorino 1995 Aplicação: Fiat Fiorino 1996 Aplicação: Fiat Fiorino 1997 Aplicação: Fiat Fiorino 1998 Aplicação: Fiat Fiorino 1999 Aplicação: Fiat Fiorino 2000 Aplicação: Fiat Fiorino 2001 Aplicação: Fiat Fiorino 2002 Aplicação: Fiat Fiorino 2003 Lâmpadas Super Led 30000 Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED R8* CARACTERISTICAS: - Potência: 30000lm - Vida útil: 30000 horas - Temperatura: 6500k - Cor clara: Branco - Consumo: 42w - Tensão: 12v - Ligado: Instantâneo - Resfriamento: Dissipador de calor Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 78.9, 78.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Dry Bags', 'https://cf.shopee.com.br/file/sg-11134201-82631-mjyjai37xs7b8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F58204085421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097652302', 'Lâmpadas Ultra Led Chevrolet Vectra 20000lm Alto Baixo e Milha + Pingo Led', 'Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem (1993 a 1995): - 2 Super Led H4 - Alto e Baixo - 2 Super Led H3 - Milha - 2 Pingo Led - Chicotes - Manual do Usuário Conteúdo da Embalagem (1996 a 2011): - 2 Super Led H7 - Alto - 2 Super Led H1 - Baixo - 2 Super Led H3 - Milha - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Lâmpadas Super Led 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED V10* Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lâmpada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias do Fabricante.', 119.9, 119.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-mdnlhmzrz3rl5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23097652302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
