INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094158651', 'Areia Granulado Fina Biodegradável 4Kg Natural Chalesco', 'GRANULADO SANITÁRIO 4KG CHALESCO PRODUTO ORIGINAL COM NOTA FISCAL O Granulado Sanitário PeePoop da Chalesco é a escolha ideal para quem busca praticidade, economia e bem-estar para seu pet. Produzido com mandioca, é 100% natural, biodegradável e ecológico, eliminando até 99,9% dos odores e garantindo um ambiente sempre limpo e agradável. Com granulometria fina e toque suave, forma torrões firmes que facilitam a limpeza diária, além de render muito mais que as areias comuns. Pode ser utilizado também para coelhos, roedores e aves. O descarte é fácil, podendo ser feito no vaso sanitário com responsabilidade ou no lixo comum. Zero desperdício, fácil de manusear e super eficiente no controle de odores — tudo o que você precisa em um só produto! Garantia: 7 Dias', 99.9, 59.0, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rasm-mb5mtvmt6b0w9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F23094158651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263767413', 'Rack para TV até 75 Polegadas 3 Portas 180cm Kappesberg Canela', 'Transforme sua sala de estar com a beleza e a qualidade do Rack 3 portas T272 da Kappesberg. Com um design clássico, ele se encaixa perfeitamente em todos os espaço. São 53cm de altura, 1,80m de largura e 42cm de profundidade, produzido em MDP de 15mm, o que garante mais robustez, firmeza e qualidade ao seu produto, além de um acabamento lindo. E com pintura na cor canela, em acabamento touch, conta com a textura dos veios da madeira, perfeito para quem busca por um ambiente clássico e aconchegante. Remetendo aos tons da natureza, você terá o espaço ideal para receber sua família e amigos com conforto e beleza. Com duas portas laterais e uma porta basculante central, você terá amplo espaço para guardar seus itens com praticidade, deixando sua sala de estar sempre organizada, além suportar TVs de até 75''. A base e os pés completam o design e a qualidade do produto, garantindo seu acabamento clássico. Nas portas, o destaque fica para o sistema de amortecimento, garantindo um fechamento suave e sem ruídos, além de mais durabilidade, e os puxadores em chapa J dourado completam a beleza do produto, deixando sua sala de estar perfeita. Medidas: • 53 cm de altura • 180 cm de largura • 42 cm de profundidade Itens inclusos: • Três (3) portas de bater Código do produto: T272-CN Informações importantes: • As imagens são ilustrativas. • A Kappesberg não disponibiliza serviço de montagem (recomendamos a contratação de um profissional qualificado). • O manual de montagem acompanha o produto. • 3 meses de garantia para defeitos de fabricação.', 649.99, 649.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqc8im9z3aps6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F58263767413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
