INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42604046217', 'Livro Principis Papa Leão XIV', 'Nascido nos subúrbios de Chicago, formado no rigor da fé e forjado no calor das missões latino-americanas, Robert Francis Prevost não buscou os palcos do poder. Caminhou entre os pobres, escutou os esquecidos, cuidou dos feridos._x000D_ Esta biografia traça, com sensibilidade e profundidade, a jornada de um homem discreto que se tornou Papa não por ambição, mas por coerência com o Evangelho. Um líder que escuta mais do que fala, age mais_x000D_ do que promete, acredita que a reforma da Igreja começa pela conversão do coração._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2025_x000D_ Autor: Walter Bukunovicky_x000D_ Idioma: Português_x000D_ Páginas: 96_x000D_ Dimensões: L 15.50 x A 22.60 x E 1.00_x000D_ ISBN: 9786550972134_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Principis - Autores contemporâneos_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): Religião, Fé., Deus, Catolicismo, Reflexão, Igreja, Vaticano, Papa_x000D_ BISAC: Religião / Religião / Biografia Bíblica_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 24.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ravj-matys6uwk40ha2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42604046217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
