INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203355091', 'Camiseta Palmeiras Betel 1914 II Infantil Verde/Branco', 'A camisa do Palmeiras, modelo 1914 III, é ideal para os jovens fanáticos pelo Verdão exibirem seu orgulho em todos os momentos. Feita em poliéster leve, a peça possui design na cor verde, além de contar com o escudo do clube estampado em destaque. INFORMAÇÕES TÉCNICAS: Composição: 100% Poliéster Cor predominante: Verde Escudo: Estampado Origem: Nacional Gênero: Unissex Clube: Palmeiras Idade: Juvenil Manga: Curta Gola: Careca Medidas Aproximadas (Altura x Largura): 08: 54 x 42 cm 10: 56 x 44 cm 12: 58 x 46 cm 14: 60 x 48 cm .', 129.9, 129.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mjiq0j9dyz9ga3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1332710855%2F58203355091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24398183130', 'Garrafa Max 500ML Jessie Toy Story Zona Criativa - 10074021', 'Você viveu um dia cheio de aventuras, mas não consegue se hidratar? A gente te ajuda! Com 500ml de capacidade para você sobreviver a todos os contos de fada! Com uma pegada confortável, e uma tampa rosqueável, é a companhia perfeita para a sua mochila!A garrafa é importada, feita em aço inoxidável, possui detalhes incríveis que vão fazer você se apaixonar! Se você busca uma garrafa que te acompanhe na faculdade, trabalho ou escola, você encontrou a companhia perfeita! Com 500ml de capacidade para te hidratar o dia inteiro, com uma tampa rosqueável, envolta por uma tira de silicone para evitar vazamentos, caso você precise levar na bolsa ou mochila! Feita em aço inox, ajuda a manter a temperatura da sua bebida por até 6h! Não importa onde é a sua aventura, essa garrafa te acompanha em todos os lugares!EspecificaçõesAltura 23,5cm| Largura 7cm| Comprimento 4cm| Capacidade 500ml| Material Aço inoxidávelCuidados e recomendações de usoNão preencha com líquidos até a superfície, deixe pelo menos 1,5cm de espaço para poder fechar o copo.Choques ou quedas podem trincar ou quebrar o produto.Não é a prova de pequenos vazamentos, carregue o produto apenas na posição vertical e não coloque em bolsas ou mochilas.Lavar com água, esponja macia e sabão neutro.Não recomendado colocar no freezer.Não vai á lava-louças, nem ao micro-ondas.Não utilizar produtos químicos e abrasivos. Características: - Marca:Zona Criativa - Modelo:10074021 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Garrafa Max 500ML Jessie Toy Story', 119.52, 107.57, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-823oz-mogzfb2bu1vw1d', 'https://shope.ee/an_redir?origin_