INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20072154439', 'Bule Viena 750ml com Gatilho Verde Lime Invicta', 'O Bule Viena da Invicta é um clássico da Invicta, e é sinônimo de tradição e estilo. Com um design elegante e atemporal, ele oferece uma experiência de servir impecável, graças à sua rolha gatilho e bico corta-gota, que garante precisão e praticidade a cada uso. Com ampola de vidro, ele mantém a temperatura ideal de suas bebidas, seja café, chá ou qualquer outro líquido. O Bule Viena é mais do que um item funcional, ele é um companheiro indispensável que combina resistência, charme e eficiência. Porque momentos especiais merecem ser servidos com estilo. CARACTERÍSTICASCapacidade: 750mlConservação térmica eficiente: Ampola de Vidro que permite 12h Frio e 6h QuenteRolha gatilho: Praticidade e precisão ao servir.Bico corta gotas: Evita respingos e sujeiras indesejadas.Design sofisticado e resistente: Perfeito para qualquer ambiente e uso contínuo. COMPOSIÇÃOFabricado com materiais de alta qualidade, garantindo resistência e excelente desempenho térmico.', 49.9, 49.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-825aa-mqw7a1dxhedde3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859051456%2F20072154439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199053838', 'Sofá Modular Luma Bouclê para Sala Moderna - Balaqui Decor', 'O Sofá Modular Luma Compact Air é a escolha perfeita para quem busca conforto, funcionalidade e design inteligente em ambientes compactos. Embalado à vácuo e entregue na caixa, ele foi desenvolvido para facilitar o transporte e a montagem, cabendo com facilidade em apartamentos, studios, salas pequenas, quartos ou espaços multifuncionais. Seu estofado em tecido bouclê macio, estrutura reforçada e chaise integrada proporcionam um visual moderno e aconchegante para compor qualquer ambiente com elegância e praticidade. Perfeito para quem valoriza conforto sem abrir mão de espaço. Especificações do produto - Tecido em Bouclê - Espuma de densidade D-28 - Produto prensado e enviado a vácuo e na caixa - Sua estrutura é composta por módulos; Informações Técnicas - Altura: 63 cm - Largura: 275 cm - Profundidade: 80 cm - Peso: 50 kg Capacidade de Suporte: O produto suporta até 200 kg em cada módulo Produto embalado - Altura: 107 cm - Largura: 48 cm - Profundidade: 91 cm - Peso: 50 kg Observações Importantes - O produto tem 3 meses de garantia contra defeitos de fabricação - Produto possui uma embalagem segura, feita para evitar danos durante o transporte Prazo de entrega: 8 a 15 dias úteis, de acordo com a região - O Produto é entregue com a sua estrutura montada. Você terá apenas que retirar da caixa, abrir o plástico, retirar o vácuo conforme a foto e/ou vídeo do anúncio; - A cor real pode variar ligeiramente devido às configurações da tela e ao tratamento das imagens - O Prazo de envio é de 8 dias úteis após a confirmação da compra e enviamos para todo o Brasil - Não nos responsabilizamos por subida de escada no ato da entrega Perguntas Frequentes Como devo limpar? - Realizar a limpeza do tecido com um pano seco ou levemente umedecido Quantos produtos irei receber nesta compra? - Você receberá 1 volume, ou seja, apenas um Sofá Modular Luma Compact Air Para mais informações ou assistência com sua compra, nossa equipe está à disposição para ajudar', 4999.9, 3199.9, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-823ri-mp0uyii1tssre7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427283392%2F23199053838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
