INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20098485732', 'MÁSCARA DE NUTRIÇÃO PROFUNDA - JOICO K-PAK COLOR THERAPY 150 ml', 'O Joico K-PAK Color Therapy Luster Lock é um tratamento intensivo que oferece brilho imediato, reconstrução e proteção da cor para cabelos coloridos e danificados. Com resultados visíveis desde a primeira aplicação, ele age como um verdadeiro "milagre instantâneo" para cabelos sem vida, devolvendo luminosidade, força e sedosidade. ESPECIFICAÇÕES TÉCNICAS: Marca: Joico Cor: Dourado intenso Textura: Cremosa e rica Peso líquido: 150ml Origem: Importado (EUA) Indicação: Cabelos coloridos, danificados, opacos e sem vida Fórmula: Complexo Peptídico Quadrabond™, óleo de argan, óleo de manketti, antioxidantes Ação: Brilho instantâneo, reconstrução e proteção da cor Frequência de uso: 1 a 2 vezes por semana ou conforme necessidade Tipo de uso: Profissional e home care Produto lacrado e com selo de originalidade Benefício: Resultados visíveis já na primeira aplicação Benefício: Restaura o brilho e a maciez de cabelos opacos Benefício: Prolonga a vida da cor e fortalece a estrutura dos fios Garantia: Produto original com garantia de procedência CUIDADOS Evite contato com os olhos. Manter fora do alcance de crianças. Uso externo. Armazenar em local fresco e longe da luz solar.', 281.2, 177.16, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7qvco-lgbcct2iuc3kae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F525611242%2F20098485732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893987454', 'Lápis de cor 12 cores Tons de Pele 112634 Faber-Castell', 'INMETRO 000777/2013 Explore a diversidade e crie representações mais inclusivas com o Lápis de Cor Faber-Castell 12 Cores Tons de Pele. Especialmente desenvolvido para proporcionar uma ampla gama de tons de pele, este conjunto permite retratar pessoas de diferentes origens de forma realista e respeitosa. Detalhes: - Formato sextavado - Cores mais vivas e ótima cobertura - Mina macia e ultra resistente a quebras - 12 tons de pele: valorização da diversidade étnico-racial', 33.48, 33.48, NULL, 'Stationery > Art Supplies > Color Pencils', 'https://cf.shopee.com.br/file/sg-11134201-7rfg4-m9yt3wzbnteqa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22893987454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399441390', 'Porta lápis aramado Preto 2090.P Dello', 'O Porta Objetos Dello Redondo Aramado 2090P é a solução perfeita para manter sua mesa organizada com praticidade e estilo. Produzido em aramado resistente e com acabamento preto elegante, ele oferece durabilidade e um design moderno que combina com qualquer ambiente. Ideal para armazenar pequenos itens do dia a dia, garantindo mais eficiência e facilidade na rotina. Detalhes: - Formato: Redondo - Material: Aramado metálico - Cor: Preto - Ideal para organização de pequenos objetos - Alta durabilidade e resistência - Dimensões: 80 x 80 x 90mm *Imagem ilustrativa, não acompanha acessórios.*', 24.88, 24.88, NULL, 'Home & Living > Home Organizers > Desk Organizers', 'https://cf.shopee.com.br/file/sg-11134201-81zve-mmpzb3aohn9hbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22399441390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598861530', 'Pincel para pintura Soft Touch Pastel 481691 com 4 unidades Faber-Castell', 'Os pincéis Soft Touch da Faber-Castell são ideais para uma variedade de atividades que estimulam a criatividade. A cartela inclui quatro pincéis com pontas diversas, possibilitando a criação de traços de diferentes tamanhos. Esses pincéis são versáteis e podem ser utilizados tanto em projetos escolares quanto por entusiastas que buscam um hobby criativo. Detalhes: - Kit para pintura, Soft Touch - Ideal para qualquer tipo de uso: artístico, escolar e hobby - Sua exclusiva área de pega macia e antideslizante proporciona mais conforto e melhor manuseio. - 4 Pincéis nas cores pastéis.', 37.92, 37.92, NULL, 'Stationery > Art Supplies > Paint Brushes', 'https://cf.shopee.com.br/file/sg-11134201-824j8-me02mkhanz7ke3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22598861530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093565525', 'Bíblia Todo Dia com Espaço para Anotações | AM | Letra Normal | Capa Dura Outono', 'Bíblia Todo Dia com Espaço para Anotações | AM | Letra Normal | Capa Dura Outono A Bíblia Todo Dia é uma forma de explorar as Escrituras com flexibilidade e disciplina. Para cada dia, você encontrará trechos cuidadosamente selecionados do Antigo Testamento, Novo Testamento e Salmos, além de um espaço dedicado para anotações ou expressões criativas. Essa experiência te auxiliará na rotina diária de leitura Bíblica. A Bíblia Todo Dia será sua aliada nessa jornada espiritual, enriquecendo seu tempo com Deus e Sua Palavra! Altura: 21,5 cm Largura: 14,5 cm Profundidade: 3,0 cm Páginas: 1206 fitilho Único', 89.9, 76.42, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rffi-m30l4ylofwy1ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22093565525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997635908', 'Livro lançamento Queimando no Secreto | Fabiano Ribeiro', 'Queimando no Secreto | Fabiano Ribeiro Com Fabiano Ribeiro"Queimando no Secreto" é uma obra reveladora do autor Fabiano Ribeiro, lançada pela editora Inspire em 2024. Neste livro, o autor utiliza a simbologia do fogo, representando o Espírito Santo nas Escrituras Sagradas, para conduzir os leitores a experiências espirituais profundas. Através de vivências transformadoras, busca-se avivar o leitor, promovendo um despertar espiritual e possibilitando uma parceria íntima com o Espírito Santo. Descubra como alcançar novos patamares de crescimento espiritual ao queimar no secreto. Especificações do livro :Título:Queimando no SecretoSubtítulo:Vivências que Ativam seu Relacionamento com DeusAutor(es):Fabiano RibeiroAno de Edição:2024Capa:Brochura Acabamento:Laminação FoscaMiolo:Papel Pólen Páginas:176Dimensões:Altura: 20 cm Largura: 14 cm Profundidade: 0,5 cm Peso:0,240 kgISBN:9788577081646Editora:Editora Inspire', 40.78, 40.78, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rcd1-lsttqt991rvieb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20997635908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
