INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299159499', 'Câmeras De Ré Automotiva 70mai Rc11 1080p 130°Camera de Carro Acessórios para A200/s500/A810/A510', 'Observação: este produto é um acessório — uma câmera traseira — projetado para uso com uma câmera de painel e não pode ser operado de forma independente. Nome do produto: Câmera traseira 70mai RC11 Modelo: Midrive RC11 Dashcams compatíveis: A200/S500/A400/A500S/A800S/A810/A510 Chip: FH8536V200 Sensor de imagem: GC2053 Taxa de quadros: 25 Resolução: 1920 x 1080 Lente/Abertura: F2.0/2G2P Campo de visão: 130° Temperatura de operação: Recomendada entre -10 °C e 60 °C Temperatura de armazenamento: -20 °C a 70 °C Dimensões do produto: 33,5 × 36 × 61 mm Comprimento do cabo: 5,5 m + 0,5 m = 6 m Método de montagem: Adesivo de alta temperatura + suporte estático Posição de montagem: Para-brisa traseiro, voltado para fora HDR: Não compatível Interface: Conector mini de 8 pinos Termos da garantia: 1.Produto 100% genuíno. A câmera para painel vem com garantia de 1 ano . 2.Para mais dúvidas/serviço pós-venda, os clientes podem entrar em contato conosco pelo chat da loja.', 499.0, 197.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Cameras', 'https://cf.shopee.com.br/file/sg-11134201-821f0-mgrsikto50y252', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1645033694%2F23299159499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49309946259', 'O Discípulo Radical | Estudos Bíblicos', 'O Discípulo Radical | Estudos Bíblicos John Stott, Reinaldo Percinoto Jr Este livro apresenta 8 estudos bíblicos desenvolvidos a partir da reconhecida obra O Discípulo Radical de John Stott, oferecendo uma abordagem estruturada para compreender as características essenciais do discipulado cristão. Com base sólida no texto bíblico e perspectiva cristocêntrica, constitui o primeiro volume da Série Estudos Bíblicos Ultimato. A obra explora os fundamentos do discipulado através de uma metodologia que combina o conhecimento teológico de John Stott com a organização didática de Reinaldo Percinoto Jr. Cada estudo foi cuidadosamente preparado para proporcionar uma compreensão profunda dos princípios bíblicos que definem a vida cristã autêntica, mantendo Cristo como centro de toda reflexão. 8 estudos bíblicos estruturados sobre discipulado cristãoBaseado na obra consagrada O Discípulo Radical de John StottAbordagem cristocêntrica fundamentada no texto bíblicoPrimeiro volume da Série Estudos Bíblicos UltimatoFormato prático com 64 páginas para estudo individual ou em grupoUma ferramenta valiosa para quem busca aprofundar sua compreensão sobre os princípios bíblicos do discipulado, oferecendo conteúdo sólido e metodologia acessível para o crescimento espiritual fundamentado nas Escrituras. Especificações do livro O Discípulo Radical | Estudos Bíblicos: Título: O Discípulo Radical | Estudos Bíblicos Autores(es): John Stott, Reinaldo Percinoto Jr Ano de Edição: 2026 Capa: Brochura Páginas: 64 Dimensões: 15 x 12 x 0,4 cm Peso: 100 g ISBN: 9788577793488 Idioma: Português Editora: Ultimato Família: Livros Assunto: Estudo, Desenvolvimento, Vida Cristã, Teologia, Discipulado', 14.68, 14.68, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-822yn-mo5i97yosphi1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F49309946259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44450670757', 'Livro Lugar de Mulher é Onde Ela Quiser | Patricia Lages', 'Livro Lugar de Mulher é Onde Ela Quiser O manual para quem quer vencer na carreira profissional ou empreender seu próprio negócio? Ser uma mulher empreendedora não significa apenas abrir um negócio ou trabalhar por conta própria. Empreender é um verbo que toda mulher que deseja ser bem-sucedida deve conjugar. Seja como funcionária de carreira, profissional liberal, freelancer ou empresária, a mulher quer mais do que trabalhar: ela deseja ter a liberdade de conquistar o seu espaço. Não o lugar onde dizem que ela deve estar, mas aquele em que ela escolheu estar. Em Lugar de mulher é onde ela quiser, Patricia Lages desvenda os segredos do mundo corporativo e dos caminhos do empreendedorismo com dicas práticas e valiosas com base em sua própria experiência e em extensas pesquisas. Com um texto bem-humorado e envolvente, Patricia descomplica o tema e mostra que empreender é um estilo de vida que tem tudo a ver com o universo feminino. Especificações do livro Plena Satisfação em Deus Título: Lugar de Mulher é Onde Ela Quiser Subtítulo: O manual para quem quer vencer na carreira profissional ou empreender seu próprio negócio? Autor(es): Patricia Lages Ano de Edição: 2016 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel Polen Páginas: 264 Dimensões: Altura: 23 cm Largura: 15,5 cm Profundidade: 1,5 cm Peso: 0,400 kg ISBN: 9788578609030 Editora: Thomas Nelson', 39.31, 39.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9kn56bijprt30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F44450670757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
