INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19473546180', 'Lixeira Meia Lua Brinox Decorline 8 Litros 20x30cm Aço Inox', 'Lixeira Meia Lua Brinox Decorline 8 Litros Ø20 x 30 cm Aço Inox Alto Brilho – Compacta, Elegante e Funcional Ideal para ambientes que exigem praticidade sem abrir mão do design, a Lixeira Brinox Decorline 8 Litros oferece resistência, visual sofisticado e tamanho compacto. Perfeita para banheiros, lavabos, cozinhas, escritórios e espaços menores, ela combina com qualquer estilo de decoração. Destaques que fazem a diferença: Tampa basculante em formato meia-lua: mais discrição, evita a exposição do conteúdo e a propagação de odores Corpo em aço inox alto brilho: durável, higiênico e fácil de limpar Base plástica protetora: evita contato direto com o chão e preserva o produto Design compacto: encaixa perfeitamente em ambientes com pouco espaço Características técnicas Capacidade: 8 Litros Dimensões: Ø20 x 30 cm Material: Corpo em aço inox alto brilho com base plástica Tampa: Basculante em formato meia-lua Indicação de uso: Banheiros, lavabos, escritórios, cozinhas Cuidados com o produto Para manter o brilho do inox, lave com esponja macia e sabão neutro. Evite o uso de palha de aço e produtos abrasivos. Enxágue bem e seque logo após a lavagem. Aposte na praticidade e elegância da linha Decorline Brinox e mantenha seus espaços sempre organizados com estilo.', 209.99, 157.5, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5320bi1scdu59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F19473546180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
