INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298812142', 'Lâmpada Led Ix35 Hyundai 2010 A 2015 Kit V10 - Efeito Xênon', 'Seja bem-vindo(a) à sua Loja! Produto: Kit Super LED V10 para Hyundai ix35 2010 a 2015 – Iluminação Branca com Efeito Xênon ILUMINAÇÃO DE ALTA PERFORMANCE – PARA QUEM EXIGE ESTILO, SEGURANÇA E VISIBILIDADE EM QUALQUER ESTRADA Dê um upgrade no seu IX35 com o Kit Super LED V10! Desenvolvido para máxima eficiência luminosa e visual moderno, ele proporciona 20000 lúmens por par e tonalidade branca 6500K, garantindo iluminação intensa, segura e com efeito xênon. Fácil de instalar, com encaixe perfeito e acabamento profissional. Destaques do Produto Iluminação de Alta Intensidade: 20000 lúmens (par) para visibilidade superior Tonalidade 6500K (Branco Puro): Estilo xênon com iluminação limpa Tecnologia Alemã: Alta durabilidade, desempenho térmico e eficiência Sistema Plug & Play: Instalação rápida, sem cortes ou adaptações Kit Completo: Tudo o que você precisa em um só pacote Conteúdo da Embalagem 2x Lâmpadas Super LED H27 (Milha) 2x Lâmpadas Super LED H7 (Alto) 2x Lâmpadas Super LED H7 (Baixo) 2x Lâmpadas Pingo LED Chicotes de Instalação Manual do Usuário Aplicações Compatível com: Hyundai IX35 2010 Hyundai IX35 2011 Hyundai IX35 2012 Hyundai IX35 2013 Hyundai IX35 2014 Hyundai IX35 2015 Especificações Técnicas Tonalidade da Luz: 6500K (Extremamente Branca) Luminosidade: 20000 lúmens (par) Potência: 30W por lâmpada Voltagem: 12V Vida Útil: Até 2x mais que LEDs convencionais Material: Corpo e base metálicos Resistência: À prova d’água, calor e vibrações Dissipação de Calor: Cooler embutido em cada lâmpada Chip: Importado de alta potência Dimensões: 9 cm (altura) x 4 cm (comprimento) Benefícios Segurança Total: Luz mais forte e com maior alcance Baixo Consumo: Iluminação potente sem sobrecarregar a bateria 