INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43531281077', 'KIT COM 05 Revista Lições Bíblica Primários Aluno 3º Trimestre 2026', 'Voltada para crianças de 7 e 8 anos, possui várias ilustrações e exercícios que aliam o conhecimento bíblico à alfabetização. Totalmente reformulada de acordo com orientação pedagógica e didática, com conteúdos didáticos atualizados, utilizando a Nova Tradução na Linguagem de Hoje e um mascote, que acompanhará o estudo semanal da criançada. Tema: As Crianças da Bíblia Sumário: Lição 1 –As Crianças Que Receberam Uma Grande Promessa Lição 2 – A Criança Que Ajudou A Salvar O Irmão Lição 3 – Uma Criança Profeta Lição 4 – O Menino Rei Lição 5 – De Criança Órfã À Rainha Lição 6 – A Menina Que Salvou Um Guerreiro Lição 7 – Um Menino Pastor Lição 8 – O Deus 11 Menino Lição 9 – As Crianças Que Foram Abençoadas Por Jesus Lição 10 – A Criança Que Virou Um Exemplo Lição 11 – A Criança Que Ressuscitou Lição 12 – A Criança Que Ajudou Jesus Lição 13 – Você É Uma Criança Escolhida Por Deus! 27X20 CM 32 Páginas', 60.9, 52.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-820lf-mozoavm6xb0j39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F43531281077', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12838728125', 'Beleza em vez de cinzas - Joyce Meyer', 'Não importa qual fogo de adversidade tem atuado em sua vida, você também, pode receber beleza no lugar de suas cinzas Adquira uma maior compreensão desta mensagem através de notas de estudo de Joyce É tempo de fazer uma grande troca... é tempo de entregar a Deus suas dores e feridas e deixá-Lo dar a você a cura e restauração que sua alma anseia e é direito seu através de Jesus Cristo. Descubra como receber a beleza de Deus para suas cinzas. 266 Páginas 14x21cm', 36.9, 31.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/a91c2ed5fd5a806422c4819633d15b3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12838728125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292425678', 'Puzzle 2000 peças Vista do Castelo', 'Da janela desta casa é possível deparar com uma vista de tirar o fôlego: um exuberante castelo erguido nas montanhas gélidas, que indicam uma recente nevasca na região. Apesar do céu límpido, as árvores mais abaixo cobertas pela neve simbolizam a resiliência de um lugar que enfrenta temperaturas adversas, ao mesmo tempo em que torna mágica e única a atmosfera a seu redor. Os objetos dispostos na janela deixam a cena ainda mais encantadora e talvez nos revelem parte da rotina de quem morava ali em tempos antigos: o gosto pela literatura, a admiração pelo castelo, a pontualidade e o prazer em viver num local tão privilegiado! Sinta-se parte dessa casa e monte as 2.000 peças para apreciar e se surpreender com esta vista espetacular ! Dimensões aproximadas 70,4 x 97,8 cm Contém 2000 peças A partir de 12 anos', 144.99, 114.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7r9c7-lluxpny4b9nt5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F22292425678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19975020967', 'Auxílio Para Obreiros | Charles Spurgeon', 'Auxílio para Obreiros é um guia de orientação para ministros da igreja, escrito sabiamente por um dos maiores pregadores do protestantismo inglês, o chamado Príncipe dos Pregadores, Charles Spurgeon. Publicado em 1896, esta obra reúne uma série de conselhos e instruções para a caminhada no ministério bíblico, independente do nível de experiência que se tenha, de forma alinhada e centralizada com os princípios do Evangelho. Uma leitura agradável e carregada de sabedoria bíblica para enfrentar as dificuldades e os desafios nos trabalhos para Cristo. 14x21cm 112 Páginas', 22.9, 17.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-23030-rklrd3stt0nv9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19975020967', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
