INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093140465', 'Violão Giannini Start S14 Aço + Capa + Afinador Kit Full', 'VIOLÃO ACÚSTICO AÇO GIANNINI S-14 START ESTUDO NATURAL ACOMPANHA -01 CAPA REFORÇADA EM NYLON 600 -01 AFINADOR -01 CAPOTRASTE -03 PALETAS A START é a nova séria de violões da Giannini. O Giannini Start S-14 é um violão leve, confortável e de boa qualidade. Um violão ideal para quem quer aprender a tocar já com um instrumento de cordas de aço. O S-14 foi produzido pela Giannini pensando no músico iniciante, um violão preparado para dar todo o suporte ao aprendizado de violão. Este Start chega para complementar a já conhecida linha estudante GSX15 da Giannini. Além disso, o violão também é excelente para quem já toca e quer um instrumento leve para deixar no carro, levar para cima e para baixo, animar as rodas de amigos, tocar suas músicas em casa, ou qualquer lugar que você vá. O Giannini S-14 é perfeito para dar o "Start" na sua vida musical. Aproveite!Tipo:Acústico Cordas:Aço Cor:Preto Tampo:Linden Faixa e Fundo:Linden Acabamento:Verniz Brilhante Braço:Catalpa / Solid Basswood Escala:Maple Escurecido Tarraxas:3+3 Niqueladas Pino Grosso Trastes:19 em Alpaca Pesquisa:gs14|gs-14|gs 14|preto|preta|estudo|acustico|start|giannini', 469.0, 469.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-81zum-ml279yre6dj5ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22093140465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
