INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45710332733', 'Speaker Philco Connection Bluetooth V.5.3 50W PBS56', 'A Speaker Philco PBS56 é ideal para quem busca potência, praticidade e conexão sem fio para ouvir músicas com mais qualidade no dia a dia. Com 50W de potência e Bluetooth V5.3, oferece uma experiência sonora estável, moderna e eficiente para diferentes ambientes. Seu design funcional facilita o uso em momentos de lazer, reuniões, festas, encontros com amigos ou para deixar a rotina mais animada. A conexão Bluetooth permite reproduzir músicas diretamente de dispositivos compatíveis, como celulares, tablets e notebooks, sem a necessidade de cabos. Com a qualidade Philco, a Speaker PBS56 combina desempenho, versatilidade e praticidade em um único produto, sendo uma ótima opção para quem deseja som potente e facilidade de conexão. Marca: Philco Modelo: PBS56 Tipo de produto: Caixa de som speaker Potência: 50W Conexão: Bluetooth V5.3 EAN: 7891356124303 Indicada para uso em ambientes internos, lazer, festas e uso cotidiano Conexão sem fio com dispositivos compatíveis Design prático e moderno', 499.0, 154.0, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-820lx-mptpz08ds1kz97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1509845472%2F45710332733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
