INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697491233', 'Spray Filtro Solar Termoativado Hair Sun Protect Jacques Janine 60ml', 'O SPRAY HAIR SUN PROTECT NUTRE, HIDRATA E BLINDA OS FIOS CONTRA AS AGRESSÕES QUE SÃO INTENSIFICADAS DURANTE O VERÃO, COMO A EXPOSIÇÃO AOS RAIOS UV, O SAL E O CLORO DA ÁGUA. ALÉM DISSO, MANTÉM OS CABELOS COLORIDOS PROTEGIDOS, UMA VEZ QUE MINIMIZA O DESBOTAMENTO DA COR. Modo de Uso PODE SER USADO TANTO NOS CABELOS SECOS QUANTO NOS ÚMIDOS E MOLHADOS, VOCÊ SÓ PRECISA BORRIFAR O PRODUTO PELO COM PRIMENTO E PELAS PONTAS PARA GARANTIR A PROTEÇÃO DOS FIOS. POR ISSO, É IMPORTANTE LEVÁ-LO NA BOLSA QUANDO FOR À PRAIA OU À PISCINA, PARA REAPLICAR DEPOIS DE MERGULHAR E REATIVAR O FILTRO UV. Composição AQUA, AMIDO BISPROPYL DIMETHICONE, TRIDECETH-12, TEA- DODECYLBENZENESULFONATE, CETRIMONIUM CHLORIDE, ETHYLHEXYL METHOXYCINNAMATE, AMODIMETHICONE, DMDMHYDANTOIN, PARFUM, CITRIC ACID, DISODIUM EDTA, PEARL EXTRACT, CAVIAR EXTRACT, COCOS NUCIFERA OIL.', 36.9, 32.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-lv21pcapqiqrea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F23697491233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
