INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9170299245', 'Livro - Frankenstein - Capa comum - Principis', 'Victor Frankenstein concluiu seu projeto. Depois de anos de estudos e dedicação, é chegada a hora de dar vida à matéria morta. Ressurreição. Uma nova espécie. Mas o encontro entre criador e criatura não é exatamente o que se espera. Rejeitado, o novo ser agora vaga pelo mundo. O que será capaz de fazer? Haverá um preço para Viktor Frankenstein pagar pelas atrocidades que cometeu para atingir seu objetivo? Horror, medo, amor. A vida e a morte estão em jogo. Editora: Principis Edição: 1, 2021 Autor: Mary Shelley Idioma: Português Páginas: 96 Dimensões: L 15.50 x A 22.60 x E 0.80 ISBN: 9786555524666', 24.9, 24.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/eaac35493a5aee0389710268ff4ffc18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F9170299245', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
