INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997757222', 'Livro Literatura infantil O varal das vogais', 'Nesta encantadora obra infantil, Donaldo Buchweitz e Ieda Silva nos levam a um mundo mágico onde as vogais a, e, i, o, u, decidem se unir para uma grande festa. A cada página, acompanhamos a animação dos personagens e seus sons peculiares. Com ilustrações vibrantes de Júnior Caramez, o livro proporciona uma experiência lúdica e educativa, ideal para crianças em fase de alfabetização._x000D_ _x000D_ Editora: Ciranda na Escola_x000D_ Edição: 1, 2024_x000D_ Autor: Ieda Nilza da Silva, Donaldo Buchweitz_x000D_ Ilustrador: Júnior Caramez_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 26.00 x E 0.33_x000D_ ISBN: 9786553845350_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Alfabetização, Alfabeto, Lúdico, Aprendizado, Aliteração, Vogais_x000D_ BISAC: Literatura Infantil / Conceitos / Alfabeto_x000D_ Linha de Produto: Literatura infantil_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 39.9, 27.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-lzulys3hv3he06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22997757222', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
