INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898388322', 'Expositora Refrigerada Imbera 569 Litros VRS19S Full Black - Inverter Bivolt', 'Expositora Refrigerada Imbera 569 Litros VRS19S Full Black - Inverter BivoltA Expositora Refrigerada Imbera 569 Litros VRS19S Full Black - Inverter Bivolt é a solução ideal para quem busca eficiência, durabilidade e excelente apresentação dos produtos refrigerados. Com capacidade de 569 litros e acabamento na elegante cor preta, ela se destaca tanto pelo visual moderno quanto pelo alto desempenho. Seu design com porta de vidro proporciona ótima visibilidade interna, valorizando ainda mais os itens expostos e facilitando a escolha dos consumidores. Equipada com tecnologia de ponta, a VRS19S possui sistema de refrigeração que garante temperatura constante e uniforme, ideal para conservar bebidas e alimentos com máxima eficiência. O controle de temperatura é fácil e intuitivo, e o sistema de iluminação em LED contribui para melhor visibilidade interna, com menor consumo de energia. O equipamento ainda conta com prateleiras ajustáveis, que oferecem flexibilidade na organização dos produtos conforme a necessidade do estabelecimento. Outro grande diferencial é a garantia de 3 anos oferecida pela fabricante, reforçando o compromisso com qualidade e confiabilidade.', 6085.87, 6085.87, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-82604-mm8zkbnf320ybb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23898388322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
