INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23895980463', 'Desinfetante Uso Geral Pinho Sol Limão 1,75l', 'Desinfeta, limpa e perfuma com o poder da desinfecção e o perfume de Pinho Sol Limão, podendo ser utilizado em toda a casa. Benefícios: Pinho Sol é um desinfetante de uso geral de alta qualidade que limpa, desinfeta e perfuma o ambiente. Esse desinfetante perfumado elimina 99,9% das bactérias, germes e fungos. Sua fórmula gera um excelente rendimento, mantendo sua casa protegidas e perfumadas por muito mais tempo. Use em todos os cômodos da sua casa e em diversas superfícies, como: vaso sanitário, ralo, pia, tanque, azulejos e pisos. Deixa uma agradável fragrância de limão nos seus ambientes.', 31.19, 31.19, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7qvdt-lhxpi1bqs60546', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23895980463', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12213560853', 'Amaciante Downy Concentrado Lírios do Campo 3L', 'O Amaciante Downy Concentrado Lírios do Campo possui um cheiro suave de rosas com um toque de flor de laranjeira, que fixa no tecido. Dessa maneira, suas roupas ficam com um perfume que dura mais*, graças às microcápsulas de perfume especiais que liberam aquele cheirinho gostoso conforme o toque. O seu Downy roxo, Lírios do Campo, é concentrado, ou seja, todos seus ingredientes da fórmula têm menos água e estão em maior concentração, por isso que ele rende muito mais^ que o mesmo volume dos amaciantes diluídos comuns. O Downy 3L é muito econômico e rende até 132 lavagens se utilizado conforme a orientação da embalagem. Outro resultado fantástico que o seu Amaciante da marca nº1 do Brasil¨ traz é uma maciez incrível para os tecidos. Além de proteger a sua roupa contra maus cheiros°, incluindo fumaça, cheiro de fritura e peixe. Se combinado com o Sabão Líquido Ariel, as roupas ficam leves, confortáveis e lisinhas na hora de passar, além de ficarem protegidas contra os danos da lavagem. Modo de Usar: Para lavadoras de 9 a 14 kg ou lavagem à mão, utilize 1/3 de tampa (22,5 ml). Para mais perfume ou lavadoras maiores (+15 kg), utilize 1 tampa. · O amaciante Downy concentrado rende até 132 lavagens · Ótima proteção contra maus cheiros° e roupas macias para uma aparência impecável · Downy Lírios do Campo é um amaciante concentrado equivalente a 12L de amaciante comum^ · Suas cápsulas de perfume proporcionam uma fragrância que você sente a cada toque ^ Downy concentrado vs. amaciantes não concentrados baseado nas instruções de uso do fabricante ° Baseado em provas realizadas com conjunto de odores representativos. ¨ Baseado em dados Nielsen Brasil, para o ano de 2021 * Concentração de perfume depositada e liberada do tecido seco medida por métodos analíticos vs. amaciantes não concentrados', 77.49, 74.68, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-22110-ccyboc37b8jv9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12213560853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
