INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20798273377', 'Sandália Dakota de Salto Bloco Feminina Y9301', 'Produto marca Dakota. Prepare-se para elevar seu estilo com a Sandália Dakota de Salto Bloco, uma peça que combina conforto e sofisticação em cada detalhe. Desenvolvida para a mulher moderna, esta sandália apresenta um design elegante com tranças delicadas e tiras finas que abraçam seus pés, garantindo não apenas um visual impecável, mas também um ajuste perfeito. o salto bloco de 6 cm oferece a altura ideal sem perder a estabilidade, tornando-a perfeita para o dia a dia e momentos de lazer. Sinta a leveza e a praticidade com o fechamento em fivela, que proporciona um calce seguro, permitindo que você desfrute de cada passo com confiança. O destaque desta sandália está na fusão entre a tradição das tiras tramadas e o brilho contemporâneo das pedrarias aplicadas sobre o pé. Essa combinação exclusiva não só adiciona um toque de luxo discreto aos seus looks, mas também reflete a versatilidade do produto, ideal para transitar do ambiente de trabalho para um evento social com total desenvoltura. Feita em material sintético de alta qualidade, a Sandália Dakota é sinônimo de durabilidade e conforto prolongado, pesando apenas 0,625 kg para que seus pés se sintam leves durante todo o dia. Invista em você e experimente o poder da transformação que a Sandália Dakota de Salto Bloco oferece. Mais do que um simples calçado, ela é um convite a um estilo de vida onde elegância, conforto e praticidade caminham juntos. Adquira agora e descubra como pequenos detalhes podem fazer uma grande diferença no seu visual, elevando sua autoestima e garantindo que você esteja sempre impecável em qualquer ocasião. Peso: 0,625 kg Altura da sola: 6,00 cm', 199.9, 189.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mdka98wc7b9w3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F20798273377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21305268382', 'Em Busca da Espiritualidade | Carlos Queiroz', 'A espiritualidade não é mais uma abordagem de interesse apenas de pessoas religiosas. Aliás, o entendimento e a prática da "espiritualidade" podem significar tudo ou qualquer coisa. Assim, como lidar com as diferentes experiências religiosas, a mercantilização da fé e a multidão de promessas apresentadas nas igrejas e até mesmo em lugares impensáveis em outros tempos? Como discernir os critérios que podem nos levar de volta à espiritualidade bíblica? São estas, entre outras, as perguntas respondidas por Em Busca da Espiritualidade. 104 Páginas 14x21cm', 19.9, 19.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/6e7e2b11078d05bf47b84419c0f5ac21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F21305268382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
