INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192199408', 'Máscara Facial com Ácido Salicílico - Serum Face Mask 20ml', 'Hidratar a Pele E, de Quebra, Controlar a Oleosidade. com Esta Máscara Facial de Ácido Salicílico, Isso É Possível. Prática, a Máscara Facial de Tecido Possui Um Sérum Potencializador em Sua Embalagem. Ao Pressionar As Laterais do Produto, Conforme Descrito No Modo de Uso, o Sérum É Transferido para a Máscara de Tecido e Fica Pronto para Uso. Neste Caso, o Sérum Possui Ácido Salicílico, Conhecido Por Suas Propriedades Anti-Inflamatórias e Um Aliado No Combate à Acne. Ele Ajuda a Reduzir a Inflamação da Acne e a Desobstruir Os Poros, Além de Controlar o Nível de Oleosidade Na Pele.', 69.9, 49.9, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mqhptp1sutc018', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22192199408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
