INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293198492', 'Led Sinalizador de Alarme - 12V - DNI 5003', 'LED Sinalizador de Alarme DNI5003 12V Vermelho com Suporte O LED Sinalizador DNI5003 é ideal para indicar o funcionamento de sistemas de alarme, emitindo sinal luminoso intermitente que demonstra que o sistema está ativo. Prático e eficiente, contribui para a segurança do veículo ao inibir ações indesejadas. Características: Modelo: DNI5003 Função: Sinalizador de alarme ligado Voltagem: 12V LED na cor vermelho 3 fios para instalação Acompanha suporte Baixo consumo de energia Fácil instalação Aplicação: Sistemas de alarme automotivo Indicação visual de funcionamento do sistema Benefícios: Indica que o alarme está ativo Auxilia na prevenção de furtos Instalação simples e prática Produto compacto e eficiente Conteúdo da embalagem: 01 LED Sinalizador de Alarme com suporte Produto indicado para quem busca reforçar a segurança e ter uma sinalização clara do funcionamento do sistema de alarme.', 41.82, 41.82, NULL, 'Home Appliances > Electrical Circuitry & Parts > House Alarms', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-lydo1plew7xk91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F22293198492', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
