INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22695639757', 'Conjunto de 3 Potes refratário Hermético de Vidro com Trava', 'BEM-VINDO A ESTRELA DO LAR. Conjunto 3 Potes Refratário Mantimentos Hermético De Vidro Características: - 1 Pote de 330ml - 1 Pote de 570ml - 1 Potes de 840ml - Material: Vidro - Cor: Transparente - Tampa Hermética O jogo de potes são feitos de vidro e polipropileno, com tampas herméticas que mantenha seus alimentos armazenados de forma adequada e segura Sua tampa permite um alto nível de vedação, mantendo por muito mais tempo os alimentos conservados e protegidos tanto na hora guardar quanto transportar. Complementando ainda mais a sua versatilidade e praticidade, esses refratários podem ir no freezer, micro-ondas e máquina de lavar louças. Agradecemos o contato, atenciosamente Estrela do Lar.', 59.99, 59.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134201-820lg-mqxstegi62h297', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341754426%2F22695639757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993682563', 'Fralda Infantil Huggies Tripla Proteção G Com 30 Unidades', 'Fralda Infantil Huggies Tripla Proteção G com 30 Unidades A Fralda Infantil Huggies Tripla Proteção foi desenvolvida para garantir máximo conforto e segurança para o seu bebê. Com uma exclusiva camada tripla de proteção, oferece absorção eficiente e mantém a pele do bebê seca por mais tempo. Além disso, seu formato anatômico se adapta ao corpo da criança, proporcionando liberdade de movimento e bem-estar ao longo do dia. Principais Características: - Camada tripla de absorção: Garante maior proteção contra vazamentos, mantendo o bebê seco por até 12 horas. - Barreiras antivazamento: Laterais reforçadas para evitar escapes, proporcionando mais segurança. - Toque macio e respirável: Materiais suaves que ajudam a proteger a pele delicada do bebê. Benefícios: - Mantém a pele do bebê sequinha e protegida por mais tempo. - Design anatômico para melhor ajuste e conforto. - Fácil de vestir e remover, ideal para o dia a dia. - Dermatologicamente testada e segura para a pele sensível do bebê. Diferenciais do Produto: - Exclusiva tecnologia de tripla absorção. - Barreiras laterais altas para mais segurança contra vazamentos. - Cintura elástica para melhor ajuste ao corpo do bebê. Especificações Técnicas: - Peso: Embalagem com 30 fraldas tamanho G. Instruções de Uso: - Abra a fralda e posicione sob o bebê, ajustando as laterais e fixando as fitas adesivas de maneira confortável. Troque sempre que necessário para manter a pele do bebê seca e protegida. Avisos e Precauções: - Uso externo. - Mantenha fora do alcance de crianças. - Troque a fralda com frequência para evitar irritações na pele. O que está incluso? - 1 Pacote de Fraldas Infantis Huggies Tripla Proteção G com 30 unidades. ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 77.19, 58.99, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/br-11134207-820lz-mlc5zafa6nt1ee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F23993682563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
