INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299575669', 'Abafador de Ruído Tático Foxtrot – Tag', 'Abafador de Ruído Tático Foxtrot – Tag Para esportes táticos de alta performance, o Abafador de Ruído Foxtrot TAG é um aliado indispensável. Seu design tático, ajustável e seguro garante conforto e proteção em situações de alta intensidade. Confeccionado em plástico ABS de extrema leveza, o Foxtrot TAG é o companheiro ideal para ação tática. Seu arco em Courino proporciona ajuste personalizado para diversos perfis de usuários. Especialmente projetado para jogos de airsoft, seu formato de concha revestido com almofadas de espuma oferece conforto excepcional e proteção eficiente. Além da alta potência sonora dos esportes táticos, o Abafador de Ruído Foxtrot é uma escolha popular em jogos de airsoft. Seu acabamento almofadado e ajuste perfeito garantem conforto e segurança mesmo nas situações mais intensas. A limpeza é fácil, com um pano levemente umedecido, e o armazenamento ideal é em ambiente seco e arejado. Com dimensões de 11,5 cm (altura) x 10 cm (largura) x 11 cm (profundidade) fechado e peso de apenas 200g, o abafador é prático e eficiente. Disponível na cor preta, o modelo Foxtrot Preto oferece a qualidade que você busca em proteção auditiva. Especificações Marca: TAG Material: Plástico ABS e espuma Dimensões: 11,5 x 10 x 11 cm Peso: 200g Cor: Preto ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 119.9, 119.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7qvcz-lk78azu5l0jp9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F20299575669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
