INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999195039', 'Mini Veículos Die Cast Garagem S.A. - Esportivo Preto', 'A Garagem S.A. apresenta a coleção de mini veículos Die Cast, uma linha de modelos incríveis na escala 1:58 para os entusiastas e colecionadores. Com 24 modelos diferentes e uma variedade de cores, você terá a oportunidade de construir uma coleção única e diversificada. Cada mini veículo Die Cast é meticulosamente detalhado, capturando a essência e o estilo dos carros em escala reduzida. Os detalhes realistas, a pintura precisa e as cores vibrantes garantem uma experiência visual impressionante. Esses mini veículos são perfeitos para colecionadores e entusiastas de todas as idades. Eles são ótimos para exibição em estantes, dioramas ou simplesmente para se divertir em brincadeiras imaginativas. Entre no mundo emocionante dos mini veículos Die Cast da Garagem S.A. e comece sua jornada de colecionador. Explore os 24 modelos disponíveis, escolha suas cores favoritas e comece a construir uma coleção incrível.', 18.99, 18.99, NULL, 'Hobbies & Collections > Collectible Items > Vehicle Models & Diecast', 'https://cf.shopee.com.br/file/sg-11134201-7rd4j-lutees29t8ts5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F19999195039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
