INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42655339054', 'Mingau de Arroz e Aveia Vitalon - Sachê 600g', 'Os Cereais Infantis Vitalon foram criados para tornar o momento das refeições mais gostoso, nutritivo e especial. Enriquecidos com vitaminas e minerais, têm textura leve e são ideais para crianças em fase de crescimento. Com sabores que remetem ao carinho da infância — como banana, chocolate, mel e o clássico tradicional —, os produtos são fáceis de preparar, agradam o paladar dos pequenos e dão tranquilidade para os pais. Disponíveis em embalagens de 180g, 600g e 1kg, os cereais infantis Vitalon unem praticidade e nutrição no dia a dia da sua família. Os Cereais Infantis Vitalon foram pensados para oferecer uma refeição equilibrada, saborosa e com aquele toque afetivo que remete à infância. São enriquecidos com vitaminas e minerais, com textura suave e fácil preparo — ideais para acompanhar o desenvolvimento saudável das crianças. Cada sabor traz uma inspiração especial para tornar a alimentação mais divertida e gostosa. Destaques do Produto: Formulados especialmente para o público infantil Textura leve e fácil digestão Enriquecidos com vitaminas e minerais Validade de 16 meses Mix de cerea:is de arroz e aveia com sabor suave e agradável ao paladar, adicionado de viitaminas e minerais, com baixo teor de açúcar. Indicado para crianças a partir de 6 meses de idade, com registro no Ministério da Saúde.', 13.99, 5.6, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra2i-mb8gspco2cf60e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F534023108%2F42655339054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
