INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42769273667', 'Colágeno Protein 440G Enjoy Sabor Chocolate', 'O Collagen Protein Enjoy sabor Chocolate é a forma deliciosa de consumir proteína e cuidar do seu corpo. Com 15g de proteína por dose, ele é feito com colágeno PPure, garantindo absorção rápida e benefícios para articulações e pele. Sem adição de açúcares, livre de glúten e lactose, é uma opção saudável e saborosa para quem busca um suplemento nutritivo e de fácil digestão. Ideal para qualquer momento do seu dia, seja puro, no preparo de shakes ou receitas fitness. Sabor chocolate: com 15g de proteína por dose. Nos sabores: Neutro, Limão Siciliano e Chocolate. Com colágeno PPure. Extremamente saborosos. Opção de aporte proteico livre de leite. Proteína de fácil absorção. Benefícios para articulações e saúde em geral. Sem glúten e lactose Ideal para quem faz esportes ou quer aumentar a quantidade de proteína ingerida. Ideal para usar em receitas, smoothies, iogurtes, com água ou com a sua bebida de preferência.', 207.57, 126.7, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/sg-11134201-824iz-meqa3bsei0au67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F42769273667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
