INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599542857', 'Kit Conector 8 Pares MC4 Staubli Macho + Fêmea - 320016', 'Diferenciais: - São conectores de corrente contínua com capacidade máximo de 1500V de tensão. - Com proteção UV e características de suportar as intempéries. - O conector para corrente contínua tem utilização exclusiva para sistemas fotovoltaicos. - Conta com facilidade na conexão entre painéis e os inversores. - Ótima resistência ao tempo (proteção UV), umidade e intempéries. - Com travamento automático. - Facilidade na montagem e acoplamento aos cabos. - A caixa de junção do painel permanece selada, prevenindo conexões precárias e protegendo contra a exposição ao tempo.', 183.62, 183.62, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdym-m1krxu611z60ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F20599542857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397786697', 'Lona 4X4 Cobertura Cinza Preta Impermeável 300 Micras Grossa 190g/m2 TNT', 'Lona Multiuso Prata/Preto 300 Micras , 190G/M2 TAMANHO: 4MX4M , PESO:3040 GRAMAS A Lona Multiuso da TNT é a solução perfeita para quem precisa de versatilidade e resistência em diversas situações. Seja para acampar, cobrir espaços, proteger veículos, telhados, barracas, tendas, objetos volumosos, canteiros de obras ou até mesmo para revestir pisos durante pintura ou reformas, esta lona oferece ampla proteção e durabilidade. Vantagens: *Uso versátil: Ideal para diferentes aplicações. *Ilhós a cada metro: Facilita a fixação segura. *Impermeável: Protege contra água e umidade. *Proteção UV: Bloqueia a luz solar, embora não isole 100% o calor e a umidade. *Flexível: Facilmente adaptável a várias superfícies. *Resistente ao mofo: Imune à ação de bactérias e fungos. *Durabilidade prolongada: Material robusto e resistente. Material: *As lonas de 300 micras / 190G TNT são fabricadas com: *Polietileno de Alta Densidade: Proporciona maior resistência. *Polietileno de Baixa Densidade Laminado: Garante a impermeabilidade. Observações Importantes: *Evite instalar totalmente na horizontal. *Recomenda-se a instalação inclinada ou com um ângulo de 45º. *Sempre utilize cabos de sustentação durante a instalação. *A lona deve ser flexível para evitar acúmulo de água ou pressão do vento. *Certifique-se de que haja uma inclinação para drenagem de água, evitando peso excessivo sobre a lona. *Armazene em local sombreado, longe de fontes de calor. *Não utilize solventes. *A garantia não cobre defeitos causados por fenômenos naturais. O kit de instalação não está incluído. Imagens meramente ilustrativas.', 299.85, 179.9, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-81zul-mkvdo535hr0gae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308179417%2F21397786697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
