INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599706388', '1~6 DECORAÇÃO DE BALÃO COLORIDO 30CM-6132-22 FESTA JUNINA 2025 (EX) (CHOCO)', '🎈 PARA DEIXAR SEU ARRAIÁ DE 2025 AINDA MAIS ALEGRE E COLORIDO! OLHA SÓ ESSA DECORAÇÃO DE BALÃO: 1 DECORAÇÃO DE BALÃO COLORIDO 30CM DE COMPRIMENTO - 6132-22 FESTA JUNINA 2025 (EIXO FIRME) ✨ DÊ UM TOQUE DIVERTIDO E TRADICIONAL À DECORAÇÃO DA SUA FESTA JUNINA COM ESSE BALÃO DE PAPEL COLORIDO! COM 30CM DE COMPRIMENTO E EIXO FIRME, É PERFEITO PARA PENDURAR E CRIAR UM VISUAL FESTIVO E ACONCHEGANTE. 📏 DIMENSÕES: 30 CM DE COMPRIMENTO 🎨 MODELO: 6132-22 (VERIFICAR DISPONIBILIDADE DE COMBINAÇÕES DE CORES) 🎈 TEMA: FESTA JUNINA ✔️ IDEAL PARA: ✔️ DECORAR BARRACAS, SALÕES E ÁREAS EXTERNAS DA FESTA. ✔️ ADICIONAR UM ELEMENTO DECORATIVO TRADICIONAL E COLORIDO. ✔️ COMPLEMENTAR A DECORAÇÃO JUNINA COM AS CORES E FORMAS TÍPICAS. 🇧🇷 PREPARE-SE PARA UM ARRAIÁ INESQUECÍVEL EM 2025 COM DETALHES QUE FAZEM A DIFERENÇA! ESSE BALÃO DE PAPEL VAI TRAZER MAIS COR E ALEGRIA PARA SUA FESTA. ⚠️ OBSERVAÇÃO: AS COMBINAÇÕES DE CORES PODEM VARIAR. VERIFICAR A DISPONIBILIDADE DO MODELO 6132-22. 🚫 NÃO PERSONALIZAMOS ESTE PRODUTO. 🛒 ADICIONE UM TOQUE DE COR E TRADIÇÃO À SUA FESTA JUNINA! GARANTA JÁ SEU BALÃO DECORATIVO! IMPORTANTE: VERIFIQUE OS PRAZOS DE ENTREGA E O VALOR DO FRETE PARA SUA REGIÃO DURANTE A SIMULAÇÃO DA COMPRA.', 13.85, 13.85, NULL, 'Stationery > Gift & Wrapping > Others', 'https://cf.shopee.com.br/file/br-11134201-820lo-mqxfdnkk1bet26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F21599706388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799495386', 'Ferro De Passar A Vapor Cadence Iro210 Laranja - 220v', 'O Ferro de Passar a Vapor Cadence Iro210 Laranja é a escolha ideal para quem busca praticidade e eficiência na hora de passar roupas. Com 1200 w de potência, o Iro210 garante um desempenho rápido e eficiente, removendo amassados com facilidade. O sistema de vaporização, facilita o processo de passar roupas, deixando suas roupas lisas e sem vincos. O design moderno e a cor vibrante trazem um toque de alegria para sua lavanderia. Diferenciais: - Vapor: Possui função a vapor, que ajuda a remover rugas mais facilmente e a desinfetar tecidos; - Design Ergonômico: Projetado para facilitar o manuseio, tornando o ato de passar roupas mais confortável; - Base Antiaderente: Possui uma base que desliza suavemente sobre os tecidos, evitando grudar e queimaduras; - Reservatório de Água: Capacidade adequada para uso prolongado sem necessidade de reabastecimento frequente; -Controle de Temperatura: Permite ajustar a temperatura de acordo com o tipo de tecido, garantindo um melhor cuidado com as roupas. - Com 17 saídas de vapor,o Ferro de Passar IRO 210 Cadence faz o trabalho pesado contra rugas e vincos, além de combater odores leves, deixando tudo com cheirinho de novo.Com o novo tanque de 160 ml, tem 3x mais capacidadede armazenamento que o modelo anterior; - Tanque de Água de 160ml, 3x maior que o modelo anterior; - Base Antiaderente, Faz o ferro deslizar com total facilidade; - Ajuste de Temperatura, Para todos os tipos de tecido; - Recurso Salva-Botões, reserva detalhes e tecidos delicados; - Aquecimento Rápido; não precisa esperar; - 2 em 1 Ferro a seco e Ferro a Vapor; - Para aumentar a eficiência ao passar tecidos densos, como linho ou algodão, utilize a função de vapor regulável; - Tensão: 220V; Potência: 1200W; Consumo: 1,2 kWh (220V); Dimensões: 110x250x127mm; Peso 0,600Kg.', 120.41, 120.41, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-m1d5nb1fkd2001', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F21799495386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
