INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55750053054', 'Lovito Shorts Bermuda Jeans Feminino SHB84BRL113', '✅Destaques -❤️Botão frontal com botão frontal -❤️Macio e confortável -❤️Zíper frontal frontal -❤️Bolsos Com Bolsos ✅Descrição Padrão de padrão: liso Estilo do estilo: Casual Tamanho da peça Plus: Não Material da tela: algodão Composição: 98% Algodao 2% Elastano Tipo de Encaixe Regular Folha pura: Não Estica: Estica leve Região de Origem: Brasil ✅O pacote inclui 1x Shorts ✅Introdução DO LOVITO Lovito é uma marca emergente que acredita no poder da menina, comprometida em fornecer escolhas de roupas da moda e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertando e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é autoconfiança. ✅NOTAS DE COMPRA Compare suas medidas com nossa tabela disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, entre em contato conosco e responderemos o mais rápido possível.😊', 92.9, 45.9, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgc9z2ronj0g26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1632995122%2F55750053054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256239886', 'Vaso para Planta Mini Facetado com Pé Luxo N4 21x17', '🪴 VASO MINI FACETADO PP COM PÉ – 21x17 – MODERNO E ELEGANTE ENVIO IMEDIATO !!! O Vaso Mini Facetado PP com Pé é a escolha ideal para quem quer decorar ambientes pequenos com muito estilo. Seu design facetado moderno traz um toque sofisticado, enquanto o pé elevado valoriza ainda mais a planta, criando leveza e destaque na decoração. Compacto, versátil e elegante, ele combina perfeitamente com salas, cozinhas, varandas, escritórios e cantinhos decorativos. ✨ DIFERENCIAIS DO PRODUTO ✔ Design facetado moderno e decorativo ✔ Possui pé para dar mais destaque à planta ✔ Produzido em polietileno resistente ✔ Leve, durável e fácil de transportar ✔ Fácil de lavar e manter ✔ Ideal para ambientes internos 📏 MEDIDAS Boca: 21 cm Altura: 17 cm 🪴 INDICADO PARA Pequenos arranjos, suculentas, folhagens delicadas e plantas ornamentais naturais ou artificiais. 🏠 PERFEITO PARA Sala de estar, cozinha, varanda, escritório, aparadores, nichos e mesas decorativas. 📦 Produto à pronta entrega 🚚 Envio rápido 🧾 Nota fiscal 📦 Embalado com cuidado para chegar perfeito até você 👉 Garanta o seu agora e transforme pequenos espaços com mais charme e sofisticação!', 29.99, 16.9, NULL, 'Home & Living > Gardening > Pots & Planters', 'https://cf.shopee.com.br/file/br-11134207-820l5-mlhqj68j9kp106', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F608615567%2F58256239886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994454731', 'Câmera Ré Tartaruga Fisheye Dianteira Traseira Automotivo', 'Há 50 anos atuando no mercado automotivo oferecendo qualidade, inovação e garantia da satisfação total dos nossos clientes. - Produtos novos e lacrados a pronta entrega; - Produtos originais e de qualidade com garantia de fábrica; - Atendimento personalizado. _______________________________________________________________________ CÂMERA DE ESTACIONAMENTO FISHEYES CVBS/AHD 1080 – H-TECH A H-tech apresenta a câmera de ré CR-525, com função dianteira e traseira, CVBS/AHD 1080P, função com linhas e sem linhas, 160 graus, resistente a água (lp68), 21 MM, DC cabos, DC 12V, visão noturna CR e muito mais! INFORMAÇÕES TÉCNICAS: - Câmera de Ré - Resolução AHD 108 - Função dianteira e traseira - Visão noturna CR - Ângulo de visão de 160° - Opção com ou sem linhas guia - Lente Fisheye - Encaixe 2x1 tipo “tartaruga” - Resistente à água (IP68) - Tamanho: 18.5mm - Alimentação: 12V DC (via cabos) CONTEÚDO DA EMBALAGEM: - 01 Câmera de Ré CR-525 - Acessórios para instalação - Broca - Manual ATENÇÃO: - Garantia de 12 meses. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. - Imagens meramente ilustrativas.', 74.25, 74.25, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/sg-11134201-81zti-mievr7y7dix340', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432778585%2F22994454731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
