INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598944532', 'Corrente prata 925 colar Singapura 40cm - Prata 925', 'A corrente de prata 925 Singapura é um cordão elegante e sofisticado, confeccionado em prata de lei 925, que possui 92,5% de prata pura em sua composição. O modelo Singapura apresenta uma malha delicada e suave, que se assemelha a pequenos diamantes interligados, formando um padrão elegante e discreto. A corrente feminina possui um comprimento de 40cm, o que a torna perfeita para ser usada próxima ao pescoço, em composições com pingentes ou sozinha, como um colar minimalista. Com uma largura de 1,5mm, a corrente é fina e delicada, proporcionando um visual elegante e discreto. Por ser confeccionada em prata de lei 925, a corrente possui alta durabilidade e resistência, além de não escurecer ou oxidar facilmente. A corrente de prata 925 Singapura é uma escolha clássica e atemporal, perfeita para quem busca sofisticação e elegância em um acessório de alta qualidade. Além da corrente de prata 925 Singapura, temos outros modelos de correntes de prata disponíveis em nosso catálogo. Trabalhamos com uma grande variedade de opções, incluindo correntes venezianas, rabo de rato, laminadas, trançadas, pipoca, entre outras. As correntes venezianas, por exemplo, são conhecidas por sua textura e formato em "V", proporcionando um visual elegante e sofisticado. Já as correntes rabo de rato são mais grossas e resistentes, ideais para quem busca um acessório mais robusto e marcante. As correntes laminadas possuem uma camada de metal precioso, geralmente ouro ou prata, sobre uma base de metal menos nobre, conferindo um brilho intenso e durabilidade. Já as correntes trançadas são confeccionadas a partir da entrelaçamento de várias correntes finas, formando uma trama resistente e sofisticada. As correntes pipoca, por sua vez, são caracterizadas por seus elos arredondados e irregulares, conferindo um visual mais despojado e moderno. Esses são apenas alguns exemplos das opções que oferecemos em nosso catálogo, temos diversas outras opções de modelos, larguras, comprimentos e acabamentos para atender às necessidades e preferências dos nossos clientes. Descrição do produto: Material: Prata 925 Comprimento :40cm Modelo: Singapura', 90.79, 55.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvt82hha37ha4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F19598944532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
