INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199595480', 'Bandeja Plástica 250ml Pintura Multiuso Para Pad Rolo Pincel Reparos Manutenção Acabamentos', 'Bandeja Para Pintura Plástico 250ml Atlas A Bandeja Para Pintura Atlas é a solução ideal para quem busca praticidade e eficiência na aplicação de tintas. Seu design leve facilita o manuseio, proporcionando mais conforto durante a aplicação da tinta. Ideal para pequenos reparos ou projetos de pintura em casa, ela possui capacidade de 250ml. Fabricada em plástico de alta resistência, é leve, durável e fácil de manusear. Seu design compacto permite um manuseio confortável, facilitando a transferência de tinta para pincéis ou rolos. Características: > Capacidade 250ml; > Produto leve, resistente, de fácil manuseio e facilitará o processo de pintura; > O produto apresenta uma construção robusta que dá maior segurança ao trabalho; > Ideal para trabalhos com pads e rolos sem desperdiçar tinta e perder agilidade no trabalho. Especificações Técnicas: > Material: plástico; > Dimensões do produto (C x L x A): 30cm x 15cm x 5cm. - Marca: Atlas - Garantia: 12 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 21.09, 15.92, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rbm7-m5ykzrtcpy2y37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F21199595480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
