INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23099031042', 'Colhedor De Frutas Pequenas Tramontina 15 Pol Sem Cabo P/ Maçãs Laranjas E Árvores Frutíferas', 'Colhedor De Frutas Pequeno Em Aço Sem Cabo 15Cm Tramontina Facilite a colheita de frutas no pomar ou no quintal com o Colhedor de Frutas Pequeno Tramontina em Aço Sem Cabo. Ideal para apanhar laranjas, maçãs, goiabas, bergamotas e diversas outras frutas com praticidade e segurança, ele é a ferramenta perfeita para quem busca eficiência e conforto no dia a dia. Produzido em aço carbono especial de alta qualidade, o colhedor garante resistência, durabilidade e excelente desempenho. Seu corpo leve reduz o esforço físico durante o uso, tornando a tarefa muito mais rápida, simples e prazerosa Com pintura eletrostática a pó, o colhedor recebe uma camada protetora que evita oxidação e proporciona acabamento visual superior, além de ser fabricado com tinta livre de metais pesados, reduzindo o impacto ambiental. Compacto e versátil, é a escolha ideal tanto para uso doméstico quanto profissional na colheita de frutas frescas diretamente do pé. Características: > Produzido em aço carbono especial de alta qualidade, com longa vida útil; > Leve e ergonômico, reduzindo o esforço físico durante o uso; > Pintura eletrostática a pó, com proteção contra oxidação e excelente acabamento; > Ideal para colher laranjas, maçãs, goiabas, bergamotas e outras frutas diretamente do pé. Especificações: > Modelo: Colhedor de Frutas Pequeno Sem Cabo; > Material: Aço carbono especial; > Acabamento: Pintura eletrostática a pó; > Cabo: Não incluso; > Aplicação: Colheita de frutas em pomares e quintais. - Marca: Tramontina - Garantia: 12 meses contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 49.18, 37.38, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259i-mfx1gwy9rimi99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F23099031042', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205015933', 'Cílios Postiços ImPRESS Press-on Falsies Natural - Kiss New York', 'imPRESS Press-on Falsies é a primeira linha de cílios postiços autocolantes do mercado. Sem cola, sem tempo de secagem e sem danos aos cílios naturais. Com Tecnologia ASP (Adesivo Sensível à Pressão), a mesma das unhas imPRESS, os clusters de cílios possuem adesivos autocolantes que aderem instantaneamente ao cílios naturais. Com apenas 1 passo e em 10 segundos, garanta 24 horas de duração e aparência 100% natural. Nunca mais tenha medo de aplicar cílios postiços! O kit contém 20 clusters que garantem de 2 a 3 aplicações e um aplicador com um design único antiaderente e com uma curvatura que garante o ângulo perfeito para a aplicação dos seus imPRESS Press-on Falsies', 90.9, 90.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mkk14ubq2gw1e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58205015933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
