INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40722780471', 'Chinelo Rider de Dedo RW Plus Confortável Original 12425 Preto e Vermelho', '🩴 Chinelo Rider RW Plus 12425 – Conforto e Estilo para o Dia a Dia 🩴 O Chinelo Rider RW Plus Masculino é a escolha ideal para quem busca leveza, design moderno e praticidade. Desenvolvido para garantir bem-estar em cada passo, ele possui palmilha macia, tiras confortáveis e solado resistente, oferecendo estabilidade em diferentes superfícies. Perfeito para uso diário, praia, piscina ou momentos de lazer, une conforto e durabilidade com a autenticidade Rider. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/40872672363/ ✨ Benefícios Exclusivos: 🩴 Palmilha macia que proporciona conforto prolongado 👣 Formato anatômico que se adapta ao pé 💪 Tiras resistentes e flexíveis ⚡ Solado antiderrapante para maior segurança 🌊 Versátil: ideal para o dia a dia, praia e piscina 📌 Ficha Técnica: Marca: Rider Modelo: RW Plus 12425 Tipo: Chinelo Masculino de Dedo Material: Sintético leve e durável Palmilha: Macia e anatômica Solado: Emborrachado antiderrapante Estilo: Casual / Praia / Piscina Numeração: 37 ao 44 📏 Tabela de Medidas (cm): 37 – 25,0 38 – 25,5 39 – 26,0 40 – 27,0 41 – 27,5 42 – 28,0 43 – 29,0 44 – 29,5 🧼 Dicas de Limpeza: Lave com água corrente e sabão neutro. Não utilize produtos abrasivos ou solventes. Deixe secar naturalmente à sombra. 💖 Diferenciais: O Rider RW Plus 12425 combina estilo esportivo, conforto anatômico e alta durabilidade, garantindo praticidade e versatilidade em qualquer ocasião.', 119.9, 104.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfdz1lol416s5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F32453629