INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096993831', 'Kit Tereré Copo Bomba Garrafa Termica 4l Inox - Seu Nome', 'Acompanha: 1 - Copo Tereré Inox 1 - Bomba Tereré Inox 1 - Garrafa Térmica Tereré Inox 4 LITROS *Limpador de Bomba* Características do Produtos: - Capacidade para 4 Litros. - Adequado para líquidos frios e quentes. - Mantem a temperatura por mais tempo. - Bombeamento por alavanca. - Base giratória 360°. - Alça móvel para transporte. - Parede dupla em aço inoxidável. - Tampa removível e boca larga para facilitar a limpeza. - Bloqueio de segurança para crianças.', 259.9, 246.91, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/br-11134207-7r98q-lmf1f9y7ke7qb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23096993831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49457089284', 'Jogo de Chave Combinada 6-22 MM Cromo Vanádio 12 Peças STELS', 'O Jogo de Chave Combinada STELS reúne 12 peças essenciais para trabalhos mecânicos e manutenção em geral, cobrindo a faixa de 6 a 22 mm. Confeccionado em cromo vanádio, oferece resistência e durabilidade para uso frequente, com acabamento que facilita a limpeza e ajuda a proteger contra corrosão. Compacto e prático, o conjunto é indicado para profissionais e entusiastas que precisam de versatilidade em um único kit. As chaves combinadas permitem operações com bocas e catracas em diferentes aplicações, garantindo mais organização e rapidez no serviço. Características: Modelo: 1540555 Referência: 1540555 Tipo: Jogo de chave combinada Tamanhos: 6-22 mm Material: Cromo Vanádio Peças: 12 Marca: STELS Benefícios: Construção em cromo vanádio para maior resistência e durabilidade Conjunto de 12 peças cobre uma ampla faixa de medidas (6 a 22 mm) Acabamento cromado facilita a limpeza e ajuda a proteger contra corrosão Permite organização e praticidade no transporte e armazenamento Versátil para uso profissional e doméstico Conteúdo da embalagem: 1 jogo com 12 chaves combinadas (6 a 22 mm)', 157.1, 111.98, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mlp19nyc9urp31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F49457089284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254041590', 'Pneu Pirelli Aro 15 Cinturato P1 (KS) 195/65R15 91H', '** PRODUTO NOVO ** GARANTIA DE FÁBRICA DE 5 ANOS ** EMISSÃO DE NF ** SOBRE O PNEU: O pneu Pirelli Cinturato P1 foi desenvolvido pela Pirelli para equipar carros pequenos e médios, oferecendo bom desempenho em estabilidade e aderência, sem abrir mão da alta durabilidade e resistência dos pneus Pirelli. Sua banda de rodagem tem amplas nervuras, que garantem contato com o solo constante, dando apoio nas curvas e ótimas frenagens. Esse pneu pode ser aplicado nos seguintes carros; Audi:80, A4 Bmw: Serie 3 Chevrolet: Cobalt, Omega, Onix, Sonic, Spin, Suprema, Vectra, Zafira Citroen: C4, C5 Fiat: Linea, Stilo, Strada Honda: Accord Hyundai: Hb20x Kia: Cerato Mercedes: Classe B, Classe C Nissan: Maxima, Versa Peugeot: 307, 406, 605 Renault: Espace, Laguna, Megane, Safrane Subaru: Impreza Toyota: Corolla, Prius Vw: Beetle, Bora, Golf, Parati, Passat Garantia de fábrica: 5 anos', 723.0, 650.7, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mjy49vyc4xs3ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081431407%2F58254041590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49556671788', 'Trena Curta 7,5m 25mm Gancho Magnético 1 Peça MTX', 'Trena curta MTX ideal para medições rápidas e práticas em ambientes residenciais e profissionais. Mede 7,5 m com fita metálica de 25 mm, carcaça emborrachada para maior proteção e fita com gancho magnético que facilita a fixação em superfícies metálicas durante a medição. Compacta e resistente, oferece boa visibilidade da escala e manuseio confortável graças ao revestimento emborrachado. Produto vendido em unidade única, indicado para quem precisa de uma trena portátil e funcional para obras, marcenaria e tarefas gerais de medição. Características: Modelo: 3100655 Referência: 3100655 Comprimento: 7,5 m Largura da fita: 25 mm Acabamento: emborrachado Fita: metálica com gancho magnético Unidade: 1 PC Marca: MTX Benefícios: Medições rápidas e precisas com fita metálica de 25 mm. Fixação prática em superfícies metálicas pelo gancho magnético. Maior durabilidade e proteção contra impactos com carcaça emborrachada. Portabilidade e armazenamento facilitados por ser uma trena curta. Ideal para uso em obras, marcenaria e tarefas domésticas. Conteúdo da embalagem: 1 x Trena curta 7,5 m, 25 mm, emborrachada com fita metálica e gancho magnético (MTX)', 44.12, 34.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262q-mlc56zm8v5zj92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F49556671788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22196921693', 'Kit Blindagem Das Unhas Fibra Nylon + Nivelador Fosco Blant', 'O Kit Blindagem Das Unhas Fibra Nylon + Nivelador Fosco Blant é um conjunto de produtos projetados para fortalecer e proteger as unhas, proporcionando um acabamento fosco elegante. O kit inclui dois itens essenciais: a fibra de nylon e o nivelador fosco. A fibra de nylon fortalece e promove resistência através de uma trama de nylon que protege a unha de qualquer agressão e choque, evitando quebras e descamações. Já o nivelador Fosco, proporciona uma superfície lisa nas unhas, cobrindo as fibras ásperas de nylon preparando a unha para receber a esmaltação. Benefícios: - Unhas mais resistentes; - Evita descamação; - Diminui a quebra; - Acabamento fosco. Modo de usar: Passo 1, Aplique uma camada sobre toda a superfície da unha limpa e seca, deixe secar por alguns minutos. Passo 2, Aplique uma única camada e deixe secar completamente. Se a superfície permanecer áspera, aplique uma segunda camada. Sobre a marca: A BLANT, indústria 100% brasileira atua no mercado nacional desde 2010. A marca preocupa com suas mãos, pés e unhas em todos os sentidos, por isso inova sempre para oferecer produtos para unhas, com fórmulas realmente eficazes de proteção, tratamento, nutrição, regeneração e fácil aplicação, que permite a utilização em casa como também pelas profissionais.', 51.29, 51.29, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-820o0-mo09ajz6jvgh00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22196921693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
