INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997925998', 'Kit Wella Professionals Invigo Blonde Recharge - Shampoo Desamarelador 250ml (2 Unidades)', 'Kit Wella Professionals Invigo Blonde Recharge - Shampoo Desamarelador 250ml (2 Unidades) Shampoo desamarelador para cabelos loiros coloridos, naturais ou com mechas. Wella Professionals Invigo Blonde Recharge Shampoo elimina os tons amarelados e acobreados indesejados com seus pigmentos violeta. Assim, além de limpar, mantém a cor bonita e com muito brilho. Wella Professionals Invigo Blonde Recharge Shampoo tem uma fragrância floral deliciosa, com lírio do vale, rosas, sândalo e baunilha como acordes olfativos. Além disso, proporciona maciez aos fios. Seu cabelo fica com a cor linda, brilhante, sedoso e perfumado. Como Usar Conselho de Aplicação Aplique o shampoo sobre o cabelo úmido. Massageie gentilmente. Em seguida, enxágue.', 383.1, 383.1, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdvz-m14lp5qnzksq4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F20997925998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
