INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12701834828', 'Gelo Pan 100g - Gel Relaxante Muscular P/ Cães, Gatos, Equinos e Bovinos.', 'INDICAÇÃO DO PRODUTO Gel de efeito relaxante e refrescante. Indicado nas fadigas de músculos, tendões, articulações e ligamentos, em traumas, contusões, luxações, artrites, reumatismos e dores musculares. MODO DE USAR Gelo Pan pode ser prontamente utilizado. Aplicar no local afetado massageando a favor do pelo. Também pode ser diluído em água morna: 50 g do produto para 1 litro de água (5 g/100 mL). Massagear a região afetada. EFEITOS COLATERAIS Não há registro de efeitos colaterais. APRESENTAÇÃO Bisnagas plástica contendo 100 g.', 77.35, 49.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/7435f9c8412b14e7bb4da807562a0319', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F12701834828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
