INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593544669', 'Kit 2 Protetor Solar Corporal Isdin HydroLotion FPS 50 com 200ml', 'Protetor Solar Corporal ISDIN HydroLotion FPS 50+ 200ml O Fotoprotector ISDIN Hydrolotion é um protetor solar corporal bifásico que oxigena a pele e protege contra os danos causados pela exposição solar com FPS 63. É indicado para todos os tipos de pele, inclusive peles sensíveis. Protege e revitaliza a pele do stress oxidativo causado pelo sol, diminuindo a formação de radicais livres. - Protetor solar corporal bifásico com FPS 63 e dupla ação: protege e revitaliza a pele. - O primeiro fotoprotetor bifásico que oxigena a sua pele. - Hidratante. Absorção imediata. Uma vez aplicado e espalhado, seca em segundos sem deixar nenhum resíduo. - Ação antioxidante: Minimiza os danos mais profundos na pele causados pelos raios infravermelhos. - Sem álcool. Hipoalergênico. Resistente à água. Modo de usar: Agite o produto por 5 segundos, assegurando que ele se misturou corretamente. Aplicar generosamente sobre a pele seca, meia hora antes da exposição solar. É necessária a reaplicação do produto para manter a sua efetividade a cada 2 horas e depois de transpirar, nadar, banhar-se ou secar-se com uma toalha e durante a exposição ao sol. Se a quantidade aplicada não for adequada, o nível de proteção será significativamente reduzido.', 315.78, 315.78, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-823rs-mooibl0r474177', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23593544669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
