INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894949060', 'Kit Camisetas Tommy Hilfiger Original | Masculina Essential Preta/Branca/Azul Royal 3UN', 'Kit Camisetas Tommy Hilfiger Masculina Essential Preta/Branca/Azul Royal 3UN _x000D_ O Kit Camisetas Tommy Hilfiger Masculina Essential Preta/Branca/Azul Royal oferece variedade e versatilidade para o dia a dia. Composto por três camisetas em cores clássicas — preta, branca e azul royal — esse kit é ideal para diferentes ocasiões e combinações. As camisetas possuem modelagem regular e são confeccionadas em 100% algodão, proporcionando conforto e durabilidade. O detalhe da bandeira da marca bordada no lado esquerdo do peito adiciona um toque de elegância. Com gola redonda canelada e mangas curtas, essas camisetas são perfeitas para composições básicas ou mais elaboradas. Tommy Hilfiger é sinônimo de estilo, qualidade e sofisticação._x000D_ Ficha Técnica do Produto_x000D_ _x000D_ Composição: 100% Algodão_x000D_ Cores: Preta, Branca e Azul Royal_x000D_ Modelagem: Regular_x000D_ Detalhes: Bandeira da marca bordada no lado esquerdo do peito, gola redonda com acabamento canelado_x000D_ Kit: 3 camisetas_x000D_ _x000D_ O Kit Camisetas Tommy Hilfiger Masculina Essential Preta/Branca/Azul Royal 3UN é a escolha certa para quem busca praticidade, elegância e conforto.', 599.97, 395.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-820lb-mneemwajjv9k86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760398124%2F22894949060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41301434419', 'Garota à Beira-Mar - Grupo Editorial JBC', 'O lado marginal da sociedade que o mundo ignora é visitado de forma visceral por Inio Asano, o premiado autor de Boa Noite Punpun, Dead Dead Demons DeDeDeDe Destruction e Decadência. Em Garota à Beira-mar, como preencher o vazio que surge na alma enquanto não se encontra o caminho que o destino apontará para seguir pela vida é o principal tema abordado por Asano. Sexo, violência, drogas e sonhos surgem como possíveis respostas. Viver, por si só, é dolorido e, ao mesmo tempo, toda decisão tem suas consequências.', 72.22, 72.22, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rfg4-m9yigupm1t3j69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F41301434419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
