INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20775541541', 'KIT 06 ICE 51 MACA VERDE 275ML', 'A Cachaça 51, tornou-se a base do soft drink mais saboroso do Brasil. A 51 Ice, vem pronta para beber e é perfeita para ser consumida entre amigos ou nas baladas. Presente nas festas mais badaladas, a 51 Ice Maça verde é uma bebida mista leve e saborosa, pronta para qualquer momento. Combinando a cachaça 51 clássica com o gostinho exclusivo da fruta, essa versão oferece diversão e refrescância de forma prática. ESPECIFICAÇÕES DO PRODUTO Teor Alcoólico: 5,5% Litragem: 275ml Sugestão de consumo: Ela é apreciada tanto pura, pelos verdadeiros apaixonados pela bebida, quanto como base de drinks clássicos, como a famosa caipirinha.', 39.9, 39.9, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-7qvfz-lihpb4hksurl48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F20775541541', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
