INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17471901074', 'VINHO CIRCUS SAUVIGNON BLANC 2019 750ML', 'Os aromas são os mais típicos, mas sem perder a excelência. Maracujá, pêra, limão e abacaxi crescem em taça, dando espaço para algumas notas florais e nuances que remetem a chás de frutas, bem tropical. Em boca, é levemente encorpado, com notas de amêndoa e frutas doces. O final é sutil e amanteigado, deixando sabores mais verdes ao longo do palato. Muito fresco, fácil de beber e ótimo para agradar a todos, este é um daqueles vinhos para guardar na adega e ter como companheiro em todos os momentos!', 79.08, 69.59, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/bc7f52f72bcc7c4d284d7c00d5ac1128', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F17471901074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22099148068', 'Ukulele Soprano Bravo Music Buk121 21 Polegadas Nylon', 'Ukulele Bravo BUK121 – Soprano 21” com Capa de Fábrica - Leve, compacto e perfeito para iniciar na música! Traga música e alegria para o seu dia com o Ukulele Bravo BUK121! Ideal para quem está começando ou deseja um instrumento portátil com excelente custo-benefício, esse ukulele soprano 21” oferece um som brilhante, suave e encantador — perfeito para tocar pop, gospel, MPB, reggae, lo-fi e muito mais! Construído em Basswood (Tília), ele é leve, resistente e confortável ao tocar, com acabamento fosco premium que garante um visual moderno e toque agradável. Além disso, por ser compacto, é ideal para crianças, jovens e adultos que desejam aprender e se divertir com um instrumento fácil de manusear. O modelo já acompanha capa/bag de fábrica, oferecendo mais praticidade para guardar, proteger e transportar o instrumento com segurança. Por que escolher o Ukulele Bravo BUK121? Timbre alegre e definido — som perfeito para iniciantes Tamanho Soprano 21” — fácil de transportar e tocar Acompanha capa/bag de fábrica — mais proteção e praticidade Corpo em Tília — material leve e resistente Acabamento fosco — moderno, bonito e confortável Ótimo para quem quer aprender rápido e com qualidade Especificações Técnicas Modelo: BUK121 Marca: Bravo Tipo: Acústico Tamanho: Soprano 21” Tampo: Basswood Plywood (Tília) Lateral e Fundo: Basswood Plywood (Tília) Tarraxas: Sim Acabamento: Satin (Fosco) Acompanha: Capa/Bag de fábrica Dimensões Peso: 500 g Comprimento do corpo: 23 cm Largura: 19 cm Altura: 5,6 cm Indicado para: iniciantes, estudantes, crianças e adultos que desejam aprender com praticidade. Comece a tocar hoje mesmo! Garanta já o seu Ukulele Bravo BUK121 com capa/bag de fábrica e descubra como aprender música pode ser fácil e divertido!', 189.9, 189.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-820lq-mq6jhma4sr29fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780674849%2F22099148068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
