INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994176690', 'Cooler para Notebook Acer Part Number DC28000JRF0', 'Cooler para Notebook Acer Part Number DC28000JRF0 | Interno ste é um Cooler bringIT compatível com o notebook Acer Part Number DC28000JRF0. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 4 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL149-AC-0008-1', 50.41, 45.36, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-82581-mq6yahpitn297b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22994176690', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
