INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497605921', 'Clorador Margarida Brustec para Limpeza de Piscina - 03.0002', 'O clorador Margarida é fabricado com polímeros de alto padrão de qualidade. Possui método de dosagem controlada através da abertura e fechamento das cavidades inferiores (para saber o quanto dosar é necessário consultar o fabricante do produto químico). Possibilita o tratamento da piscina mesmo quando não houver a manutenção periódica fornecendo assim mais comodidade e segurança na qualidade da água. É necessário apenas manter o acessório abastecido com as pastilhas de cloro e tem a capacidade máxima de 600g (3 pastilhas de 200g).', 41.12, 32.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8261b-mk4bkye631fp5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23497605921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
