INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899378283', 'Guarda-Roupa Casal Kappesberg 6 Portas 2 Gavetas Marrom Branco - M569BR', 'Transforme seu quarto com o Guarda Roupa de Casal M569 da Kappesberg, combinação perfeita entre sofisticação e modernidade. Conta com 6 portas, 2 gavetas, 6 prateleiras e 3 cabideiros metálicos, oferecendo grande espaço para armazenamento, mantendo suas roupas e objetos pessoais seguros, organizados e ao alcance das mãos. Sua estrutura em MDP de alta qualidade, juntamente com as corrediças metálicas, garantem durabilidade e resistência excepcionais ao móvel. Na sua belíssima combinação das cores Marrom Nogueira em sua estrutura e Branco nas portas, agregam elegância ao ambiente. Aproveite a qualidade dos móveis da Kappesberg! VERSÃO SEM ESPELHO Especificações: - Comprimento: 232 cm - Largura: 47 cm - Altura: 223 cm - Material: MDP - 6 Portas - 2 Gavetas com Corrediças Metálicas - 6 Prateleiras - 3 Cabideiros Metálicos - Puxadores em Madeira - Tipo de Porta: de Bater - Peso Suportado por Prateleira: 7 kg - Peso Suportado por Gaveta: 6 kg - Sistema de Montagem: Parafuso Philips - Cor: Nogueira/Branco - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 2654.85, 1519.9, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-lzrcbopvlf3e5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F19899378283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
