INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594087599', 'Ração Supra Leroy Cocktail Do Mar 1kg', 'A Ração Supra Leroy Cocktail do Mar 1kg é um alimento completo e balanceado, desenvolvido especialmente para gatos adultos. Sua fórmula contém 31% de proteína e 12% de extrato etéreo, proporcionando energia e vitalidade para o seu felino. Enriquecida com taurina, ômegas 3 e 6, e extrato de yucca, auxilia na saúde cardiovascular, pelagem brilhante e controle do odor fecal Diferenciais: 31% de proteína para músculos fortes. Ômegas 3 e 6 para pelagem saudável. Taurina para saúde ocular e cardíaca. Extrato de Yucca para redução do odor fecal. Vitaminas E, C e Selênio para ação antioxidante.', 36.12, 28.9, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-8261l-mkwrm567l1525e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F22594087599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698916619', 'Shorts Jeans Azul Feminino Adulto Básico Select', 'O Shorts Jeans Feminino Adulto Básico Select é a peça ideal para compor looks versáteis e modernos. Confeccionado em jeans de alta qualidade, oferece conforto e durabilidade no dia a dia. Possui fechamento em zíper e botão, passantes para cinto que permitem diferentes combinações, além de bolsos frontais e posteriores funcionais. A barra levemente desfiada adiciona um toque de estilo despojado, perfeito para produções casuais que valorizam praticidade e elegância.', 89.99, 89.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-82591-mr0o1lt4acxuf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23698916619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193734034', 'Kit Uniformidade e Frescor', 'Garanta uma pele uniforme, livre de manchas, super hidratada e extremamente perfumada com o kit Uniformidade e Frescor. O novo creme clareador Niacinamida Corporal 10% ajuda a uniformizar o tom da sua pele, além de mantê-la hidratada por muito tempo. Aliado ao Sérum Facial 25%, você garante uma pele livre de manchas, acne e hidratada. Aproveite e leve um super body splash para deixar sua pele perfumada por muito mais tempo. Niacinamida: O Creme Niacinamida Corporal 10% é o cuidado essencial para quem busca uma pele mais uniforme, hidratada e revitalizada. Com 10% de Niacinamida (Vitamina B3), ele melhora a elasticidade da pele e promove um clareamento gradual e uniforme, deixando o tom da pele mais homogêneo. Ativos : Alfa-Arbutin: Reduz manchas, inibindo a formação de melanina. Vitamina E: Um antioxidante que protege e combate os sinais de envelhecimento. Óleo de Rosa Mosqueta: Hidratação intensa, toque macio e melhora na textura da pele. Sérum Facial Niacinamida: Experimente a revolução em cuidados com a pele com o nosso Sérum Facial Clareador Niacinamida 25% Nossa fórmula avançada visa proporcionar à sua pele uma luminosidade excepcional e um tom mais uniforme. Imagine uma pele livre de manchas escuras, marcas indesejadas e descolorações. Agora, torne realidade com o Sérum Facial Clareador Niacinamida 25% - Rosa Selvagem. Ativos: Niacinamida 25%: Um poderoso aliado na luta contra manchas escuras e irregularidades na pele. A niacinamida ajuda a reduzir a produção de melanina, deixando sua pele com um tom mais uniforme e luminoso. Ácido Hialurônico: Este ingrediente age como um hidratante supremo, mantendo sua pele suave, flexível e com uma aparência jovem. Sua ação antioxidante também ajuda a proteger a pele dos danos causados pelos radicais livres. Alpha-Arbutin: Uma arma eficaz contra as manchas, o Alpha-Arbutin atua diretamente na inibição das enzimas que formam a melanina, ajudando a clarear a pele e reduzir as áreas hiperpigmentadas.', 230.0, 230.0, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6ph5d8o9gz4d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F773799036%2F23193734034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
