INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7093822630', 'Macacão de Bebê Amore Vira Pé Pink Com Zíper 100% Algodão', 'DESCRIÇÃO Seu bebê merece esse conforto! O Macacão Vira Pé com Ziper e protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido em Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Vira Pé • Ziper • Protetor de Zíper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade Ou em Centímetros. O tamanho em centímetros é entre a gola do macacão e o pezinho. RN - 48cm P - 51cm M - 56cm G - 61cm GG - 66cm ESPECIFICAÇÕES 1 Macacão com Ziper *Imagem Ilustrativa: A mercadoria é composto somente pelos produtos da descrição acima.', 34.9, 32.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg2ja9g6jke86e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F7093822630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3090266259', 'Móbile para Carrinho Animal Fun 13147 - Buba', 'DESCRIÇÃO DO PRODUTO Nos primeiros meses de vida o bebê consegue se comunicar apenas com olhares, choros e alguns movimentos dos membros. Os Móbiles são essenciais neste período para estimular o tato, visão e audição, através do movimento, das cores, formas e músicas. Pensando nisso, a Buba trouxe o Móbile para Carrinho Animal Fun, o móbile ideal para entreter o seu bebê. Macio e com cores vibrantes, pode ser usado em qualquer lugar, principalmente no carrinho de bebê, estimulando seu pequeno até mesmo na hora dos passeios. CARACTERÍSTICAS TÉCNICAS Conteúdo da Embalagem: 1 móbile com 3 brinquedos Dimensões Aproximadas do Produto: 33 x 36 cm Dimensões Aproximadas da Embalagem: 34 x 37,5 x 8cm (Altura x Largura x Comprimento/Profundidade) Material/Composição: Poliéster, Polipropileno, ABS, EVA e Poliestireno Idade Mínima Recomendada: A Partir de 3 meses de idade Marca: Buba Referência: 13147 Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 185.23, 163.49, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/bef20cb8434ec6dd446493ca3bee3d45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F3090266259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
