INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193697548', 'Protetor Térmico para Ptc 1/3 Hulter - 110V', 'Protetor Térmico PTC 1/3 Hulter - 110V O Protetor Térmico PTC 1/3 Hulter - 110V é um componente essencial para o bom funcionamento de refrigeradores, garantindo a partida correta do compressor e protegendo o sistema contra superaquecimentos. Sua atuação é fundamental para evitar danos causados por sobrecarga elétrica, promovendo mais segurança e estabilidade no funcionamento do equipamento. Projetado para aplicações em sistemas de refrigeração que utilizam motores de 1/3 HP, o protetor térmico PTC funciona de forma automática, ativando o compressor de maneira eficiente e desconectando-se após o ciclo de partida. Isso reduz o desgaste dos componentes internos e contribui para uma operação mais silenciosa e econômica. Com instalação prática e desempenho confiável, o Protetor Térmico PTC Hulter é uma escolha inteligente para quem busca manter a eficiência e prolongar a vida útil dos refrigeradores. Ideal para manutenções corretivas ou preventivas, é uma solução segura e duradoura para garantir o desempenho ideal do sistema de refrigeração.', 23.9, 23.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-mdbrvx43cc8p50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23193697548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
