INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398772803', 'Kit 04 Cadernos Universitário 10 Matérias 160 Folhas Flow - Jandaia CAPA:Skate/Alien/Boys/Olho', 'Kit De 4 Cadernos Universitário 10 Matéria 160 Folhas Masculino. Pedidos feitos até às 11:00 horas (seg à sex) são enviados no mesmo dia! - DESCRIÇÃO: • Formato: 20x27,5cm - ideal para mochilas e pastas. • Tamanho Padrão (A4) • Capa: Dura com laminação fosca - resistente e fácil de limpar. • Número de Folhas: 160- espaço para todas as suas anotações. • Matérias: 10 matérias. • Espiral preta - resistente e prática. • Diversas estampas Masculino: escolha a que mais combina com você! - Quantidade Do Kit: • 04 Cadernos Cada Um Com 160 Folhas - Qualidade Jandaia • Papel de alta gramatura: resistente e evita que a tinta marque na folha seguinte. • Arame resistente: garante que suas folhas fiquem firmes no lugar. • Acabamento impecável: um caderno que você vai ter orgulho de usar. • Aproveite a oferta por tempo limitado: Chega de cadernos sem graça! Com o Caderno Universitário 10 Matérias Masculino da Jandaia, você vai organizar seus estudos com muito mais estilo e praticidade. Quem busca um caderno bonito e funcional: as estampas Masculino e o acabamento de qualidade garantem um toque especial no seu dia a dia.', 80.0, 59.96, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7rdwo-mctens34fldsc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F22398772803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
