INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499257589', 'Pneu Moto Pirelli Aro 17 Diablo Rosso II 140/60R17 63H TL - Traseiro', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O pneu para moto Pirelli Diablo Rosso II é um modelo desenvolvido para equipar motos esportivas. É um pneu bom para quem busca pilotar de forma rápida e segura, com a garantia de a moto deitar nas curvas e ter rapidez para levantar nas saídas de curvas. Além disso, a área central do pneu garante excelente estabilidade em linha reta, mesmo em velocidades acima dos 200km/h, quando o pneu de alta qualidade faz muita diferença na pilotagem. As laterais, garantem ótima aderência em pista seca e também possuem ramificações para expulsar a água da área de contato em situação de pista molhada. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 859.08, 790.36, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-lvlvqlz5zzmu47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F20499257589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
