INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51408086773', 'Papel Branco Premium Offset 180g A4 - MASTERPRINT', 'PAPEL BRANCO PREMIUM 180g/m² A4 - MASTERPRINTPedidos feitos até às 11:00 horas (Seg à Sex) são enviados no mesmo dia!!! DESCRIÇÃO: • Variações Disponiveis: Offset/Casca de Ovo/Vergê/Linho • Tamanho: A4 (210mm X 297mm).• Contém: Pacotes c/ 50• Gramatura: 180g/m². Papel liso Offset Superfície lisa, ideal para impressão nítida e documentos formais. · Sem textura → impressão mais limpa · Melhor para:documentos,apresentações,certificados simples muito mais Textura tipo linho Textura suave tipo tecido, com acabamento mais refinado para materiais premium. · Textura lembra tecido de Linho · Muito usado para convites finos e menus Texta Vergê Textura vergê (linhas finas) → aparência elegante · Firme, tipo cartolina fina · Ideal para convites, certificados e papelaria fina Casca de Ovo Textura leve, granulada, parecida com a superfície de casca de ovo · Firme, tipo cartolina fina · Ideal para convites, certificados e papelaria fina Para que serve os papeis premium ? 180g/m² → papel grosso e resistente (não é sulfite comum) Liso → mais simples e profissional(Cartões de visita mais grossos,Tags,Lembrancinhas..) Texturizado → Visual mais sofisticado e elegante (Convites, certificados e materiais elegantes..)', 40.0, 16.96, NULL, 'Stationery > Notebooks & Papers > Art Paper & Boards', 'https://cf.shopee.com.br/file/sg-11134201-81zwr-mmxijvkxgjk123', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F51408086773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
