INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21459970762', 'Filtro Óleo Kia Sorento 2.5 2004 A 2009 Tecfil Psl327', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação SORENTO EX 2.5 140/170CV 4X4 AUT.DIESEL 2004 até 2009 SORENTO EX 2.5 16V 4X4 MEC. DIESEL 2006 até 2009 SORENTO LX 2.5 16V 140CV 4X4 AUT. DIESEL 2005 até 2006 SORENTO LX 2.5 16V 140CV 4X4 MEC. DIESEL 2005 até 2006 Conteúdo Da Embalagem 1 Filtro de Óleo Observação Motor 2.5 CRDI Tipo de Veículo para SUV''s e Caminhonetes Marca A Tecfil é sinônimo de qualidade e garantia da melhor experiência. A mais de 60 anos no mercado, o comprometimento em fazer o melhor para o cliente a garantiu o mais alto patamar de reconhecimento em qualidade e tecnologia. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o filtro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7891342000574 Código do Fabricante PSL327 Combustível Diesel Combustível Diesel >', 44.79, 44.79, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rblq-llx239o4p0a15b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21459970762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493516085', 'Barbie Caixa Registradora Unique - Fun Divirta-se', 'Barbie Caixa Registradora Unique - Fun Divirta-seA Caixa Registradora Unique Barbie é o brinquedo perfeito para proporcionar horas de diversão e aprendizado para os pequenos. Com detalhes encantadores e cores vibrantes, este brinquedo permite que as crianças mergulhem em um mundo de faz de conta, onde podem simular ser vendedoras em seus próprios comércios. Com a calculadora inclusa, as crianças podem realizar cálculos, escanear produtos, calcular o valor das compras e até mesmo passar o cartão de crédito, estimulando a criatividade e a habilidade matemática. Além disso, a Caixa Registradora Unique Barbie é produzida com materiais de qualidade, garantindo durabilidade e segurança durante as brincadeiras. Presenteie a sua pequena com este brinquedo encantador que vai proporcionar momentos de diversão e aprendizado. Diferenciais:Estimula a imaginação e criatividade das crianças. Possui calculadora funcional para realizar operações matemáticas. Cores vibrantes e detalhes encantadores. Seguro e durável. Mais sobre o Produto:Simular ser uma vendedora. Utilizar a calculadora para realizar cálculos. Escanear produtos e calcular o valor das compras. Passar o cartão de crédito de brincadeira. Dicas de Uso:A Caixa Registradora Unique Barbie é ideal para brincadeiras individuais ou em grupo. Incentive as crianças a criarem suas próprias histórias e se divertirem enquanto aprendem a lidar com dinheiro e realizar cálculos de forma lúdica. Ficha Técnica:Marca: Fun Divirta-se; Nome do produto: Barbie Caixa Registradora Unique; Idade recomendada: A partir de 3 anos; Selo Inmetro: 014551/2024; Contém: 1 caixa registradora fabulosa.', 287.49, 287.49, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7reo7-m271on1z9q2j57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F22493516085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
