INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398718792', 'Jogo Viagem Pela História - Grow', 'Jogo Viagem Pela História - Grow Um jogo de perguntas e respostas sobre a História do Brasil, desde a época do Descobrimento até os dias de hoje! Para vencer, além de responder corretamente as perguntas, o jogador vai precisar ajudar os outros jogadores nas perguntas passando dicas, desenhando ou através de mímicas. Quem chegar mais longe na linha do tempo do tabuleiro, entrará para a História como o grande vencedor! Selo Inmetro: 7908010143669', 110.99, 110.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7qvf6-lj5x91c6plvq07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F21398718792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199262046', 'Guarda-Roupa Casal Vigo 6 Portas 3 Gavetas', 'Descrição: O(a) Guarda-Roupa Casal Vigo 6 Portas 3 Gavetas Branco - Loja é produzido em MDP na escala de brilho Fosco, e possui um grau de dificuldade de montagem: Médio. Seu revestimento/acabamento é: Laca. Infelizmente a Loja não oferece serviço de montagem, deixamos essa informação bem clara em todas as nossas páginas de produto. Onde especificamos que os móveis chegarão desmontados, e que a montagem fica por conta do cliente. Como não oferecemos esse serviço não embutimos o mesmo no preço dos produtos, ou seja, maior economia para você! Todos os nossos móveis também acompanham o manual de montagem, e caso você queira, pode realizar a montagem você mesmo, sempre especificamos os graus de montagem dos produtos. Nos casos de grau baixo e médio, com pouco ou nenhum conhecimento, você mesmo pode efetuar a montagem, e fazer essa economia. Apenas nos graus de montagem alto, recomendamos a contratação de um montador com experiência, visto que são montagens mais complicadas. A montagem é feita com Parafusos, cavilhas e Minifix.. Este móvel é indicado para que seja utilizado no(a) Quarto e Quarto Infantil, dando um toque especial no cômodo de sua casa. Para que você mantenha seu produto sempre em ótimo estado, recomendamos que use apenas um pano seco ou levemente umedecido, sem o uso de quaisquer produtos abrasivos. A Loja garante aos clientes, 90 dias de garantia nos produtos, porém, recomendamos que entre em contato com o fornecedor/marca do produto, pois o mesmo(a), pode garantir um prazo maior de garantia. Lembrando ainda que: quaisquer objetos decorativos que aparecem nas imagens, não acompanham o produto. Características: - Material da Estrutura: MDP - Necessita de Montagem: Sim - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Grau de Dificuldade da Montagem: Médio - Sistema de Montagem: Parafusos, cavilhas e Minifix. - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Recomendação de Manutenção: Utilizar pano levemente umedecido, seguido de pano seco. Não utilizar quaisquer produtos abrasivos. - Indicação de Uso: Quarto e Quarto Infantil - Garantia (dias): 90 - Escala de Brilho: Fosco - Acompanha: Guarda-Roupa - Material do Cabideiro: Madeira - Peso Suportado no Cabideiro (Kg): 6 - Possui Sapatas?: Não - Modelo: Solteiro - Quantidade de Cabideiros: 3 - Revestimento /Acabamento: Laca - Possui Rodízios?: Não - Quantidade de Portas: 6 - Tipo de Porta: Portas de Bater - Quantidade de Gavetas: 3 - Possui Espelho?: Não - Possui Vidro?: Não - Peso Suportado nas Gavetas (Kg): 5 Kg - Material das Corrediças: Plástico - Material das Dobradiças: Alumínio - Material do Puxador: Plástico - Espessura da Estrutura: 12 mm - Possui Gavetas?: Sim - Tipo da Corrediça: Convencional - Possui Portas?: Sim - Material da Porta: MDP - Espessura da Porta: 12 mm - Possui Prateleiras?: Sim - Quantidade de Prateleiras: 3 - Peso Suportado nas Prateleiras:: 5 Kg - Possui Puxadores?: Sim - Linha ou Coleção: Vigo - Possui Pés?: Não - Tipo de Guarda-Roupa/Closet: Convencional - É frágil?: Sim - Possui Ripamento?: Não - Montagem Invertida?: Não Pode ser Montado Invertido', 806.59, 730.33, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-7rd42-lvjfifng5aqi8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F580791382%2F21199262046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897087942', 'Sabão Líquido Ação Total Sem Perfume 7L Brilhante', 'Sabão Líquido Ação Total Sem Perfume 7L Brilhante Detergente versátil, que pode ser utilizado desde a lavagem de roupas até a limpeza de superfícies. Sua fórmula hipoalergênica e sem fragrância o torna ideal para estabelecimentos Food Service, como bares e restaurantes. Produto multiuso pode ser usado na limpeza de uniformes, guardanapos e toalhas de mesa, roupas de cama e toalhas de banho, além de superfícies como pisos e azulejos. Indicação de Uso: - Recomendado para a lavagem de guardanapos, toalhas de mesa, uniformes, cama, toalhas de banho, azulejos e pisos; - Evite o uso direto em superfícies de mármore e granilite, pois pode apresentar manchas devido ao desgaste químico; - Produtos de lava roupas não devem ser misturados com produtos à base de cloro; - Tempo ideal de molho de até 2 horas. Modo de Uso: - Lavagem das Roupas: Adicione ½ copo americano de 200ml no compartimento indicado para detergente; - Limpeza das Superfícies: Antes da sua aplicação remova a sujeira superficial (pó, areia, etc.) com o auxílio de uma vassoura ou pano; - Limpeza Diária: Dilua 1 copo americano de 200ml do produto em 30L de água; - Limpezas Pesadas: Dilua 3 copos americanos de 200ml do produto em 30L de água. Fragrância: Sem perfume Embalagem: 01 galão de 7L', 122.48, 71.72, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-82619-mkcp8sceaxvk49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F21897087942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
