INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597500437', 'Pneu Goodyear Aro 18 Wrangler Workhorse AT 265/60R18 110H', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O pneu para qualquer desafio! O Goodyear Wrangler Workhorse AT é o modelo ideal para SUV e Pick-ups que precisam de um parceiro durável, resistente e com desempenho em qualquer terreno. O Wrangler Workhorse AT é um pneu All Terrain com tecnologia exclusiva Soybean Oil, que utiliza soja em seus componentes. Essa tecnologia permite uma durabilidade maior e menor consumo de combustível. Ou seja: ainda é um pneu com preocupação ecológica. Além disso, a tecnologia e o desenho da banda de rodagem contribuem para um aumento na segurança, aderência em piso molhado 20% maior do que seu antecessor. Os blocos mais largos em seu desenho permitem melhor escoamento da água e tração em terrenos Off-Road. O Goodyear Wrangler Worhorse AT é a escolha certa pra quem procura desempenho e aventura em qualquer condição! Sobre a marca Goodyear A marca Goodyear Considerada uma das maiores marcas de pneus no mundo, a Goodyear possui 2 centros de inovação, 48 fábricas e está presente em 22 países. Fundada por por Frank Seiberling em Akron, Ohio (EUA), já últrapassou os 100 anos de existência e hoje em dia conta com mais de 64 mil colaboradores no mundo todo. Investindo constantemente em inovação para fabricar pneus para automóveis, caminhões comerciais e leves, utilitários esportivos, carros de corrida, aviões e máquina agrícolas, é líder de vendas no mercado norte americano.', 1398.98, 1398.98, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd3x-lval8eagdkmdaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23597500437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11734656841', 'Macacão de bebê Vira Pé Amiguinha Hipo - Suedine 100% Algodão', 'DESCRIÇÃO Seu bebê merece esse conforto! O Macacão Vira Pé com Ziper e protetor de Ziper é uma exclusividade da Amore pensada especialmente para os pequenos. São macias e confortáveis, feitas com tecido Suedine 100% algodão, para tornar o dia do seu amor mais alegre e cheio de estilo. DETALHES • Confeccionados com tecido macio em Suedine 100% Algodão • Vira Pé • Ziper • Protetor de Ziper TAMANHO • RN = Recém Nascido • P = 3 Meses de Idade • M = 6 Meses de Idade • G = 9 Meses de Idade • GG = 12 Meses de Idade Ou em Centímetros. O tamanho em centímetros é entre a gola do macacão e o pezinho. RN - 48cm P - 51cm M - 56cm G - 61cm GG - 66cm ESPECIFICAÇÕES 1 Macacão com Ziper A mercadoria é composto somente pelos produtos da descrição acima.', 34.9, 32.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfbc9umi93ifef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F11734656841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
