INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697432940', 'Maçaneta Interna Completa Porta Dianteira / Traseira Esquerda Celta 2000 A 2006', 'Comprando até 12h30, nós enviaremos no mesmo dia. Receba seu produto rápido! Garantia de 3 meses e suporte especializado no chat. Renove a maçaneta interna da porta do seu Chevrolet Celta G1 2000 a 2006 com esta peça completa e de alta qualidade. Compatível com as portas Dianteira e traseira esquerda, esta maçaneta é a solução ideal para garantir o funcionamento suave e eficiente das suas portas. Características Principais: Maçaneta interna completa para portas Dianteira e traseira esquerda Cor: Preta Compatível com Chevrolet Celta G1 2000, 2001, 2002, 2003, 2004, 2005 e 2006 Qualidade e Durabilidade Garantidas: Fabricada pela marca Universal, reconhecida pela sua excelência em peças automotivas, esta maçaneta interna é feita com materiais de alta qualidade, garantindo durabilidade e resistência ao uso diário. Além disso, oferecemos uma garantia de 3 meses para sua total tranquilidade. Aplicação: Compatível com os modelos Chevrolet Celta G1 2000 a 2006 Instalação Fácil: A instalação desta maçaneta é simples e rápida, podendo ser realizada sem complicações. Caso tenha alguma dúvida, nosso suporte especializado está disponível para ajudá-lo no chat. Renove o interior do seu Chevrolet Celta com esta maçaneta interna completa e garanta o funcionamento suave e eficiente das suas portas!', 37.29, 33.57, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk8-lmoqho2z6yxl2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F18697432940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
