INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8359549620', 'Papel sulfite carta 75g 216x279 com 500 folhas Chamex', 'O Papel Sulfite Carta Chamex é perfeito para suas necessidades de impressão e cópias no dia a dia. Com formato 216mm x 279mm (tamanho Carta), resistente e com corte perfeito, este papel é ideal para uso em impressoras jato de tinta, laser e multifuncionais, garantindo resultados profissionais e de alta qualidade. Detalhes: - Formato Carta (216 x 279 mm): Tamanho versátil e amplamente utilizado em escritórios e demais instituições. - Superfície Lisa e Uniforme: Impressões nítidas e sem borrões, garantindo excelente acabamento. - Coloração: Branco premium realça textos e imagens com ótimo contraste. - Alta Resistência: Papel durável que não rasga ou amassa com facilidade. - Gramatura 75g: Leve e eficiente para diversos tipos de impressões e cópias.', 53.36, 39.9, NULL, 'Stationery > Notebooks & Papers > Printing & Photocopy Paper', 'https://cf.shopee.com.br/file/sg-11134201-82584-mq7u0al1wpvkdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F8359549620', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
