INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18196907347', 'Kit Ferragens p/ Porta Camarão Sem Dobradiça - 60 cm Bronze - Alfer', 'A porta camarão é considerada por muitos um modelo moderno e versátil, que oferece conforto e melhor aproveitamento do espaço para diferentes áreas da casa. Sua principal característica é o tipo de abertura, que é aberta lateralmente, deslizando sobre o próprio vão. Há dobradiças no meio da porta que permitem seu movimento deixando uma folha paralela à outra, recolhendo-se na lateral e permitindo a passagem de pessoas, luz e a corrente de ar. Além economia de espaço, outra vantagem da porta camarão é que não haverá mais portas batendo na parede. O funcionamento deste kit para instalação de porta camarão ou sanfonada, conta com o apoio de um trilho superior e outro componentes que permitem o deslizamento das portas instaladas. ATENÇÃO: Não acompanha dobradiças, não acompanha trinco, não acompanha puxador, não acompanha porta. Características Gerais do Produto: • Capacidade de Carga Total: 25kg • Capacidade de Portas: Duas Portas • Cor: Bronze • Fixação: Parafuso • Garantia: 3 meses • Marca: Al-Fer • Material Trilho: Alumínio • Medida Trilho Total: 60 cm • Uso Indicado: Porta Camarão / Sanfonada Acompanha o produto: • 01 Trilho(Corrediça) • 01 Chapa de Trava • 01 Cursor Deslizante com Mola • 02 Pivô com Mola • 01 Trava Inferior Cantoneira • 01 Pivô Recartilhado Inferior • Manual de Instalação • Parafusos e Buchas para Instalação Garantia: • 3 meses', 42.9, 42.9, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/sg-11134201-7qvd1-lgau1q2mfgv9a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F575316573%2F18196907347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
