INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42361509765', 'Carrinho Infantil Rolemã Ginga Car com LED Brinquedo Criança Brincadeiras de Rua Presente Toymix', 'O Carrinho Infantil Rolemã Ginga Car é ideal para proporcionar diversão segura e estimulante para crianças a partir de 3 anos. Com funcionamento por impulso no volante, não requer bateria, pilhas ou energia elétrica, promovendo uma brincadeira ativa e intuitiva. Possui rodas em PU que garantem deslizamento suave e silencioso, além de apoio antiderrapante para os pés, proporcionando maior segurança. Seu volante ergonômico facilita a condução e estimula a coordenação motora e o equilíbrio. Características: -Funcionamento sem bateria ou energia elétrica -Rodas em PU para maior estabilidade e silêncio -Volante ergonômico e apoio antiderrapante para os pés -Estrutura resistente com excelente acabamento -Iluminação LED nas rodas para maior atratividade visual Medidas: -Faixa etária recomendada: a partir de 3 anos -Peso máximo suportado: 50kg -Dimensões do produto com embalagem: 65 x 41 x 35 cm -Peso aproximado: 4kg Composição: -Material: Plástico resistente -Embalagem: Papelão -Itens inclusos: 1 carrinho Ginga Car Imagens e vídeos são meramente ilustrativos. A tonalidade da cor pode variar conforme o monitor.', 499.9, 275.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md0pptrgubzm96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F42361509765', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397778207', 'Ingleza Cera Líq Calçado Preto 60ml', 'Brilho e proteção! Protege, dá brilho e amacia os calçados e artigos em couro. Oferece brilho instantâneo! Modo de usar: Agite antes de usar. Limpe a superfície. Pressione suavemente o aplicador sobre a superfície até umedecer a esponja. Espalhe uniformemente. Deixe secar. O brilho é instantâneo! NÃO PRECISA LUSTRAR! Lave o aplicador após o uso. Onde usar: Utilize em calçados e artigos em couro, como malas, bolsas, pastas e outros. ATENÇÃO! Não utilizar em calçados de Nobuk, camurça e couros que não possuam tratamento tipo verniz ou similar.', 20.24, 20.24, NULL, 'Men Shoes > Shoe Care & Accessories > Shoe Care & Cleaning Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0bskhblq9pcc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F23397778207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
