INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209319501', 'Sandália Feminina Ipanema Class Modern', 'A Sandália Class Modern Ipanema traz um visual moderno e elegante. O modelo conta com detalhe metálico em destaque nas tiras, que valoriza o design e adiciona um toque sofisticado. Versátil e confortável, é perfeita para compor looks do dia a dia com estilo. *Pedidos realizados através de CNPJ não serão faturados.', 49.99, 49.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-820lb-mncvwihgntadc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F58209319501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256589848', 'Mineiraço Pão de Queijo Mini Provolone Congelado KIT 2 x 400g (800g)', 'Massa de pão de queijo congelada com queijo provolone, de sabor marcante e irresistível. As bolinhas assam direto do freezer, sem pré-aquecer, resultando em uma textura crocante por fora e macia por dentro. Prático e saboroso, é perfeito para cafés, lanches e recepções. Forno convencional/elétrico: disponha as unidades congeladas em assadeira, com espaço entre elas. Asse a 180°C por ~35 minutos até dourar. Não usar micro-ondas. Airfryer: 160°C por ~20 minutos (lotes pequenos). Não descongelar. 100% sem glúten - sem risco de contaminação cruzada', 32.0, 32.0, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/br-11134207-820lh-mlm56816zymc7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1640913654%2F58256589848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899250488', 'Maiô Adulto Racerback Melhor Desempenho Atividades Aquáticas Speedo - MARINHO', '⚠️ Atenção ao tamanho! Nossa modelagem é menor que o padrão. Para garantir conforto, escolha um número acima do habitual. 😉 O Maiô Racerback Speedo foi desenvolvido para quem busca desempenho e conforto dentro e fora da água. Com tecido liso e modelagem New Racer nas costas, ele garante total liberdade de movimento e ajuste ao corpo, sendo ideal para a prática esportiva e momentos de lazer. Produzido com Lycra® XTRA LIFE, o modelo oferece resistência até 10 vezes maior ao cloro do que as lycras convencionais, prolongando a vida útil da peça sem comprometer o conforto ou o visual. Detalhes do produto: • Modelagem New Racer: costas nadador para mais mobilidade • Tecido liso com toque macio e excelente elasticidade • Logo Speedo bordado, sinônimo de autenticidade • Proporciona liberdade de movimento com ajuste perfeito ao corpo • Produzido com Lycra® XTRA LIFE: maior resistência ao cloro e durabilidade • Composição: Tecido Externo: 86% Poliamida / 14% Elastano Dicas de Uso: • Não guarde a peça úmida • Não use amaciantes ou produtos com alvejantes à base de cloro • Evite o contato com superfícies ásperas • Sua peça possui instruções específicas para lavagem, secagem e formas de passar — confira na etiqueta • Cloro e bronzeadores podem manchar o produto. Após o uso, enxágue bem a peça em água fria • A contínua exposição à luz forte do sol e à água clorada pode deteriorar alguns tipos de tecidos e cores', 219.9, 219.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjh19t70lq816c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242944993%2F19899250488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599232699', 'KIT Lash Princess + Booster essence', 'Esse kit contém 2 produtos. 1 - Primer de cílios VOLUME BOOSTER essence O primer de cílios Volume Booster essence confere volume extra aos cílios. Aplique uma camada antes da máscara de cílios. Sua fórmula cremosa branca contém ingredientes nutritivos, como óleo de açaí e manteiga de manga e pode ser combinada com qualquer máscara de cílios. Possui um delicado cheirinho de manga. 2 - Máscara de cílios Lash Princess false lash effect essence A máscara de cílios,popularmente conhecida como rímel, Lash PRINCESS false lash effect essence proporciona alongamento,curvatura e volume.', 84.8, 76.32, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-7rcca-lt5m2e5ye48r03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F21599232699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593581201', 'Sandália Feminina Lumiss Rasteira Confortável Juta Esfera Bico Quadrado', 'A nossa rasteira é a combinação perfeita de sofisticação e modernidade. Com um design elegante e enfeites metalizados, ela adiciona um toque de brilho ao visual, sem perder o conforto. Ideal para diversas ocasiões, é a escolha certa para quem busca estilo e leveza em um único calçado. ESPECIFICAÇÕES DO PRODUTO *Material - Napa Sintética Soft Confort *Solado - Expandido, não escorrega, emborrachado, não faz barulho, anti-derrapante. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 23,0 cm Tamanho 35 --- 23,5 cm Tamanho 36 --- 24,0 cm Tamanho 37 --- 24,5 cm Tamanho 38 --- 25,0 cm Tamanho 39 --- 26,0 cm Tamanho 40 --- 26,5 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 139.9, 69.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3no372tmwxk29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F22593581201', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20144020152', 'Frigideiras Antiaderente Tramontina Com Tampa 20 / 24 / 28 Cm', 'Frigideira Tramontina Turim em Alumínio com Revestimento Interno e Externo em Antiaderente Starflon Max – Com Tampa de Vidro Montre Se você está em busca de uma frigideira antiaderente eficiente, durável e prática para o seu dia a dia, a Frigideira Tramontina Turim com tampa de vidro Montre é a escolha ideal! Produzida com corpo de alumínio de alta qualidade e espessura de 1,2 mm, essa frigideira garante um cozimento rápido e uniforme dos alimentos, ideal para preparar suas receitas favoritas de maneira ágil e eficiente. O revestimento antiaderente Starflon Max, presente tanto na parte interna quanto externa, é um grande destaque. Ele não apenas impede que os alimentos grudem, facilitando a limpeza, como também é extremamente durável e totalmente seguro, já que é livre de PFOA, uma substância prejudicial à saúde. Além disso, a frigideira vem equipada com um cabo de baquelite antitérmico, que não aquece durante o uso, oferecendo segurança extra no manuseio e evitando queimaduras. Para completar, acompanha uma tampa de vidro Montre com bordas de aço inox e puxador de baquelite, que mantém o calor e o vapor no interior, garantindo um cozimento mais uniforme e alimentos mais suculentos. Essa frigideira é compatível com fogões a gás, elétrico e vitrocerâmico, e ainda pode ser levada à máquina de lavar louças, tornando sua limpeza rápida e prática. Variedade de Tamanhos: A Frigideira Tramontina Turim está disponível em diferentes tamanhos e capacidades para atender às suas necessidades culinárias. Escolha o tamanho ideal para suas receitas selecionando a variação desejada no anúncio: • 20 cm – 0,8 L: Ideal para pequenas porções e refeições rápidas. • 24 cm – 1,4 L: Perfeita para receitas do dia a dia, como grelhados e frituras leves. • 28 cm – 2 L: Excelente para preparos maiores, garantindo maior versatilidade na cozinha. Benefícios: • Corpo em alumínio com espessura de 1,2 mm: garante um aquecimento rápido e uniforme. • Revestimento antiaderente Starflon Max: mais resistente, fácil de limpar e livre de PFOA. • Cabo de baquelite antitérmico: não aquece, proporcionando maior segurança no manuseio. • Acompanha tampa de vidro Montre: bordas de aço inox e puxador de baquelite, para cozimentos mais eficientes e suculentos. • Compatível com fogões a gás, elétrico e vitrocerâmico: versatilidade no uso. • Pode ir à máquina de lavar louças: praticidade na limpeza. Dicas de Uso e Conservação: • No primeiro uso, lave bem a frigideira com esponja macia, sabão neutro ou detergente líquido. • Unte a parte interna com um pouco de óleo e aqueça por 1-2 minutos antes de usar pela primeira vez. • Utilize sempre utensílios de silicone, nylon ou madeira para preservar o revestimento antiaderente. • Evite o choque térmico, não imergindo a frigideira quente em água fria. • Para limpeza, não utilize produtos abrasivos e, caso alimentos queimem, umedeça a superfície e use uma esponja para remover os resíduos. Perguntas Frequentes: • Qual a frigideira antiaderente mais saudável? As frigideiras da linha Turim da Tramontina, como esta, são livres de PFOA, o que as torna seguras para a saúde. • O que fazer no primeiro uso da frigideira antiaderente? Lave com esponja macia e unte levemente com óleo antes de usar. • Como lavar uma frigideira antiaderente? Lave com esponja macia e sabão neutro, evitando produtos abrasivos. Com a Frigideira Tramontina Turim com Tampa de Vidro, você garante praticidade e eficiência, sem abrir mão de segurança e durabilidade. Escolha o tamanho ideal para suas receitas e torne suas refeições ainda mais saborosas! Sobre a Lojas Montre A Lojas Montre, localizada em Americana, no interior de São Paulo, é uma revendedora autorizada dos produtos Tramontina. Desde agosto de 2020, estamos comprometidos em oferecer aos nossos clientes apenas produtos originais e de altíssima qualidade. A Tramontina, uma marca 100% brasileira, foi fundada em 1911 e se tornou referência mundial na produção de utensílios domésticos, como panelas, talheres, ferramentas, móveis e muito mais. Se você está buscando onde comprar Tramontina em São Paulo ou quer um e-commerce de confiança, nós somos a escolha certa. Com mais de 60 mil pedidos enviados nos últimos 12 meses, a Lojas Montre está há 4 anos no mercado, entregando os melhores produtos para todo o Brasil. Aqui, você encontra tudo que a Tramontina produz com garantia de originalidade, seja para sua cozinha, jardim ou oficina. Temos orgulho em ser uma empresa que representa a qualidade e tradição da Tramontina, oferecendo praticidade tanto em nossa loja física no interior de São Paulo, quanto em nosso e-commerce, para que você tenha acesso aos melhores produtos no conforto de sua casa. Compre com segurança e confiança!', 123.0, 71.99, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1d1zs28wloga6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333246733%2F20144020152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297618343', 'Torneira Boia Plástica Vazão Total Com Balão Plástico Verde Amanco 3/4"', 'A Torneira Boia de Vazão Total tem a função de regular o nível de água no reservatório, permitindo maior pressão de trabalho com maior vazão de água comparada a torneira boia convencional. INFORMAÇÕES TÉCNICAS Marca: Amanco Material: Polietileno na cor verde; Corpo plástico na cor branca; Haste em alumínio. Pressão de Serviço: : 7,5 Kgf/cm (7,5 Bar) Temperatura de Serviço: 60C; Bitola: 3/4 Informações Complementares: Fácil instalação e regulagem; Excelente desempenho; Durabilidade; Fácil ajuste do nível de água; Enchimento mais rápido. SOBRE A FABRICANTE A Amanco Wavin faz parte da Orbia, uma comunidade de empresas que trabalham juntas por um propósito comum: Melhorar a Vida ao Redor do Mundo!', 152.9, 152.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-7rd5x-lx16upb6s9r457', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F22297618343', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
