INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23235641857', 'Tampa Modular Plasútil Encaixa 15540 T3', 'Tampa Modular Plasútil Encaixa 15540 T3 Dimensao: (Comp x Larg x Alt): 21,9 x 7,3 x 0,9 cm Tampa Modelo T3 Modelo compatível com três modelos de Caixas EnCaixa de alturas diferentes A Tampa T3 da Linha EnCaixa colabora na organização de itens que ocupam menor espaço na largura e espaço mediano na profundidade, é adaptável a três produtos da mesma linha com alturas distintas, ela serve como tampa e também como bandeja para alocar objetos em geral O sistema de organização EnCaixa conta com atributos que são essenciais para qualquer organização: 10 formatos de Tampas 26 formatos de Caixas: todos múltiplos do menor formato Paredes retas: sem ângulo, otimizando 100% do espaço na organização! Empilhamento perfeito (com ou sem tampa): o fundo de cada produto encaixa perfeitamente no seu semelhante! Tampas: vendidas separadamente, conforme a necessidade da organização, uma vez que o fundo de cada organizador já fecha o organizador que está posicionado abaixo! Supertransparente: Rápida identificação dos itens armazenados. O que não é visto, não é lembrado! Versatilidade: encaixam em qualquer espaço, seja ele vertical ou horizontal. Organização viva: os organizadores podem migrar de uso e ambiente, conforme o momento ou necessidade de organização. Mais que uma caixa, um sistema de organização! A linha de organizadores enCaixa conta com 26 modelos de caixas, que variam em altura, largura e profundidade, o que torna esse o organizador mais completo e mais versátil do mercado. Fabricado em Politereftalato de etileno (PET) um tipo de plástico super transparente, atóxico e que não contém BPA em sua composição. Este material é MUITO MAIS RESISTENTE A IMPACTOS e mais maleável que a versão anterior em PS (Poliestireno). Produto sensível ao calor: Não pode ser aquecido no micro-ondas. Não pode ser lavado na lava-louças. .', 14.9, 14.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-7qvea-lf09fa3m9njz70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F23235641857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398965042', 'Kit 10 Potes Porta Mantimentos Herméticos Empilháveis Plástico Quadrados para Geladeira Despensa Armário Plasútil', 'Kit 10 Potes Herméticos com Trava Quadrado Plástico Plasútil Dimensao: (Comp x Larg x Alt): 39,0x23,5x23,5 cm - Os conjuntos de potes herméticos da Plasútil são essenciais para organização da sua cozinha ou despensa. São fabricados em polipropileno (PP), atóxicos e livres de bisfenol-A (BPA FREE); Possuem diferencias que farão diferença no seu dia-a-dia e facilitarão sua rotina: - Tampa emborrachada que garante o fechamento hermético e conserva os alimentos frescos e crocantes por mais tempo. -Travas laterais que contribuem para um fechamento seguro. - Modulares: empilhamento entre bases semelhantes. Encaixe perfeito que otimiza espaço em armários e gavetas. - Tampa transparente facilita identificação do conteúdo. - Pode ser levado ao freezer, lava-louças e micro-ondas. - Composto por 10 potes (CxLxA): 4 x 380 ml (11,0x10,4x7,6 cm - QUADRADO BAIXO), 3 x 830 ml (11,0x10,4x14,4 cm - QUADRADO MÉDIO), 2 x 1,24 L (11,0x10,4x21,0 cm - QUADRADO ALTO) e 1 x 1,6 L (11,0x10,4x27,8 cm - QUADRADO ALTO)..', 186.9, 124.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-81zwr-mikla0v0ufwgc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F20398965042', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
