INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259708428', 'Margarina com Sal Qualy', 'A Margarina Qualy com Sal é cremosa e saborosa, perfeita para o seu dia a dia. Ideal para acompanhar pães, torradas e brioches no café da manhã ou lanche da tarde. Qualy Cremosa contém o exclusivo QMIX, uma combinação de vitaminas, selênio e Ômega 3, que são essenciais para a sua saúde. Além disso, a cada pote vendido, outro é reciclado, mostrando o compromisso da Qualy com o planeta.', 10.79, 10.79, NULL, 'Food & Beverages > Dairy & Eggs > Butter & Margarine', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqnelhp7iolr2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259708428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
