INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399094616', 'Garrafa Térmica Wolff Basic de Plástico Preta 300ml', 'Garrafa Térmica Wolff Basic de Plástico Preta 300ml Apresentamos a Garrafa Térmica de Plástico Basic Preta 300ml da Wolff, uma opção prática e versátil para manter suas bebidas na temperatura ideal. Design Simples e FuncionalCom um design minimalista e funcional, esta garrafa térmica em plástico destaca-se pela sua praticidade e versatilidade. Material DurávelFabricada em plástico de alta qualidade, a garrafa térmica é resistente e durável, garantindo a conservação adequada das suas bebidas. Isolamento Térmico EficienteCom isolamento térmico de qualidade, mantém suas bebidas quentes ou frias por um longo período, oferecendo praticidade em qualquer ocasião. Capacidade IdealCom capacidade para 300ml, é perfeita para transportar suas bebidas favoritas para o trabalho, academia, viagens ou para o uso diário. Tampa RosqueávelA tampa rosqueável oferece vedação segura, evitando vazamentos e preservando o sabor e a temperatura das suas bebidas. Adquira já a sua Garrafa Térmica de Plástico Basic Preta 300ml da Wolff e desfrute de bebidas sempre na temperatura perfeita, onde quer que você esteja. Wolff. A excelência em receber, servir e decorar! Contém: 1 Garrafa Térmica Lava Louça: Não Microondas: Não Forno: Não Fogão: Não Freezer: Não Medidas Produto: Altura 15,50cm x Largura 10,50cm x Comprimento 12,50cm Peso: 0,31Kg Cor: Preto Material: Plástico Água corrente e sabão.', 66.0, 43.99, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rat4-mad3y8ycm0oj0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F869809385%2F19399094616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
