INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205552012', 'Tampa para reservatório Mercedes Benz C-Class 1993 a 2011', 'Descrição: A Tampa para reservatório FLORIO 27710 é uma peça que serve nos veículos MERCEDES BENZ C-CLASS, CLASSE A, CLASSE B, CL-CLASS, CLK-CLASS, E-CLASS, M-CLASS, ML-CLASS, SL-CLASS. Confira abaixo as especificações e aplicações detalhadas. Atenção: EMBALAGEM COM 1 UNIDADE Especificações Técnicas: - Cor: PRETO - Material: PLASTICO Aplicação: - MERCEDES BENZ C-CLASS C180 1.8 L 16V DOHC L4 1993 a 2000; - MERCEDES BENZ C-CLASS C180 KOMPRESSOR 1.8 L 16V DOHC L4 2003 a 2008; - MERCEDES BENZ C-CLASS C200 CGI 2.0 L 16V DOHC L4 1994 a 2001; - MERCEDES BENZ C-CLASS C230 KOMPRESSOR 2.3 L 16V DOHC L4 1995 a 2000; - MERCEDES BENZ C-CLASS C230 KOMPRESSOR SPORT COUPE 2.3 L 16V DOHC L4 2001 a 2004; - MERCEDES BENZ C-CLASS C230 KOMPRESSOR T-MODELL 2.3 L 16V DOHC L4 1997 a 2001; - MERCEDES BENZ C-CLASS C240 2.4 L 24V DOHC V6 1997 a 2002; - MERCEDES BENZ C-CLASS C280 2.8 L 18V DOHC V6 1997 a 2000; - MERCEDES BENZ C-CLASS C280 2.8 L 24V DOHC L6 1993 a 1997; - MERCEDES BENZ C-CLASS C320 AVANTGARDE 3.2 L 18V DOHC V6 2002 a 2003; - MERCEDES BENZ C-CLASS C320 ELEGANCE 3.2 L 18V DOHC V6 2000 a 2005; - MERCEDES BENZ C-CLASS C350 3.5 L 24V DOHC V6 2005 a 2006; - MERCEDES BENZ C-CLASS C350 SPORT 3.5 L 24V DOHC V6 2008 a 2011; - MERCEDES BENZ C-CLASS C350 SPORT COUPE 3.5 L 24V DOHC V6 2006 a 2007; - MERCEDES BENZ CLASSE A A200 2.0 L 16V DOHC L4 2004 a 2011; - MERCEDES BENZ CLASSE B B200 2.0 L 16V DOHC L4 2005 a 2013; - MERCEDES BENZ CL-CLASS CL500 COUPE 5.0 L 24V SOHC V8 1999 a 2006; - MERCEDES BENZ CL-CLASS CL500 COUPE 5.0 L 32V DOHC V8 2000 a 2001; - MERCEDES BENZ CLK-CLASS CLK320 CABRIOLET 3.2 L 24V DOHC V6 2003 a 2005; - MERCEDES BENZ CLK-CLASS CLK320 COUPE 3.2 L 24V DOHC V6 1997 a 2002; - MERCEDES BENZ E-CLASS E240 2.4 L