INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7789992735', 'Tinta acrílica fosca Azul Celeste 250ml 503 Acrilex', 'Tinta acrílica de super cobertura. Ideal para trabalhos de artesanato. Pode ser aplicada em diversos materiais como: madeira, papel, cerâmica, isopor, gesso, couro, cortiça, vidro e PET (preparados com Primer Acrilex). Detalhes: - Secagem rápida. - Pode ser lixada. - Excelente aderência. - Pronta para uso. Modo de usar: - Pode ser aplicada com pincel, rolinho de espuma ou esponja. - Dispensa preparação prévia do fundo (exceto vidro e PET). Auxiliares: - Para dar acabamento pode ser utilizado Verniz Acrílico Brilhante ou Fosco, Acrilfix, Lacas ou Verniz Geral. Aplicação em vidro e PET: para garantir aderência, recomendamos aplicar o Primer antes de iniciar a pintura. Consulte as instruções do produto para mais detalhes.', 47.52, 40.4, NULL, 'Stationery > Art Supplies > Water & Poster Colours', 'https://cf.shopee.com.br/file/sg-11134201-82609-mjvdeg6o6epv0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F7789992735', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
