INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49514680285', 'Tiras de LED RGB 30M 20M 15M 10M USB 5V Bluetooth DIY para decoração de teto em ambientes', 'Bem-vindo à nossa loja, todos os nossos produtos estão em estoque. 🌟 🌸 Descrição do Produto: 1. Excelente cor: Proporciona cores fixas e RGB diferentes, com variação de cor excepcional. 🌈 2. Super Brilhante: Toda a luz é difusa, completamente suave e a iluminação é muito uniforme. 3. Fácil de instalar: Cada LED pode ser cortado e estendido. Você pode cortar o comprimento conforme sua necessidade. Ótima flexibilidade, fácil instalação e pode ser dobrado livremente. 4. Alta qualidade: baixo consumo de energia. Vida útil de 50.000 horas 5. Economia de energia: Baixo consumo de calor, sem radiação ultravioleta ou infravermelha 🌸 Fácil de instalar 1. Cortável: Corte no comprimento desejado na marca de corte da fita. 2. Remova: Retire o adesivo da fita. 3. Pressione firmemente sobre a tira onde for necessário e conecte o USB na porta USB. 🌸 Cenários de aplicação: decoração de casa, sala de estar, adequado para hotéis, clubes, discotecas, ruas, parques, bares, empresas de decoração, escadas, tetos, luzes de TV KTV、 Luzes de computador. Parâmetros do Produto: SMD: 5050 Tensão: 5–24V Fonte de alimentação: Interface USB Cor: 5050 RGB 16 cores Comprimento: 10M/15m/20M/30M Controlador: 5050, com controlador de 24 teclas ★ Lembramos que você já recebeu a mercadoria. Se tiver alguma dúvida, pode entrar em contato conosco e responderemos em até 12 horas~', 46.0, 40.64, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134253-8259d-mqy0673yjbph40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F49514680285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
