INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258829944', 'Kit Reforço de Fichário Transparente Pimaco', 'Evite rasgos e prolongue a vida dos seus documentos! O Reforço de Fichário Transparente Pimaco é a solução ideal para quem precisa manter folhas sempre organizadas e intactas. Com aplicação simples e discreta, ele protege os furos das folhas sem alterar a aparência, sendo perfeito para uso escolar, universitário ou profissional. - Reforça furos rasgados e evita novos danos - Transparente e discreto - não interfere na estética - Alta fixação - adesivo resistente e durável - Fácil de aplicar - uso rápido no dia a dia - Economia - evita perda de folhas importantes Detalhes: - Tipo: Reforço adesivo para fichário - Cor: Transparente - Material: Plástico adesivo resistente - Aplicação: folhas de papel, fichários e documentos perfurados - Kit com 3 cartelas de reforços adesivos transparentes Indicações de Uso: - Fichários escolares e universitários - Documentos e relatórios - Folhas rasgadas ou desgastadas - Organização de escritório', 25.51, 21.43, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-81zte-mn1upabd9qma4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F58258829944', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
