INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094704068', 'Relógio Mondaine Automático 32993G0MVNC8 Edição Especial 70 Anos Couro', 'Relógio Mondaine Automático 32993G0MVNC8 Edição Especial 70 Anos Couro Relógio automático em aço combina design primoroso e funcionalidade. Seu visor texturizado com calendário oferece uma leitura precisa das horas, complementada por marcações completas que tornam a visualização mais fácil. O vidro de cristal mineral, altamente resistente a riscos, adiciona durabilidade ao estilo refinado. Parte da coleção comemorativa dos 70 anos da Mondaine, este modelo celebra a tradição e a qualidade da marca, trazendo o charme do maquinismo aparente no fundo e a icônica logo vintage de 1954, um toque de história em cada detalhe. Especificações Técnicas Mecanismo: Automático Miyota Japan 8215 (reserva de marcha 42h) Gênero: Masculino Visor: Preto e Marrom texturizado com efeito fade Vidro: Cristal Mineral Funções: Automático e Calendário Prova d''água: 100m Diâmetro da caixa: 40 mm Largura da pulseira: 18 mm Tamanho do Vidro: 36 mm Característica: Pulseira em couro crocodilo marrom, Fundo Rosqueado, coroa assinada, 21 joias. Garantia: 12 meses pelo fabricante Mondaine Relógio 100% Original, acompanha caixa, manual, certificado de garantia Mondaine e NF. Somos revendedores oficial e autorizado da Mondaine, todos os relógios comercializados pela nossa empresa possuem GARANTIA NACIONAL do FABRICANTE e caso o produto que adquiriu apresente algum defeito durante o período da garantia, basta encaminhá-lo diretamente à assistência técnica mais próxima de sua região, sempre acompanhado do CERTIFICADO de GARANTIA e NOTA FISCAL.', 818.0, 760.74, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-821dw-mgmxbj8rcmixd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F589442593%2F22094704068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494290243', 'Cera Ceramic Liquid Wax 500Ml Uv Spray - Evox', 'Ceramic Liquid Wax Cera Líquida à base de SiO2 Ceramic Liquid Wax proporciona brilho e proteção à pintura veicular. Desenvolvido com cera de carnaúba pura tipo 1 e sílica, o produto forma um filme com que promove resistência e hidrorrepelência, alcançando até 4 meses de proteção na pintura. Contém proteção UV. MODO DE USO: Lavar bem o veículo, eliminando possíveis contaminantes da pintura. Agitar bem o produto antes de usar. Pulverizar uma pequena quantidade do produto na pintura, a 20cm de distância da superfície, em área não superior à 60cm x 60cm. Sem deixar secar, espalhe o produto utilizando uma toalha de microfibra limpa e seca. Realizar o acabamento utilizando uma outra toalha de microfibra limpa e seca, até obter o brilho desejado. Continuar o processo até concluir por completo o veículo. INFORMAÇÕES ADICIONAIS – Pronto uso; – Duração média: até 4 meses; – Rendimento médio: até 15 veículos; – Indicado para uso em superfícies com ou sem vitrificação; – Em caso de repintura, pode ser utilizada após 15 dias.', 69.25, 69.25, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwi-mcy8nw6elz5o90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F22494290243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5986343314', 'Kit com as 4 Borrachas De Vedação Ford Ka e Fluence 2013 2014 2015 2016 2017', 'Temos o prazer de trazer mais um produto de excelente qualidade, sucesso de vendas com preço justo! Kit Borrachas De Vedação de 4 Portas Essa é a borracha que faz o contorno da porta, vai fixada na carroceria, evitando que entre água, poeira para dentro do veiculo, diminuindo até barulhos internos e amortecendo o fechamento da porta. Essas borrachas protetoras são conhecidas como guarnição. Compatível com Ford Ka 4 Portas - 2013 2014 2015 2016 2017 Borrachas na cor Preta. Acabamento com aba. Fixado por encaixe. Produto de excelente qualidade 100% garantido. Para outros carros e modelos, entre em contato conosco. Garantia de 3 meses', 269.0, 269.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/8be26ac75688c5fa36f1c0df6683984f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F5986343314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
