INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27632580601', 'RELÓGIO ORIENT MASCULINO DOURADO MGSS1157 S2KX', 'A Real Times é um revendedor oficial das marcas que comercializa. Estamos há mais de 20 anos no mercado relojoeiro. Trabalhamos apenas com produtos ORIGINAIS e com NOTA FISCAL. Caso seja necessário, a informação pode ser confirmada através dos canais de contato oficiais das marcas parceiras. Especificações Técnicas: Marca: Orient Referência: MGSS1157S2KX Gênero: Masculino Cor da Pulseira: Dourado Cor da Caixa: Dourado Material Da Pulseira: Aço Material Da Caixa: Aço Tamanho da Caixa: 45mm Resistência à água: 5ATM Não recomendado utilizar em água salgada ou durante o banho quente (exceto relógios apropriados para mergulho profissional) É resistente à água: Sim (porém NÃO é a prova d''água e a prova de vapor, ou seja, não é indicado mergulhar, nadar ou tomar banho com o relógio) Conteúdo da Embalagem O relógio vai na caixa original, com a nota fiscal, certificado de garantia e manual de instrução. 1 ano de garantia direto com o fabricante.', 669.0, 541.89, NULL, 'Watches > Others', 'https://cf.shopee.com.br/file/sg-11134201-7renn-m8c1xhemmbrp23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405524229%2F27632580601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992387098', 'Kit 2 Pote Hermetico Plástico Porta Alimentos Frios 1.2L', 'Kit 2 Potes Herméticos Porta Frios com Escorredor – 1,2L Cada | Plasútil Organize, conserve e otimize o seu dia a dia na cozinha! Este kit com 2 potes herméticos de 1,2L da Plasútil é perfeito para armazenar frios, frutas, legumes e muito mais com segurança, praticidade e frescor prolongado. Conta com escorredor interno removível, ideal para alimentos lavados, evitando acúmulo de umidade e mantendo-os sempre prontos para o consumo. ✅ Destaques do Produto: Vedação com borracha: fechamento 100% hermético, mantém os alimentos frescos por mais tempo. Duas travas laterais: mais segurança no transporte e na conservação dos alimentos. Formato empilhável e modular: aproveite melhor o espaço da geladeira e dos armários. Tampa transparente: facilita a visualização, mesmo em gavetas. Resistente a temperaturas de -10°C a 110°C: pode ser usado no freezer, micro-ondas e lava-louças. Borracha acoplada ao pote: impossível perder e muito mais fácil de limpar. Livre de BPA: feito em polipropileno (PP), mais seguro e durável que potes de acrílico, vidro ou poliestireno. Escorredor interno incluso: ideal para frutas, verduras e alimentos higienizados. 📦 Especificações Técnicas: Capacidade: 1,2 litros cada pote Cor: Cinza (com tampa transparente) Quantidade: 2 unidades Material: Polipropileno (PP) livre de BPA Mais praticidade, frescor e organização na sua cozinha. Adquira já o seu kit Plasútil!', 75.83, 38.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqyd7hotevief5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F23992387098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42453464015', 'Kit Lixeira Cozinha Escritório Gancho Suporte Toalha Dourado', '????️ Kit Lixeira + Gancho Suporte de Toalha Dourado – Para Cozinha ou Escritório Deixe seu ambiente mais elegante, funcional e organizado com este kit completo e sofisticado, perfeito para quem busca estilo e praticidade no dia a dia. O que acompanha: Lixeira Plástica com Tampa Basculante – 5 Litros Cor: Branco com tampa dourada Capacidade ideal para pia, bancada ou escritório Material resistente (plástico PP de alta qualidade) Fácil de limpar e transportar Medidas: 24 cm (altura) x 19 cm (largura) Gancho com Suporte de Toalha Dourado – 2 em 1 Design moderno e multifuncional Serve como gancho para utensílios e suporte para toalha de mão Material: Aço inox com acabamento dourado fosco Instalação simples com parafusos (acompanha kit de fixação) Medidas: 6,5 cm x 5 cm Ideal para uso na cozinha, lavabo, banheiro ou escritório ???? Benefícios do Kit Elegância e funcionalidade no mesmo conjunto Combinação perfeita entre branco e dourado Pronto para instalar e usar Ocupa pouco espaço e valoriza o ambiente Ideal para presentes, organização de casa ou uso corporativo ???? Conteúdo da embalagem 1x Lixeira plástica com tampa dourada 1x Gancho com suporte de toalha dourado Parafusos e buchas para instalação ???? Dica: Esse kit é uma excelente escolha para quem deseja adicionar um toque de sofisticação ao ambiente sem abrir mão da praticidade no dia a dia.', 87.49, 87.49, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rauw-mao8mxvu59jk2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F42453464015', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20350045733', 'Massa Plástica Cinza 400gr - Brascola', 'Aplicação: - Produto aplicado com o auxílio de celulóide (aplicador manual). - Nunca aplicar sobre tinta, sempre na chapa nua. - Fácil aplicação e lixamento, maior enchimento e viscosidade, menor porosidade, aspecto homogêneo e alto poder de aderência Descrição: - Indicado para corrigir imperfeições na funilaria de veículos, superfícies metálicas, máquinas e equipamentos. - Utilizado também para marmoraria como cola de peças, cubas e inox. - A tampa do produto poderá ser utilizada como medida para catálise. - A cada tampa cheia do produto, acrescente 20 gtas do catalisador. - O excesso de catalisador pode prejudicar no resultado final da repintura. - Suporta até 80ºC. Lixamento com lixa 36-40. - Tempo de vida útil de 3 a 5 minutos. Secagem em 1 hora (a 25ºC). - A cada 100g do produto, acrescentar 20 gotas do catalisador. - Cor: Cinza - Embalagem 1 latas de 400g -ACOMPANHA CATALISADOR', 25.57, 25.57, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-22090-ioy9wm47tzhvc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F20350045733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208975424', 'Água Micelar Hidratante', 'A Água Micelar Hidratante Beyoung é uma solução de limpeza úmida com foco funcional e sensorial. Proporciona limpeza profunda e delicada, removendo maquiagem, oleosidade e umidade sem agredir a barreira natural da pele. Tem toque limpo e sensação refrescante, sendo ideal para todos os tipos de pele, incluindo os mais sensíveis. Recomendado para uso diário (manhã e noite) como primeiro passo na rotina ou antes da maquiagem. Ela mantém a hidratação da pele e controla a oleosidade com extrema eficácia. Mais que uma água micelar, uma solução para a demanda de cuidados com a pele!', 52.9, 52.9, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/br-11134207-820le-mn4bum38cwledf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1776310895%2F58208975424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
