INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22605044606', 'Filtro Separador Racor Mercedes L 1620 Om906 2006 A 2012', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. >Aplicação L-1620 3-EIXOS 2P (DIESEL) 2006 até 2012 Conteúdo Da Embalagem > 1 Filtro Separador Tipo de Veículo para Caminhões Marca > Com uma ampla e inovadora linha de produtos a Mann-Filter, sempre primando um alto padrão de qualidade em seus produtos, atendendo assim a todas as exigências da montadoras. Contando com filtros de ar, óleo, combustível e cabine para todos os tipos de motores veículares é máquinas. O Produto A função do filtro separador de água do diesel é exatamente o que seu nome diz: retirar a água do diesel. “Ao impedir que esta água contamine o motor, evita-se a corrosão dentro do sistema e que se prejudique assim a injeção do diesel nele. Importante • Tempo de garantia - 3 meses • Imagem meramente ilustrativa • Valor unitário • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7893390801004 Código do Fabricante WK1060/4 >', 101.62, 101.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rblx-llt9n4o688ira8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22605044606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
