INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201012740', 'Kit 2 Potes Tupperware Instantânea Mágica Harry Potter Hogwarts Preto 2,25L', 'O Kit Contém: 2 Potes Tupperware Instantânea Mágica Harry Potter Hogwarts com 2,25L cada unidade. Com tampa hermética de fechamento exclusivo por um toque, a Instantânea Mágica proporciona uma solução de armazenamento à prova de umidade, sendo ideal para armazenar grãos, chips, biscoitos, e muito mais. O fechamento por um toque pode ser facilmente ativado com a palma da mão, e o som de "clique" confirma que a tampa foi fechada corretamente. A aba larga na tampa facilita a abertura, tornando o uso fácil para toda a família. Graças ao design plano da tampa, com uma borda grande, as Instantâneas Mágicas podem ser empilhadas de forma segura para economizar espaço. SOMOS A LOJA OFICIAL DA TUPPERWARE: TODOS OS NOSSOS PRODUTOS SÃO ORIGINAIS E VÊM DIRETO DA NOSSA FÁBRICA PARA O CONFORTO DO SEU LAR.', 243.8, 225.8, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-820m4-mmvq9adub5s00a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608053305%2F58201012740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
