INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698031918', 'Paçoquita Zero Aveia Display 144G Santa Helena', 'A Paçoquita Zero Aveia Santa Helena Display 144G é uma opção deliciosa e saudável para quem busca um doce saboroso sem adição de açúcar. Descrição: Sabor Tradicional com um Toque Especial: Combina o sabor clássico da paçoca Santa Helena com a adição de aveia, proporcionando uma textura e sabor diferenciados. Mantém o sabor original da paçoca, mas sem adição de açúcares. Opção Saudável: Ideal para quem busca uma alternativa com menos açúcar e mais fibras. A aveia adiciona fibras, que auxiliam no bom funcionamento do intestino. Mantém os benefícios do amendoim para a saúde. Praticidade: O display com 144g é perfeito para ter sempre à mão um lanche rápido e nutritivo. Contém 8 unidades de 18g. Qualidade Santa Helena: Produzida pela Santa Helena, marca reconhecida pela qualidade de seus produtos à base de amendoim. Benefícios: Sem adição de açúcares. Fonte de fibras. Sabor delicioso. Prática para o dia a dia. Informações Adicionais: Peso: 144g (display com 8 unidades de 18g cada) Ingredientes: Amendoim torrado, fibra de aveia, polidextrose, edulcorantes naturais maltitol e glicosídeos de esteviol e sal. Alergênicos: Contém amendoim e aveia. Pode conter trigo, ovo, soja, leite, amêndoas, castanha de caju e castanha do Brasil.', 18.99, 18.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6phn8qr5suf5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F21698031918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
