INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392964470', 'Película para iPhone 15 Pro Max - Defender Glass Preta - Gshield', 'Proteja a seu dispositivo com a melhor película para iPhone 15 Pro Max A Película Defender Glass da Gshield é fabricada com vidro duplamente temperado e bordas laterais em poliuretano de alta densidade com elevação de 2 milímetros que garantem maior resistência à impactos e evita que a película trinque com facilidade nas extremidades. As bordas laterais possuem um diferencial único de proteção e se diferem das películas 3D e 5D convencionais, que são apenas jateadas de tinta e não possuem elevação. Além disso a película Defender Glass conta com uma camada oleofóbica e é de fácil instalação.', 87.97, 87.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rd5w-luaqw6pz0uqw81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23392964470', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
