INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397987034', 'Chinelo Flat Vizzano Feminino Tira Pronta Strass Casual 6459.128', 'Brilhe muito no verão com esse Flat Vizzano, super versátil e que vai bem em várias ocasiões! Ele possui duas tiras grossas metalizadas com strass, formando uma decoração autêntica e sofisticada. Elas são forradas na parte interna e um elástico lateral vem para facilitar o calce e trazer muito mais conforto. A palmilha é extremamente macia e o solado tratorado de aproximadamente 3 cm dá um contraste de estilo com a delicadeza e brilho do strass. Aproveite e marque presença com a Vizzano!', 169.89, 89.88, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-81zvv-mmj1q9piq4n783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F18397987034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257612675', 'Película para Poco X8 Pro - Hydrogel Gamer Fosca - Gshield', 'DESCRIÇÃO Aumente a resistência do seu Poco X8 Pro com a película de Hydrogel Fosca! A Película de Hydrogel Fosca da Gshield oferece uma proteção avançada para a tela do seu Poco X8 Pro, garantindo uma experiência duradoura e sem preocupações. Desenvolvida com a inovadora tecnologia hidro nano pet e TPU Soft Gel, essa película é resistente contra riscos indesejados. O revestimento oleofóbico da película não apenas aprimora a resistência contra arranhões, mas também reduz as marcas de digitais na tela, proporcionando uma visão clara e nítida em todos os momentos. A adaptação perfeita às extremidades curvadas do seu dispositivo assegura uma cobertura completa do visor, preservando a estética e funcionalidade do aparelho. Escolher a Película de Hydrogel Gshield é optar por um escudo de proteção sofisticado, que une tecnologia de ponta e durabilidade para manter a tela do seu celular impecável. Cuide do seu Poco X8 Pro com estilo e confiança, investindo na excelência em proteção que só a Gshield proporciona. Clique aqui para acessar os manuais dos produtos Gshield. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mm94eq68gutk23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F58257612675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
