INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891828207', 'Película Redmi Note 10S-Traseira Fibra Carbono Preta-Gshield', 'Proteja a traseira com a película para Xiaomi Redmi Note 10S A Película Traseira de Fibra de Carbono Preta para Xiaomi Redmi Note 10S, da Gshield, é projetada para proporcionar uma camada de proteção adicional, garantindo que seu aparelho fique livre de riscos e arranhões indesejados na parte de trás. Com seu acabamento em fibra de carbono preta, ela não apenas oferece segurança, mas também adiciona um toque estiloso ao seu smartphone.', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7qvf6-lhhsfrvmuq0n7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22891828207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23295928839', 'Jogo de Chaves de Fenda com Pontas Intercambiáveis 6 peças - Tramontina', 'Um belo kit de chaves de fenda irá proporcionar muita praticidade para a sua vida, sem dúvidas. Então conheça o Jogo de Chaves de Fenda Tramontina com Pontas Intercambiáveis 6 peças. As pontas intercambiáveis fazem desse conjunto um item perfeito pra você, pois tem peças diversificadas e muito práticas. Além disso, as ferramentas são testadas com rigorosos padrões de qualidade, lhe garantindo durabilidade e resistência. - As hastes das chaves de fenda são testadas em máquinas de ensaio específicas, para verificar o perfeito balanço entre resistência mecânica e dureza. - Cabos injetados com material de alta resistência. - Os dimensionais das pontas são verificados com gabaritos-padrão, calibrados e certificados. Itens inclusos: 3 ponteiras ponta chata: 1/8x3", 3/16x3" e 1/4x3", 3 ponteiras ponta cruzada: 1/8x3", 3/16x3" e 1/4x3" e 1 suporte para ponteira. Especificações técnicas: - Código de fábrica: 41110/506 - Peso: 0,220 Kg', 31.9, 31.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qveg-lhoz81ylxnn808', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23295928839', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092820616', 'Chave Biela Com Furo Passante 10mm (400,0018) -Noll', 'A CHAVE BIELA C/FURO PASSANTE 10MM da Noll (400,0018) é uma ferramenta essencial para qualquer entusiasta ou profissional que busca qualidade e durabilidade em suas ferramentas. Fabricada com precisão, esta chave oferece um desempenho excepcional em uma ampla gama de aplicações. A construção cromada confere à chave uma resistência superior à corrosão, garantindo sua longevidade mesmo em ambientes desafiadores. O furo passante proporciona versatilidade adicional, permitindo a utilização em parafusos ou porcas de comprimento variável. Durabilidade Excepcional: A construção em aço cromado de alta qualidade oferece resistência superior à corrosão e desgaste, garantindo uma vida útil prolongada da ferramenta. Versatilidade Aprimorada: O furo passante permite a utilização em parafusos ou porcas de comprimento variável, proporcionando flexibilidade em diversas situações de trabalho. Precisão e Eficiência: O design da chave biela Noll é projetado para proporcionar uma aderência confortável e segura, facilitando o manuseio e aumentando a eficiência durante o uso. • Durabilidade Excepcional • Versatilidade Aprimorada • Precisão e Eficiência. Especificações Técnicas: Referência: 400,0018 Marca:Noll A CHAVE BIELA C/FURO PASSANTE 10MM da Noll (400,0018) é uma ferramenta essencial para qualquer entusiasta ou profissional que busca qualidade e durabilidade em suas ferramentas. Fabricada com precisão, esta chave oferece um desempenho excepcional em uma ampla gama de aplicações.', 21.16, 21.16, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcde-lquk8w2hwcincb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22092820616', NULL