INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097312532', 'Esmalte Risqué Cremoso Rose Bombom', 'Toda a linha de esmaltes Risqué Cremoso, além de apresentar textura única e cores marcantes, acompanha as tendências da moda, possibilitando diversas composições de looks e maximizando a beleza da sua maquiagem e acessórios. Com secagem rápida, use a sua imaginação e crie lindas nails art que farão sucesso aonde quer que você vá. Com fórmula especial, livre de componentes que costumam causar alergias, o Esmalte Risqué é perfeito para os cuidados diários. Apaixone-se pela cor, presencie a longa duração e viva a beleza de suas unhas de forma única com os Esmaltes Risqué. Modo de usar: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada. #html-body [data-pb-style="646BA6481E035"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6481E04A"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 16.63, 16.63, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/br-11134201-820mf-mr13ileyrv2e9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20097312532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194847313', 'Creme Hidratante DiabetTX Goicoechea 350g', 'Características do Produto: Marca: DiabetTX Conteúdo: 350g Linha do Produto: Goicoechea Ean: 7898636190515 Características Adicionais: Sua fórmula alivia a aspereza causada pelo ressecamento extremo Foi desenvolvido para peles extremamente secas, que apresentam vermelhidão e descamação Produto com selo de Qualidade e Confiança ANAD (Associação Nacional de Atenção ao Diabetes) Especialmente formulado para o cuidado dos diabéticos, hidrata intensamente a pele, ajudando a prevenir lesões Modo de Uso: Aplique o Creme DiabetTX 2 vezes ao dia sobre a pele limpa e seca, realizando suaves massagens com movimentos circulares até que o creme seja completamente absorvido. Fornecedor: Genomma Laboratories do Brasil Ltda', 53.2, 53.2, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-824iv-mpibc65ypc75ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22194847313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
