INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597084221', 'Cacau Premium 32% 1Kg', 'Este produto é uma bebida sofisticada e saborosa, contendo 32% de cacau em sua formulação. O resultado é um sabor rico e intenso, acompanhado de um amargor característico das amêndoas de cacau de alta qualidade. Sua versatilidade permite que seja apreciado tanto quente quanto gelado, proporcionando uma experiência satisfatória para qualquer apreciador de chocolate em busca de uma bebida de excelência. Modo de Preparo na Máquina de Espresso: Coloque 25g de Chocolate 32% em 100 ml de leite; dilua bem e leve ao vaporizador até dissolver completamente. Modo de Preparo em casa: Aqueça 100 ml. Em uma xícara grande ou caneca; despeje o 25g de Chocolate 32% e parte do leite; mexa bem até dissolver e coloque o restante do leite quente.', 109.9, 109.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-81zvn-midhb4yq9ouca5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F654119500%2F21597084221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
