INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255706711', 'Conjunto infantil menina de sorvete Brandili', 'Encante sua pequena com o conjunto infantil menina composto por blusa confeccionada em malha com uma divertida estampa em gel com glitter de taça de sorvete e morangos, além de uma frase em destaque. As mangas curtas e a gola redonda garantem conforto e estilo. O shorts em moletinho leve possui cós em elástico, proporcionando liberdade de movimento. Ideal para dias de diversão, esse conjunto é perfeito para compor looks alegres e descontraídos.', 69.99, 69.99, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82602-ml3tl98wdyio68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1587066956%2F58255706711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
