INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256750408', 'Lente Retrovisor Convexo KIA Sorento 2011 a 2020 Sem Base', 'Lente Retrovisor Convexo KIA Sorento 2011 a 2020 Sem Base ***ATENÇÃO: SOMENTE A LENTE (VIDRO)*** • IMPORTANTE: Compare o desenho do seu retrovisor com as fotos do anúncio • Não acompanha moldura plástica • Não acompanha motor elétrico • Deve ser fixado com fita dupla face ou adesivo de silicone neutro ESPECIFICAÇÕES TÉCNICAS: • Lado Direito e Lado Esquerdo: Lente CONVEXA o Campo de visão ampliada, eliminando pontos cegos COMPATIBILIDADE: • KIA Sorento 2011 a 2020 o Versões: EX, S e LX SELECIONE A VARIAÇÃO QUE DESEJA: • Lado Direito (Passageiro) • Lado Esquerdo (Motorista) • Par (Direito + Esquerdo) INSTALAÇÃO: 1. Retire o vidro antigo com cuidado 2. Limpe a base plástica com álcool 3. Recomendamos a fixação com Silicone Neutro 4. Centralize a lente e prenda com fiat por 24h até a secagem OBS: Não serve para colar por cima do vidro antigo _______________________________________________________________________ Não nos responsabilizamos pela má instalação ou mau uso do produto.', 77.33, 77.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-820lg-mlpclqfcjn5zeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1254320229%2F58256750408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
