INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19247854112', 'Desodorante Aerosol Antitranspirante Tabu Delicada 150Ml', '✨ Fragrância: Feminina O Desodorante Aerosol Antitranspirante Tabu Delicada oferece proteção eficaz e suave para quem busca frescor e segurança ao longo do dia. Sua fórmula antitranspirante garante até 48 horas de proteção contra suor e odores, enquanto a fragrância delicada proporciona uma sensação de frescor envolvente, sem ser excessiva. Ideal para peles sensíveis, o produto mantém sua eficácia sem causar irritações, sendo perfeito para uso diário. E o melhor de tudo: ele não deixa manchas nem resíduos nas roupas, garantindo praticidade e conforto em cada aplicação. Benefícios: ✅ Proteção duradoura contra suor e odores. ✅ Fragrância floral delicada, perfeita para o dia a dia. ✅ Fórmula suave, ideal para peles sensíveis. ✅ Aplicação prática em aerosol, com secagem rápida. ✅ Sensação de frescor e conforto o dia inteiro. Modo de Uso: 1️⃣ Agite bem antes de usar para ativar a fórmula. 2️⃣ Aplique a uma distância de 15 cm das axilas. 3️⃣ Espere secar naturalmente antes de se vestir. 4️⃣ Use diariamente para frescor e proteção contínuos. Composição: Butane / Isobutane / Propane, Aluminum Chlorohydrate, Dimethicone, Cyclomethicone, Isopropyl Myristate, C-12-15 Alkyl Benzoate, Quarternium -18 Hectorite, 2-Methyl 5-Ciclohexylpentanol, Propylene Carbonate, Parfum, Citronellol, Hexyl Cinnamal, Limonene, Linalool, Buthylphenyl Methylpropional, Alpha Isomethyl Ionone.', 24.99, 13.49, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/36006256e7a6fb7885885b8a0a2aeb0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436104412%2F19247854112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
