INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55953229876', 'Kit Jogo Ralo Zincado Para Lavatório Pia Com Garra - 12 Unidades Evita Lixo Restos Entupimento', 'Comercial Vipasa Distribuidora Kit Jogo Ralo Zincado Para Lavatório Pia Com Garra - 12 Unidades Evita Lixo Restos Entupimento O ralo zincado JWC é a solução ideal para reposição e instalação em pias, tanques e áreas de serviço, garantindo escoamento eficiente da água e maior durabilidade. Fabricado em aço com acabamento zincado, oferece boa resistência contra corrosão, umidade e uso contínuo, sendo indicado tanto para uso residencial quanto comercial. Este kit com 12 unidades é perfeito para lojistas, instaladores, manutenção predial e obras em geral. Produto prático, de fácil instalação, compatível com aplicações comuns do dia a dia. O acabamento zincado proporciona proteção extra e melhor custo benefício, sendo amplamente utilizado em cozinhas, lavanderias, oficinas e ambientes que exigem peças resistentes. Características do produto: Ralo fabricado em aço com acabamento zincado Boa resistência à corrosão e à umidade Modelo funcional e versátil Indicado para pias, tanques e áreas de serviço Produto resistente e durável Marca JWC Kit com 12 unidades Comercial Vipasa Distribuidora', 34.9, 34.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-81z1k-midcr0su4v0h7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F55953229876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3063658241', 'Cartela Super Cola Instantânea Com 12 Unidades Auto Poder De Fixação Couro Metal', 'COMERCIAL VIPASA DISTRIBUIDORA. Cartela Super Cola Instantânea Com 12 Unidades Auto Poder De Fixação * Super Cola Instantânea cartela com 12 tubos de cola instantânea. Ideal para aplicações precisas, alcançando os lugares mais difíceis e aderindo diversos tipos de materiais em segundos. Eficaz e versátil. Indicado para, porcelana, plásticos, couro, metal, borracha, madeira e cerâmica. Cor: Preto e vermelho O envio e conforme o estoque A Cartela Super Cola Instantânea da é uma solução poderosa para todas as suas necessidades de fixação. Composta por 12 unidades, cada uma oferece um poder de adesão instantâneo que garante uma fixação firme e duradoura. A fórmula avançada desta cola proporciona uma aderência rápida e forte em uma variedade de materiais, desde papel e plástico até madeira e metal. Seu design compacto e conveniente permite que você tenha sempre uma solução de fixação à mão para qualquer emergência. Além disso, a Cartela Super Cola Instantânea é projetada com um sistema de aplicação fácil, minimizando bagunças e desperdícios. Seja para projetos domésticos, artesanato, reparos rápidos ou trabalhos profissionais, esta cola é a escolha ideal para quem busca qualidade e eficiência. COMERCIAL VIPASA DISTRIBUIDORA.', 26.9, 23.99, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/br-11134207-820l4-mnmxp429eupudf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F3063658241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997328896', 'Vassoura Plástica Com 22D s/ Cabo (77850221) - Tramontina', 'Mantenha seu jardim sempre impecável com a vassoura plástica laranja Tramontina com 22 dentes, sem cabo. Uma peça fundamental para manter a limpeza no quintal, varrendo folhas secas, aparas de grama ou outros detritos que caem sobre o gramado. A opção sem cabo permite que você utilize um cabo que já possui. Com a Tramontina você tem muito mais praticidade na hora de cuidar do seu jardim. - Informações Técnicas: • Fabricada em polipropileno de alta resistência, proporcionando maior durabilidade e ótimo acabamento. • Possui 22 dentes fixos. • Possui olho de 23 mm de diâmetro. • Dimensões: 41,5 x 54,2 x 5,5 cm • Peso: 0.322 kg Refêrencia: 77850221 Marca: Tramontina Mantenha seu jardim sempre impecável com a vassoura plástica laranja Tramontina com 22 dentes, sem cabo. Uma peça fundamental para manter a limpeza no quintal, varrendo folhas secas, aparas de grama ou outros detritos que caem sobre o gramado.', 19.0, 19.0, NULL, 'Home & Living > Home Care Supplies > Brooms', 'https://cf.shopee.com.br/file/sg-11134201-7rcdj-lrexbo708t0k75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23997328896', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27132581204', 'Foice Roçadeira em Aço Sem Cabo (77600/115) - Tramontina', 'A Foice Roçadeira em Aço Sem Cabo (77600/115) - Tramontina, é ideal para realizar o corte da capoeira com mais facilidade. Produzida em Aço Carbono, essa foice vai levar mais qualidade para o seu trabalho, pois sua lâmina é altamente resistente e afiada. A melhor escolha para elevar o nível do seu trabalho. Descrição do Produto: • A foice é temperada em todo o corpo da peça, proporcionando maior resistência e menor desgaste durante o uso. • Fabricada em aço carbono especial de alta qualidade. • Recebe pintura eletrostática a pó, que tem uma melhor apresentação visual e maior proteção contra oxidação. • A tinta utilizada na pintura é isenta de metais pesados na sua composição, o que minimiza o impacto ambiental. • A lâmina é usinada em máquina de desbaste e sua afiação proporciona excelente durabilidade do fio. • Possui olho de 32 mm de diâmetro. Referência: 77600/115. Cód. de Fábrica: 77600/115. Marca: Tramontina.', 34.34, 34.34, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7renw-m8c36chb5jgg66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F27132581204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
