INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20298130137', 'Shampoo Pantene PRO-V Miracles Antiqueda & Nutrição Biotinamina B3 300ml', 'Você tem queda de cabelo, fios fracos e quebradiços? Pantene apresenta o Shampoo Antiqueda Biotinamina B3 Antiqueda* & Nutrição. Fórmula sem adição de parabenos e com complexo multivitamínico: Biotina', 34.99, 34.99, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-820ml-mo1aq4tj2gp10b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F20298130137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250433093', 'Tênis Casual Feminino Via Marte 261-001-01', 'O Tênis Casual Feminino Via Marte 261-001-01 une conforto e estilo para seu dia a dia. Com design contemporâneo e cores neutras, ele se adapta a qualquer look, do passeio ao trabalho. Ideal para outono/inverno, oferece proteção contra o frio e respirabilidade, sem plataforma, permitindo movimento natural e ajuste perfeito. ***Características do Produto: • Design contemporâneo e neutro: combina facilmente com jeans, saias ou vestidos, adaptando-se ao seu estilo pessoal. • Cabedal em material resistente: proporciona durabilidade, acabamento premium e fácil manutenção. • Forro interno acolchoado: mantém os pés aquecidos e confortáveis mesmo em uso prolongado. • Solado flexível e aderente: garante tração em diferentes superfícies e favorece a postura correta. • Construção sem plataforma: oferece sensação natural ao caminhar, reduzindo a fadiga dos pés. ***Benefícios: • Conforto prolongado: palmilha macia absorve impactos, ideal para jornadas intensas. • Versatilidade de uso: transita sem esforço de ocasiões casuais a compromissos mais elegantes. • Proteção térmica: indicado para outono/inverno, mantém os pés aquecidos sem sacrificar a respirabilidade. • Durabilidade garantida: materiais de alta qualidade resistem ao desgaste diário. • Estilo atemporal: design clean que permanece em alta, valorizando seu guarda-roupa em qualquer estação. Escolha o Tênis Via Marte 261-001-01 e experimente a combinação perfeita de conforto, praticidade e elegância em cada passo.', 224.88, 159.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134201-820lg-mqyrwkffhvd37f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1668934902%2F58250433093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197302727', 'Chave Combinada Com Catraca-M 15mm (408,0054) - Noll', 'A Chave Combinada com Catraca 15mm (408,0054) - NOll é indicada,para uso profissional e residencial, com sistema de catraca que facilita e agiliza apertos e desapertos de porcas e parafusos. Um dos lados da chave possui uma catraca com as mesmas medidas que permite a execução de trabalhos com menor esforço do que os modelos de chaves simples, pois dispensa a retirada da chave para novo movimento de apertar e soltar. • Produzida em aço cromo vanádio • Acabamento cromado e polido • Logotipo e medidas estampadas em baixo relevo facilitando a identificação da ferramenta. Especificações Técnicas: Referência: 408,0054 Marca: Noll A Chave Combinada com Catraca 15mm(408,0054) - NOll é indicada,para uso profissional e residencial, com sistema de catraca que facilita e agiliza apertos e desapertos de porcas e parafusos. Um dos lados da chave possui uma catraca com as mesmas medidas que permite a execução de trabalhos com menor esforço do que os modelos de chaves simples, pois dispensa a retirada da chave para novo movimento de apertar e soltar.', 41.41, 41.41, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcck-lquwu7ng6008c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23197302727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250626617', 'RODIZIO BORRACHA PRETA GIRATORIO SEM FREIO 5POL 125MM SUPORTE PLATAFORMA 100KG 1PC // MTX', 'Roda Giratória MTX 6871655 com Fixação de Plataforma A roda giratória MTX 6871655 é ideal para carrinhos manuais industriais, permitindo manobras em qualquer direção. Fabricada com aro de aço resistente e pneu de borracha, suporta até 100 kg. O revestimento de zinco protege contra corrosão, enquanto o rolamento de deslizamento reduz o desgaste. É silenciosa, não deixa marcas no piso e pode ser usada em ambientes internos ou externos, graças à sua resistência à umidade, raios UV e variações de temperatura de -25 °C a +50 °C. Vantagens Movimento fácil e manobrável em todas as direções Suporte de carga de até 100 kg Revestimento de zinco contra corrosão Rolamento de deslizamento que prolonga a vida útil Silenciosa e sem marcas no piso Resistente ao clima e a temperaturas extremas', 37.97, 37.97, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821cw-mh213y0uk2ku63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F58250626617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
