INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993399912', 'Creatina Monohidratada 150g 100% Pura Bodyaction', 'Uma nutrição equilibrada tem um papel muito importante na qualidade de vida. Com o ritmo acelerado de muitas pessoas, às vezes, é muito difícil prestar atenção a todos os requisitos que o corpo precisa para estar saudável e forte. Neste sentido, os suplementos cumprem a função de complementar a alimentação e ajudam a obter as vitaminas, minerais, proteínas e outros componentes indispensáveis para o correto funcionamento do organismo. *Este produto é um suplemento dietético, não é um medicamento. Suplementa Ante dietas insuficientes. Consulte seu médico e / ou farmacêutico.', 62.38, 49.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0sr8eh0ftjx49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F22993399912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
