INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43561513247', 'Almofada 40x40cm Sonic Speed Zona Criativa - 10064754', 'Almofada 40x40cm Sonic Speed depois de um dia cheio de aventuras, você precisa de uma pausa para descansar? Então essa almofada é para você! Perfeita para os dias de preguiça, não importa se é no sofá ou na cama, essa almofada te acompanha em todos os lugares! A almofada é feita em território nacional, é uma ótima companhia para os dias de preguicinha! É perfeita para sua cama ou sofá, com o enchimento em fibra e um toque aveludado é extremamente confortável! Você pode usar como decoração ou para descansar depois de um dia cheio de aventuras! Especificações: Altura: 40cm| Largura: 40cm| Comprimento: 10cm| Peso: 440gr| Tecido: 100% Poliester| Enchimento: Fibra Cuidados e recomendações de uso: Passar com temperatura máxima de 110° (sem vapor). Não alvejar. Permitido uso de centrifuga e máquina secadora. Temperatura máxima de lavagem 40°. Não limpar a seco. Características: - Marca:Zona Criativa - Modelo:10064754 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Almofada 40x40cm Sonic Speed', 71.13, 62.07, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-7rdym-md0n5tuhgwyu87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F43561513247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
