INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698940959', 'CINTO PARA BOLSAS E COLDRES PORTA MARTELO, 810MM-1120MM, 1PC // MTX', 'Cinto para Bolsas e Coldres Porta Martelo MTX 902479 – Conforto e Praticidade para Profissionais O Cinto para Bolsas e Coldres Porta Martelo MTX 902479 é a solução perfeita para quem busca comodidade e eficiência durante o trabalho. Ideal para mecânicos, trabalhadores da construção civil e profissionais de oficinas, este cinto permite pendurar bolsas, coldres ou suportes de martelo, mantendo suas ferramentas ao alcance das mãos. Esse recurso é especialmente útil quando se trabalha em alturas, garantindo que tudo o que você precisa esteja sempre acessível, sem comprometer a mobilidade. Vantagens: Resistência ao Desgaste: O cinto é feito de material sintético "Oxford", que oferece alta resistência ao desgaste, garantindo durabilidade mesmo em condições de trabalho exigentes. Fixação Segura: A fivela de plástico proporciona fixação segura do cinto, assegurando que ele permaneça no lugar durante o uso. Ajuste Personalizado: O regulador de comprimento permite ajustar o cinto de 81 a 112 cm, garantindo um ajuste confortável para diferentes tamanhos e preferências. O Cinto para Bolsas e Coldres Porta Martelo MTX 902479 é um acessório indispensável para quem busca praticidade e conforto em atividades que exigem o uso constante de ferramentas, proporcionando liberdade de movimento sem perder a organização.', 22.95, 22.95, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824ja-mf9oxp5y524t30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F23698940959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
