INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494704004', 'BROCA FRESA FORSTNER PARA MADEIRA, 42MM, HASTE CILINDRICA, 1PC // GROSS', 'Broca Fresa Forstner para Madeira Gross 70484255: Precisão e Durabilidade para Seus Projetos A Broca Fresa Forstner para Madeira Gross 70484255, com diâmetro de 42 mm e haste cilíndrica, é a ferramenta ideal para quem busca precisão e qualidade na perfuração de madeira, MDF, HDF e outros materiais similares. Projetada para criar furos cegos com paredes e fundo lisos e uniformes, esta broca é amplamente utilizada na fabricação de móveis e em trabalhos de acabamento, garantindo resultados profissionais em cada uso. Vantagens Resistência a Cargas Mecânicas: Fabricada em aço 45, a broca Forstner Gross é altamente resistente a cargas mecânicas, garantindo durabilidade e desempenho consistente mesmo em condições de uso intenso. Esta construção robusta assegura que a broca mantenha sua eficiência e precisão ao longo do tempo. Alta Produtividade e Longa Vida Útil: Graças às placas de metal duro da liga VK8 com dureza de 86-92 HRC, a broca é caracterizada por alta produtividade e longa vida útil. Esta combinação de materiais de alta qualidade permite que a broca enfrente tarefas exigentes sem perder a eficácia, representando um investimento inteligente para profissionais e entusiastas do DIY. Perfuração Precisa: A ponta centralizadora mantém a broca na posição correta, facilitando a perfuração e permitindo obter um furo uniforme. Esta característica é essencial para garantir a precisão e a qualidade dos furos, especialmente em projetos que exigem um acabamento impecável. Aplicações A Broca Fresa Forstner para Madeira Gross 70484255 é ideal para uma variedade de aplicações, incluindo: Fabricação de Móveis: Perfeita para criar furos cegos em peças de madeira, MDF e HDF, garantindo um acabamento liso e uniforme. Esta broca é essencial para marceneiros e fabricantes de móveis que buscam precisão e qualidade em seus projetos. Trabalhos de Acabamento: Ideal para trabalhos de acabamento que exigem furos precisos e de alta qualidade, proporcionando um resultado profissional e esteticamente agradável. Perfuração em Materiais Diversos: Útil para perfurações em madeira, MDF, HDF e outros materiais similares, oferecendo versatilidade e eficiência em diversas aplicações. Características Principais A Broca Fresa Forstner para Madeira Gross 70484255 possui um diâmetro de 42 mm e é fabricada em aço 45, garantindo resistência a cargas mecânicas. As placas de metal duro da liga VK8, com dureza de 86-92 HRC, proporcionam alta produtividade e longa vida útil. A haste cilíndrica facilita a fixação e a ponta centralizadora assegura perfurações precisas e uniformes. A Broca Fresa Forstner para Madeira Gross 70484255 é a escolha perfeita para quem busca uma ferramenta de alta qualidade e desempenho para perfurações em madeira e materiais similares. Com sua construção robusta e design funcional, esta broca atende às necessidades de marceneiros, fabricantes de móveis e entusiastas do DIY, proporcionando resultados precisos e eficientes em cada uso. Adquira já e experimente a diferença que a qualidade Gross pode fazer em seus projetos!', 37.16, 37.16, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fa-mh90zb4dkv7z1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F22494704004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296663838', 'Alicate Bico Chato Isolado 1.000 V 6'''' Tramontina PRO', 'Desenvolvido para prender e dobrar materiais, o alicate bico chato da Tramontina PRO é muito utilizado no segmento elétrico. Seu bico facilita o uso em locais de difícil acesso e possui sistema especial para pegar e prender objetos. A ferramenta certa para você que trabalha na indústria ou oficinas mecânicas. Forjado em aço cromo vanádio. Cabeça e articulação polidas. Têmpera total no corpo. Têmpera por indução no gume de corte.Isolação elétrica de 1.000 V CA.Produto em conformidade com a NBR9699 e NR10.DIN ISO 5745.Os alicates de corte são testados quanto à resistência ao desgaste do gume de corte em máquina de ensaio específica.Os alicates possuem dureza diferenciada no gume de corte e no corpo.Os alicates também são testados com relação à aderência das empunhaduras de PVC.Um ensaio de extrema importância analisa o grau de isolação do revestimento aplicado sobre os cabos dos alicates isolados, e que promove segurança na sua utilização em locais com tensões de até 1.000 V CA.Cortar, prender e dobrar cabos e arames.Ideal para eletroeletrônica.As ferramentas são produzidas e testadas conforme normas específicas.Desenvolvido para prender e dobrar materiais, o alicate bico chato da Tramontina PRO é muito utilizado no segmento elétrico. Seu bico facilita o uso em locais de difícil acesso e possui sistema especial para pegar e prender objetos. A ferramenta certa para você que trabalha na indústria ou oficinas mecânicas.', 71.9, 71.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-lkmdm970lpqw4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23296663838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
