INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259544506', 'Kit com 2 Gelatinas #todecacho Salon Line', 'O kit conta com a Gelatina #todecacho Alta Definição que proporciona cachos com definição máxima e brilho, além disso, conta com a gelatina líquida que possui pró vitamina B5 e colágeno, proporcionando cachos modelados da raiz as pontas. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos ondulados, cacheados e crespos. Qual a indicação? Para quem busca a finalização perfeita dos cachos. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Gelatina Líquida #todecacho Estilização 300ml Pró Vitamina B5: Contribui com o espessamento dos fios e para o combate das pontas duplas. Colágeno Vegetal: trata os fios de dentro para fora, pois penetra no fundo da fibra capilar e oferece nutrição e restauração. Gelatina Alta Definição #todecacho Profix Salon Line 320g Possui óleo de semente de uva e colágeno vegetal para os fios em sua fórmula que garantem retenção da hidratação, força e saúde. Além disso, aliados à tecnologia PROFIX, proporcionam definição máxima, combate ao frizz e brilho intenso. <>MODO DE USO$& Qual a melhor forma de usar? Com os cabelos limpos e úmidos, aplique a gelatina mecha a mecha, uniformemente no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. A aplicação ideal dependerá da quantidade e do comprimento dos fios. NÃO ENXÁGUE. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos do kit são veganos. É liberado? Todos os produtos são liberados.', 71.0, 39.36, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-820md-mng7mg16v1mo32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F58259544506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192588171', 'Óleo de Tratamento SOS Cachos Super Óleos 100ml', 'O Óleo de Tratamento Super Óleos S.O.S Cachos ajuda a hidratar, definir e nutrir os cachos, garantindo zero frizz, fim das pontas duplas e brilho extremo. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos cacheados e crespos. Qual a indicação? Para cabelos desidratados, desnutridos e com pontas duplas. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? O Óleo de Tratamento S.O.S Cachos é enriquecido com um mix de 12 óleos – óleo de argan, karité, algodão, coco, macadâmia, chá-verde, camomila, aloe vera, cálamo, mirra, oliva e canela – que promove nutrição extrema e fim das pontas duplas. Além disso, age no combate intenso contra o ressecamento e promove brilho intenso. <>MODO DE USO$& Qual a melhor forma de usar? Com o cabelo seco ou úmido, aplique algumas gotas do Óleo de Tratamento S.O.S Cachos na palma das mãos e espalhe bem do comprimento às pontas dos fios. Finalize como preferir. Sem enxágue. <>CARACTERÍSTICAS$& É produto vegano? O Óleo de Tratamento Super Óleos S.O.S Cachos não é vegano. É liberado? O Óleo de Tratamento Super Óleos S.O.S Cachos não é liberado.', 37.0, 31.5, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8259x-mfufeqec0i6lc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23192588171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256869100', 'Tênis Olympikus Qu4dra 2 Masculino', 'Tênis Olympikus Qu4dra 2 Masculino - Ideal para quem procura versatilidade no treino e no dia a dia, o Olympikus Quadra 2 oferece equilíbrio entre leveza e suporte. Seu cabedal traz gáspea em poliéster com sobreposição de tela, garantindo resistência e flexibilidade, com detalhes em laminado High Frequency que adicionam durabilidade e um acabamento contemporâneo. O atacador texturizado e o puxador traseiro facilitam o calce, enquanto o forro em poliéster com espuma proporciona conforto contínuo. A palmilha, em EVA e poliéster com aplicação gráfica, mantém os pés ventilados e estáveis, enquanto o solado em ELEVA PRO 2.0 assegura resiliência, conforto e responsividade. Além disso, conta também com a tecnologia ULTRAX, que é antiderrapante e confere maior resistência ao calçado. Nome: Tênis Olympikus Quadra 2 Masculino Gênero: Masculino Marca: Olympikus Indicado para: Jogo Características Gerais do Produto: • Gênero: Masculino Garantia: • 7 dias de garantia', 399.9, 399.9, NULL, 'Sports & Outdoors > Sports Footwear > Volleyball Shoes', 'https://cf.shopee.com.br/file/sg-11134201-8262g-mlrx099ftvk836', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1172340783%2F58256869100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
