INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53309964775', 'Vara De Pesca Telescópica 2,40m P/ Molinete Ryumar Summer Fibra De Vidro Leve E Resistente Pesca Iniciante Promoção', 'Vara de Pesca Telescópica Ryumar 2,40m p/ Molinete Summer Fibra Vidro Leve e Resistente Pesca Iniciante Promoção A vara telescópica para molinete Ryumar Summer é uma opção acessível pensada para quem quer começar na pesca ou ter um equipamento reserva sem investir alto. Entrega um bom desempenho dentro da sua proposta, sendo ideal para pescarias leves com ótimo custo-benefício. Sua ponta fina proporciona boa sensibilidade, ajudando a perceber fisgadas com mais facilidade, enquanto a cor vibrante auxilia na visualização durante o uso, trazendo mais praticidade na pescaria. Fabricada em fibra de vidro, atende bem a usos ocasionais e pescarias em lagos, rios, pesqueiros e represas. É uma vara leve, fácil de transportar e simples de utilizar, perfeita para quem busca funcionalidade sem complicação e sempre pronta para uso. ESPECIFICAÇÕES: Marca: Summer Modelo: Ryumar 240 Tamanho aberto: 2,40 m Tamanho fechado: 50 cm Peso da isca: 40-80 g Material: Fibra de vidro Peso: 144 g Passadores: 4 + 1 ponteira Cor: Sortida, conforme disponibilidade em estoque. Fotos ilustrativas para destacar os detalhes do produto.', 48.9, 48.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-820ly-mnzp1i75s3ya3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F53309964775', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
