INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899072309', 'Cera Cremosa Colorida na Cor Branca 250ml Original Pérola', 'Este anúncio contém: 1 (uma) Cera colorida branca original da marca Pérola. Código do Fabricante: 161604; Código Universal: 7896067721452. Desenvolvido com alta tecnologia, a Cera Cremosa Colorida Pérola é formulada com tintas e vernizes de última geração para tornar seu veículo encerado com brilho e protegido contra raios solares UV. Seus principais benefícios são realçar a cor original e criar uma película protetora contra o Sol. Modo de Uso: 1 - Agite o frasco. O veículo deve estar frio e na sombra. Se a pintura estiver áspera, fosca ou com pequenos arranhões, é necessário polir antes de encerar; 2 - Com o Algodão Pérola, aplique uma pequena quantidade do produto espalhando a cera uniformemente. Comece pelo teto do veículo dividindo em partes pequenas; 3 - Use Algodão Pérola friccionando com movimentos horizontais e finalize suavemente com movimentos circulares; 4 - Deixe secar por 2 minutos e limpe com Algodão Pérola ou Toalha de Microfibra Pérola. Você notará um brilho rápido que realçará a cor da pintura. Dúvidas frequentes: Trabalhamos apenas com produtos novos e com garantia; Produto à pronta entrega; Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma autopeças fundada em 1980. Atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidores finais. Não encontrou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 40.74, 40.74, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mifzkin8to8y55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F19899072309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699338096', 'Bandeja Balança Dianteira Inferior LE Perfect March Versa', 'Este anúncio contém: 1 (uma) Bandeja dianteira inferior esquerda (motorista) original da marca Perfect. Especificações: Possui Buchas: Sim; Possui Pivô: Sim. Código do Fabricante: BDJ2045; Código Universal: 7899152500833; Conversão: NBJ6003EP/SB8291EP. Atenção: Fotos reais do produto, compre apenas tendo certeza que serve para seu veículo. Aplicável nos seguintes veículos: Montadora: Nissan; Veículo: March; Motor: 1.0 / 1.6; Ano de fabricação: 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019 e 2020. Montadora: Nissan; Veículo: Versa; Motor: 1.6 16v; Ano de fabricação: 2011, 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019 e 2020. Sobre o Produto: A bandeja (ou braço oscilante) é um componente do sistema de suspensão dos veículos. Ela trabalha com os demais componentes de suspensão, ligando a roda ao chassi do veículo. Sua construção é formada por sua estrutura estampada, forjada ou fundida, buchas, pivô e mancais. Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 227.49, 213.85, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lynmlx0uf8np0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F18699338096', NULL, NULL, '2026-07-