INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203132736', 'L''Oréal Professionnel Serie Expert Absolut Repair Omega-9 + Protein - Máscara Capilar 500g', 'Máscara de tratamento para cabelos danificados. L''Oréal Professionnel Serie Expert Absolut Repair Omega-6 + Protein faz uma restauração completa nos fios para devolver saúde e brilho ao cabelo. A Máscara Capilar L''Oréal Professionnel Serie Expert Absolut Repair Omega-6 + Protein proporciona um tratamento de reestruturação intensivo que atua na reparação da fibra capilar extremamente fragilizada para que o cabelo revele uma aparência mais saudável. Seus fios ganham muito mais brilho e um toque macio incrível. Como usar: Espalhe a máscara Absolut Repair, de L''Oréal, no cabelo limpo e úmido, nos comprimentos e pontas. Deixe agir por cerca de 5 minutos e enxágue. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 334.9, 233.1, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260t-mjydfpxmc8hv6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58203132736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
