INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697079966', 'Tambor Freio A20 Blazer S10 85/97 Tras S/cubo Hipperfreios', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação Aplicação: A20 - 1985 até 1992 Blazer - 1995 até 1997 S10 - 1995 até 1997 Conteúdo Da Embalagem 1 Tambor de Freio Diâmetro Centro Externo 322,00 mm Diâmetro Máximo 281,50 mm Altura Total 93,00 mm Largura de Pista 74,50 mm Tipo de Veículo para Carros Marca A HIPPER FREIOS é líder no mercado em fornecimento de discos e tambores de freio. A marca distribui seus produtos para todo território nacional e exporta para mais de 20 países.Atualmente a HIPPER FREIOS conta com mais de 1.200 referências para as mais diversas aplicações nacionais e importadas através de suas linhas de produtos e sistemas de freios automotivos (Disco, Tambor e Cubo). Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia - 3 meses Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Valor unitário EAN 7898318870445 Espessura Mínima da Pista 90,50 mm Código do Fabricante HF368 Posição Traseiro Cubo Sem Posição Traseiro', 227.69, 227.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rbmi-lo6vxkskffof51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F23697079966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
