INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13511253334', 'Jogo De 7 Bits Com Adaptador Magnético De Aço - Mtx 113929', '-Descrição: -O jogo de bits da MTX são produzidos de aço inoxidável 45H, combinando alta dureza (53-54 HRC), além de contarem com um adaptador magnético e bits de aparafusamento intercambiáveis. -Características: - Encaixe sextavado 1/4". - Indicado para manutenção de relógios, óculos e componentes eletrônicos em geral. -Informações Técnicas: - Material do Bits ponteira : Aço carbono; - Acabamento do Bits : Fosfatizado; - Tipo do encaixe do bits : Sextavado - 1/4".Jogo composto por:7 - Bits;1 - Adaptador Magnético de Aço. -Cuidados com o produto: - Posicionamento da parafusadeira de forma inclinada com o eixo de giro do parafuso, isto provoca atrito entre o parafuso e a ponta, provocando desgaste. - Acionamento da parafusadeira antes de estar com a ponta perfeitamente encaixada no parafuso, provocando desgaste por escorregamento, a ponta fica com um “bico” em sua extremidade. - Uso de torque excessivamente alto, parafusadeira mal regulada, rotações muito elevadas, uso de parafusadeiras de impacto, uso de furadeiras e etc., provocam a quebra prematura das pontas. SKU: 10354 Distribuição por Ismafer Ferramentas.', 27.23, 27.23, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/2bdaa19093a65e077cfaacf0649b2001', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F13511253334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
