INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593805275', 'Serra copo bimetal 35 mm para metais - 724359 MTX', 'Produto: Serra copo bimetal 35 mm para metais - 724359 Marca: MTX Descrição: A Serra copo bimetal 35 mm para metais 724359 da MTX é ideal para profissionais exigentes que buscam qualidade superior em suas ferramentas. Com diâmetro de 35 mm, esta serra copo é perfeita para cortar uma ampla variedade de materiais, desde metais ferrosos e não ferrosos até plásticos, tornando-a uma opção versátil para qualquer caixa de ferramentas. Características: • Fabricação de Alta Qualidade: Construída com aço carbono de alta resistência e dentes de aço de alta velocidade (HSS), a Serra Copo MTX assegura cortes rápidos e limpos, maximizando sua produtividade em campo. • Corte Preciso e Eficiente: Equipada com dentes fixados por soldagem elétrica, a ferramenta oferece uma união robusta e confiável, proporcionando segurança e precisão mesmo sob pressão intensa de uso. • Design Otimizado para Facilidade de Uso: O design compacto e eficiente permite que você realize trabalhos de instalação elétrica e de sistemas de comunicação com rapidez e sem esforço, tornando o processo de perfuração mais ágil e menos cansativo. • Durabilidade: A durabilidade superior deste modelo garante que você poderá contar com uma ferramenta confiável por muito tempo, reduzindo a necessidade de substituições frequentes e proporcionando um excelente retorno sobre o investimento. Escolha a Serra Copo MTX BIMETAL 724359 para garantir resultados profissionais em seus projetos. Perfeita para eletricistas, instaladores e hobbistas que não abrem mão de ferramentas de alta performance. Especificações: Material: Aço carbono 6 dentes por polegada Lâmina bimetálica: sim" Uso Indicado: " metais, plásticos, alumínio e inox Dentes travados: sim" Não acompanha suporte. Dimensões (C x L x A): 6.20 x 3.30 x 3.30 centímetros Peso: 0.10 Kg', 40.41, 40.41, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mr4xcgqn6ups04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F23593805275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998371628', 'Sandália Feminina Papete Moleca Chinelo Flat Brilho', 'Sandália Moleca Tira Tripla All Black – Feminina - Elegância e conforto para brilhar no dia a dia! Ficha Técnica: Gênero: Feminino Indicado para: Dia a Dia Composição: EVA Composição Tira: Napa com Strass Solado: Borracha Salto Flatform: Aproximadamente 2cm de altura Cor: Preto com detalhes em strass Marca: Moleca Conteúdo da embalagem: 1 par de Sandália Moleca Tira Tripla All Black - Feminina A Sandália Moleca Tira Tripla é a escolha perfeita para quem busca sofisticação e conforto. Com tiras adornadas com aplicações de strass, esta sandália traz um toque de brilho ao seu visual. Sua palmilha em EVA proporciona um ajuste confortável, ideal para longas horas de uso. O solado em borracha antiderrapante garante segurança em cada passo. Versátil e moderna, ela combina com diversos looks, tornando-se uma peça essencial para o seu dia a dia.', 129.99, 58.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7repa-m8b9gmcq28pzc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F23998371628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206487923', 'Aparador de cerca viva elétrico 450 watts 500mm CC500 Tekna', 'Produto: Aparador de cerca viva elétrico 450 watts 500mm CC500 Tekna Marca: Tekna Descrição: Com design inovador, o Aparador de cerca viva elétrico 450 watts 500mm CC500 da Tekna foi projetado para ser prático e fácil de usar. Leve, potente e compacto, tem lâmina de duplo corte, que proporciona maior desempenho e menor esforço do operador. O CC500 é prático e eficiente, pois conta com uma lâmina de 500 mm de comprimento com dentes afiados em ambos os lados, que cortam nos dois sentidos, permitindo realizar até 3800 golpes por minuto. É ideal para cortar e nivelar vegetações, arbustos, árvores e cercas vivas. Possui sistema bi-manual que só aciona a lâmina ao pressionar dois botões ao mesmo tempo, garantindo a segurança ao operador. Com uma potência de 450 W, proporciona um ótimo rendimento no trabalho, sem deixar de lado a ergonomia e conforto no manuseio. Características: • Lâmina Dupla com Dentes de Duplo Corte; • Sistema Bi-Manual de Segurança; • Saia de Proteção; • Potência de 450 W; • Lâmina de 500 mm; • Diâmetro máximo de corte de 18 mm; • 3800 Golpes por minuto. Especificações: Motor: Universal com Escovas Potência: 450W Frequência: 60Hz Sistema de Corte: Lâmina Dupla com dentes de Corte Duplo Golpes por Minuto: 3800GPM Comprimento Lâmina: 500mm Diâmetro Máx. Corte: 18mm Nível de Pressão Sonora (Lpa): 84,33dB (A) Nível de Potência Sonora (Lwa): 95,06 db (A) Classe de Isolamento: Classe II Protetor de Lâmina: Sim. Itens Inclusos: Protetor de Lâmina. Peso: 2.50 Kg', 351.23, 289.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-82588-mqxr2isfcowc56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F58206487923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
