INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16173924873', 'Martelete combinado 800W M8701B c/ acessórios Makita', 'Produto: Martelete combinado 800W M8701B c/ acessórios Makita Marca: Makita Descrição: Kit Martelete perfurador e rompedor 800 watts 2,3 joules M8701B + ponteiro e talhadeira O Martelete Perfurador e Rompedor 800W 2,3 joules SDS Plus com maleta M8701B da Makita é ideal para trabalhos profissionais em setores de construção, manutenção, montagem etc. Possui 3 modos de operação: simples impacto, rotação com impacto e simples rotação. Rotação e torque iguais em ambos sentidos. O M8701B possui alta potencia de 800 watts, energia de impacto de 2,3 joules, velocidade variável de até 1.200 rpm, realiza até 4.500 impactos por minuto. Encaixe SDS PLUS. Além disso o Martelete M8701B é acompanhado de Punho lateral, limitador de profundidade e maleta. Ponteiro de 250 mm encaixe "SDS-PLUS" Para demolição de concreto. Encaixe: SDS-PLUS Talhadeira 250 mm encaixe Sds Plus Indicada para lascar, canalizar e romper pedaços grandes de concreto Encaixe: SDS-PLUS. Especificações: Capacidade de perfuração em aço: 13mm Capacidade de perfuração em concreto: 26 mm Capacidade de perfuração em madeira: 32 mm Energia em Joules: 2,3 J Função perfurador: Sim Função rompedor: Sim Impacto por minuto: 4500 IPM Potência: 800 watts Rotação máxima: 1200 RPM Encaixe: SDS Plus Itens Inclusos: Punho lateral Limitador de profundidade Maleta. Ponteiro de 250 mm encaixe Sds Plus Talhadeira 250 mm encaixe Sds Plus Dimensões (C x L x A): 19.40 x 7.10 x 36.20 centímetros Peso: 2.70 Kg', 930.43, 930.43, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-mbxznd0655i22d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F16173924873', NULL, NULL, '2026-07-28T0