INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698999040', 'Filtro Combustível Hyundai Hb20 2012 a 2017 - 191699 - FCI1630', 'Filtro Combustível Hyundai Hb20 2012 a 2017 191699 FCI1630 (Comfort/Premiun/S/SX) - 1.6 16v Flex - (Plástico Preto) (Ø Externo - 55mm /Altura - 143mm) (Blindado) (2 Bicos) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 25.94, 25.94, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-lmqnflukla3e06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21698999040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
