INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12481402589', 'Medidor de contorno 150 mm - Cortag', 'Produto: Medidor de contorno 150 mm Marca: Cortag Descrição: A Eficiência do Medidor de Contorno 150 mm da Cortag! Esta ferramenta inovadora é essencial para profissionais que trabalham com carpintaria, instalação de ladrilhos, laminação e carpetes, além de ser perfeita para moldagem e outras verificações de dimensões. Com o Medidor de Contorno 150 mm da Cortag, você pode facilmente transferir contornos de superfícies irregulares, melhorando a precisão do seu trabalho e economizando tempo. Características: • Fácil de Usar: Copie contornos com exatidão unilateral, sem a necessidade de ajustes complicados. • Material Durável: Construído com materiais de alta qualidade, garantindo resistência e longevidade ao produto. • Versátil: Ideal para uma variedade de aplicações, desde montagem de ladrilhos até customização de carpetes. • Compacto e Portátil: Com apenas 150 mm (6 polegadas), é fácil de transportar e se adapta a pequenos espaços de trabalho. Especificações: Tipo: 6" - 150 mm. Dimensões (C x L x A): 17.10 x 10.00 x 2.10 centímetros Peso: 0.21 Kg', 102.25, 75.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82587-mr3pysej6txec7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F12481402589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797455860', 'Mangueira Radiador Gm Astra 1999 a 2001 - 186368 - 117518', 'Mangueira Radiador Gm Astra 1999 a 2001 186368 117518 Reservatório Exp. Rad. 1.8 8v MPFI O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 40.76, 40.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm5-ln3ejuq7fwmvfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21797455860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998142761', 'Módulo Cozinha Henn Americana Tampo p/ Balcão 120cm Calcare', 'Tampo p/ Balcão Cozinha 120x53cm Calcare - Henn Marca: Henn Dimensões(Cm): Comprimento(Profundidade): 54cm x Largura: 120cm x Altura: 3cm Material de Estrutura - MDP/BP Espessura da Estrutura do Tampo - Tampo c/ 25mm Certificação de Qualidade - Certificação de Qualidade Aprovada Garantia - 3 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 204.91, 194.67, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7ra2t-m55uqe26dg8wc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F22998142761', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397064739', 'Filtro Ar Ford Escort 1996 a 2002 - 6664 - FAP4831', 'Filtro Ar Ford Escort 1996 a 2002 6664 FAP4831 (GL) - Motor 1.6 8v Zetec /(GL/GLX/L/RS) - Motor 1.8 16v Zetec Após passar pelo filtro, o ar é aspirado pelo motor através de seus êmbolos (pistões). Durante este processo, sensores do sistema de injeção eletrônica enviam sinais para o Módulo da Injeção Eletrônica do Veículo, informando a temperatura do ar que está sendo admitido. O filtro do ar é construído para que as impurezas em suspensão no ar sejam separadas, ficando as mais pesadas depositadas no fundo da caixa de filtração e as mais leves sendo retidas pelo elemento filtrante.', 36.35, 36.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rblw-lmxq6sgxkq2tdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22397064739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
