INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46962684298', 'Triplo Imuno Vitamina C, D E Zinco 30 Comp Catarinense', 'Triplo Imuno Catarinense Nutrição – Vitamina C + Vitamina D + Zinco O Triplo Imuno Catarinense Nutrição foi desenvolvido para auxiliar o funcionamento do sistema imunológico e contribuir para a saúde e bem-estar no dia a dia. Sua fórmula combina Vitamina C, Vitamina D e Zinco, nutrientes essenciais para fortalecer as defesas do organismo. ✨ Principais Benefícios: 🛡️ Auxilia no funcionamento do sistema imunológico 💪 Contribui para a saúde de ossos, músculos e dentes 🌟 Ação antioxidante contra os radicais livres 💇 Auxilia na manutenção da pele, cabelos e unhas 👀 O zinco contribui para a saúde da visão ⚡ Auxilia no metabolismo energético 🦴 Contribui para a absorção de cálcio e fósforo 🧬 Participa da síntese de proteínas e divisão celular ✅ Com Vitamina C, Vitamina D e Zinco ✅ Sem glúten ✅ Sem lactose ✅ Indicado para adultos (+19 anos) 🛒 Compre com segurança na Armazém Pura Saúde, sua loja especializada em saúde, suplementação e qualidade de vida. 📦 Conteúdo: • 01 Triplo Imuno Catarinense Nutrição ⚠️ Este produto não é medicamento. Seu consumo deve estar associado a uma alimentação equilibrada e hábitos de vida saudáveis. Não exceder a recomendação diária indicada na embalagem.', 78.0, 78.0, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820lm-mptcz7lrzo5e38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1346435001%2F46962684298', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57812597104', 'Newpet Bomba Motor Bebedouro Fonte de Água Sem Ruído Pet Gatos para bebedouro NP895/NP892 -Bivolt', 'Características: [Ampla compatibilidade] Bomba universal para bebedouros de animais de estimação, adequada para a maioria dos bebedouros automáticos para animais de estimação. [Baixo ruído] Motor sem escova com fonte de alimentação de 5 VCC, o som é inferior a 40 dB, economiza energia e é silencioso, não perturbando o sono do animal de estimação. [Fonte de alimentação USB] Fácil de ser alimentado por laptop, banco de energia, adaptador de energia, tomada USB e outros, plug and play. [Longa vida útil] Feito de plástico premium, à prova d''água IP68, durável para uso; fácil de limpar com escova (não incluída, recomendada a cada 2 semanas). [Luz indicadora de LED] Com luz indicadora de LED, fica automaticamente vermelha quando o nível de água está baixo, lembrando-o de adicionar água a tempo. Especificações: Cor:azul e preto Material:Plástico Tensão de funcionamento:DC 5V Corrente de carga:280mA Potência da carga:1,5 W Maior altura de içamento:50 cm Taxa de fluxo máxima:160L/H Diâmetro de saída:10,5 mm Vida útil contínua:10000 horas Ruído:40dB Grau de impermeabilidade:IP68 Temperatura de trabalho:0-60/ 0-100 Indicador LED: Vermelho:aviso de nível baixo de água e desligamento Azul: Funcionamento normal Comprimento do cabo: 150 cm/ 4,9 pés (com plugue DC5.5 x 2.1) Tamanho do produto:4,3 x 4,3 x2,8 cm/ 1,6 x 1,6 x1,1 polegada Peso do produto:120g/ 4,2oz Observação: Consulte o modelo da bomba da fonte de água antes de comprar: DR-DC160. As fontes de água e a escova mostradas nas fotos não estão incluídas. Lista de pacotes: 1 x Bomba para fonte de água', 76.95, 39.98, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mpro811368leb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F995716400%2F57812597104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
