INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56808128952', 'Jogo de Alicate para Anéis Sata Interno e Externo Retenção 5 Peças ST09251SJ', '- PRODUTO ORIGINAL; - ENVIO IMEDIATO; - ENVIADO COM NOTA FISCAL E GARANTIA; Jogo Alicates Anéis de Retenção 5 Peças - ST09251SJ Extremamente prático, apenas um alicate fazer a troca de vários tipos de anéis internos e externos com segurança trocando apenas sua ponta.Fabricados em Aço Cromo-Vanádio (Cr-V) para maior durabilidade e resistencia suas pontas foram projetados com 4 cabeças intercambiáveis com tratamento termico especial e acabamento oxigado negro. Seu cabo ergonomico possui mola para reduzir a fadiga no uso e acompanha estojo com tampa transparente para a acomodação das peças. Detalhes Jogo de 5 peças de alicate para anel de retenção para instalação e remoção de anéis internos e externos; Projetado com 4 cabeças intercambiáveis Praticidade: troca fácil da cabeça. Podem ser utilizadas tanto para abrir quanto para fechar anéis. Detalhes Jogo de 5 peças de alicate para anel de retenção para instalação e remoção de anéis internos e externos; Projetado com 4 cabeças intercambiáveis Praticidade: troca fácil da cabeça. Podem ser utilizadas tanto para abrir quanto para fechar anéis. Possui mola para reduzir a fadiga no uso. Agarre confortável para menor fadiga do usuário. Fabricados em Aço Cromo-Vanádio (Cr-V) para maior durabilidade e resistencia. Acompanha estojo com tampa transparente para a acomodação das peças Composição1 Corpo do alicate com cabo ergonômico02 Pontas tipo curvos:01 com ângulo de 45°01 com ângulo de 90°02 Pontas retas:01 com ponta de 1,5 mm01 com ponta de 2 mm', 119.98, 119.98, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820m6-mmkacci9z7yc22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.