INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57113782825', 'O menino que queria ser Deus | Yago Martins', 'Dandam tem seis anos e já sabe que o mundo tem coisas ruins que não deveriam existir. Sabe porque viveu. O pai foi embora. A vovó morreu. O cachorro sumiu. E ninguém consegue responder de um jeito que faça sentido. Então Dandam decide que, se Deus não vai consertar, ele mesmo vai. Ele quer ser Deus. Escrito por Yago Martins e ilustrado por Rogério Coelho com a delicadeza que lhe rendeu dois Prêmios Jabuti, O menino que queria ser Deus enfrenta de frente a questão mais antiga da fé: como confiar em Deus quando a dor é real e as respostas são insuficientes. Título: O menino que queria ser Deus Autor: Yago Martins Páginas: 80 Formato: 17 x 23 cm Edição: 2026 Capa: Dura Peso: 0,300 kg. ISBN: 9786559885961 Editora: Mundo Cristão', 49.9, 49.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mqi4sekf6uq452', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F57113782825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
