INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199891848', 'Forminha para Doce e Brigadeiro N5 Marrom 1000 Unid.', 'Produzida em papel impermeável, a Forminha Gourmet N5 tem o lado de fora e de dentro na mesma cor: Marrom. Ideal para acomodar docinhos já decorados com até 16g cada. Combina com todos os temas, a decoração de sua mesa de festa ficará mais elegante e personalizada.Confeccionada em papel atóxico de alta qualidade, impermeável e resistente à gordura, o que oferece mais resistência e durabilidade aos seus docinhos. A embalagem possui 1000 unidades.', 54.14, 42.77, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-824j0-mepwa6jmwgzqb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F20199891848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393516388', 'Salgadinho Torcida Queijo 60g Lucky', 'Dê um toque de sabor e diversão ao seu dia com o Salgadinho Torcida Sabor Queijo 60g. Crocante e irresistível, ele é perfeito para qualquer momento: um lanche rápido, acompanhar suas séries favoritas ou compartilhar com os amigos. Feito com ingredientes de qualidade, o sabor queijo é um clássico que agrada a todos. Sabor marcante de queijo. Tamanho ideal para levar onde quiser. Perfeito para qualquer ocasião. Experimente e descubra por que Torcida é o salgadinho favorito dos brasileiros! Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 8.99, 8.99, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2cjkfkmd9ip8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F23393516388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
